TURATH_CHUNK(82,[{"num":16400,"demo":false,"sanad":"","matn":["عن أنس بْنِ مَالِكٍ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: يَخْرُجُ قَوْمٌ مِنَ النَّارِ بَعْدَ مَا مَسَّهُمْ مِنْهَا سَفْعٌ، فَيَدْخُلُونَ الْجَنَّةَ، فَيُسَمِّيهِمْ أَهْلُ الْجَنَّةِ الْجَهَنَّمِيِّينَ.","وفي لفظ: لَيُصِيبَنَّ أَقْوَامًا سَفْعٌ مِنَ النَّارِ بِذُنُوبٍ أَصَابُوهَا عُقُوبَةً، ثُمَّ يُدْخِلُهُمُ اللَّهُ الْجَنَّةَ بِفَضْلِ رَحْمَتِهِ، يُقَالُ لَهُمْ الْجَهَنَّمِيُّونَ."],"takhrij":"صحيح: رواه البخاريّ في الرقاق (6559) عن هدبة بن خالد، حدّثنا همّام، عن قتادة، حدّثنا أنس بن مالك، فذكره باللفظ الأول.","grade":"صحيح","chapter_ar":"باب أهل الجنة الذين يقال لهم: الجهنميون","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (6559), and also (7450) with the second wording.","chapter_en":"The People of Paradise Who Will Be Called “al-Jahannamiyyūn”","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise","part_no":67,"group_no":2,"chapter_no":20,"content":{"translation":{"en":["Anas ibn Mālik narrated that the Prophet ﷺ said: “Some people will be brought out of the Fire after being scorched by it, then they will enter Paradise. The people of Paradise will call them ‘al-Jahannamiyyūn.’” In another wording: “Some people will certainly be scorched by the Fire as punishment for sins they committed. Then Allah will admit them into Paradise by the bounty of His mercy, and they will be called ‘al-Jahannamiyyūn.’”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (6559، 7450) باللفظ الثاني."},{"num":16401,"demo":false,"sanad":"","matn":["عن عِمْرَانَ بْنِ حُصَيْنٍ، رَضِيَ اللَّهُ عَنْهُمَا عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: يَخْرُجُ قَوْمٌ مِنَ النَّارِ بِشَفَاعَةِ مُحَمَّدٍ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَيَدْخُلُونَ الْجَنَّةَ، يُسَمَّوْنَ الْجَهَنَّمِيِّينَ."],"takhrij":"صحيح: رواه البخاريّ في الرّقاق (6566) عن مسدّد، حدّثنا يحيى، عن الحسن بن ذكوان، حدّثنا أبو رجاء، حدّثنا عمران بن حصين، فذكره.","grade":"صحيح","chapter_ar":"باب أهل الجنة الذين يقال لهم: الجهنميون","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (6566).","chapter_en":"The People of Paradise Who Will Be Called “al-Jahannamiyyūn”","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise","part_no":67,"group_no":2,"chapter_no":20,"content":{"translation":{"en":["ʿImrān ibn Ḥuṣayn narrated that the Prophet ﷺ said: “People will be brought out of the Fire through the intercession of Muḥammad ﷺ and will enter Paradise. They will be called al-Jahannamiyyūn.”"]}},"tuhfa":{},"full":1,"rep":[899,16186],"tks":"صحيح: رواه البخاري (6566)."},{"num":16402,"demo":false,"sanad":"","matn":["عن ابْنِ مَسْعُودٍ، حَدَّثَهُمْ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: يَكُونُ فِي النَّارِ قَوْمٌ مَا شَاءَ اللَّهُ، ثُمَّ يَرْحَمُهُمُ اللَّهُ فَيُخْرِجُهُمْ، فَيَكُونُونَ فِي أَدْنَى الْجَنَّةِ، فَيَغْتَسِلُونَ فِي نَهْرِ الْحَيَاةِ، وَيُسَمِّيهِمْ أَهْلُ الْجَنَّةِ الْجَهَنَّمِيِّينَ، لَوْ أَضَافَ أَحَدُهُمْ أَهْلَ الدُّنْيَا لَأَطْعَمَهُمْ وَسَقَاهُمْ، وَلَحَفَهُمْ وَفَرَشَهُمْ قَالَ: وَأَحْسَبُهُ قَالَ: وَزَوَّجَهُمْ لَا يَنْقُصُ ذَلِكَ مِمَّا عِنْدَهُ شَيْئًا."],"takhrij":"صحيح: رواه أحمد (4337)، وأبو يعلى (4979) – واللفظ له-، وابن حبان (7428)، وأبو نعيم في صفة الجنة (448) كلهم من طرق عن حماد بن سلمة، عن عطاء بن السائب، عن عمرو بن ميمون، عن ابن مسعود، فذكره.","grade":"صحيح","chapter_ar":"باب أهل الجنة الذين يقال لهم: الجهنميون","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by Aḥmad (4337), Abū Yaʿlā (4979), whose wording this is, Ibn Ḥibbān (7428), and Abū Nuʿaym in Ṣifat al-Jannah (448).","chapter_en":"The People of Paradise Who Will Be Called “al-Jahannamiyyūn”","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise","part_no":67,"group_no":2,"chapter_no":20,"content":{"translation":{"en":["Ibn Masʿūd narrated that the Messenger of Allah ﷺ said: “Some people will remain in the Fire for as long as Allah wills. Then Allah will have mercy upon them and bring them out. They will be placed in the lowest part of Paradise and will bathe in the River of Life. The people of Paradise will call them al-Jahannamiyyūn. If one of them were to host all the people of the world, he would be able to feed them, give them drink, provide them with coverings, and furnish them.” The narrator said: I think he also said: “And provide them with spouses, without any of what he possesses being diminished.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (4337)، وأبو يعلى (4979) - واللفظ له -، وابن حبان (7428)، وأبو نعيم في صفة الجنة (448)."},{"num":16403,"demo":false,"sanad":"","matn":["عن حماد بن زَيْدٍ، عن عَمْرِو بْنِ دِينَارٍ، عَنِ جابر، أنّ النّبيّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: يَخْرُجُ مِنَ النَّارِ بِالشَّفَاعَةِ كَأَنَّهُمُ الثَّعَارِيرُ. . قُلْتُ: مَا الثَّعَارِيرُ؟ قَالَ: الضَّغَابِيسُ. وَكَانَ قَدْ سَقَطَ فَمُهُ. فَقُلْتُ لِعَمْرِو بْنِ دِينَارٍ: أَبَا مُحَمَّدٍ، سَمِعْتَ جَابِرَ بْنَ عَبْدِ اللَّهِ يَقُولُ: سَمِعْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: يَخْرُجُ بِالشَّفَاعَةِ مِنَ النَّارِ. قَالَ: نَعَمْ.","وفي لفظ عن حماد بن زيد قال: قلت لعمرو بن دينار: أسمعتَ جابر بن عبد الله يقول: سمعتُ النّبيَّ صلى الله عليه وسلم يقول: إن الله يخرج قوما من النّار بالشّفاعة؟ قال: نعم."],"takhrij":"متفق عليه: رواه البخاريّ في الرّقاق (6558)، عن أبي النعمان، عن حماد بن زيد، فذكره بالسياق الأول.","grade":"متفق عليه","chapter_ar":"باب أهل الجنة الذين يقال لهم: الجهنميون","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6558) and Muslim (318 :191).","chapter_en":"The People of Paradise Who Will Be Called “al-Jahannamiyyūn”","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise","part_no":67,"group_no":2,"chapter_no":20,"content":{"translation":{"en":["Ḥammād ibn Zayd narrated from ʿAmr ibn Dīnār, from Jābir, that the Prophet ﷺ said: “People will be brought out of the Fire through intercession, looking like small shoots.” The narrator asked: “What are al-thaʿārīr?” He replied: “Tender plant shoots.” His teeth had fallen out, affecting his pronunciation. I asked ʿAmr ibn Dīnār: “O Abū Muḥammad, did you hear Jābir ibn ʿAbdullāh say that he heard the Prophet ﷺ say: ‘People will be brought out of the Fire through intercession’?” He replied: “Yes.” In another wording, Ḥammād ibn Zayd said: I asked ʿAmr ibn Dīnār: “Did you hear Jābir ibn ʿAbdullāh say that he heard the Prophet ﷺ say: ‘Allah will bring people out of the Fire through intercession’?” He replied: “Yes.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (6558)، ومسلم (318 :191)."},{"num":16404,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ، رَضِيَ اللَّهُ عَنْهُ أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِذَا دَخَلَ أَهْلُ الْجَنَّةِ الْجَنَّةَ، وَأَهْلُ النَّارِ النَّارَ، يَقُولُ اللَّهُ: مَنْ كَانَ فِي قَلْبِهِ مِثْقَالُ حَبَّةٍ مِنْ خَرْدَلٍ مِنْ إِيمَانٍ فَأَخْرِجُوهُ. فَيُخْرَجُونَ قَدِ امْتُحِشُوا وَعَادُوا حُمَمًا، فَيُلْقَوْنَ فِي نَهَرِ الْحَيَاةِ، فَيَنْبُتُونَ كَمَا تَنْبُتُ الْحِبَّةُ فِي حَمِيلِ السَّيْلِ ـ أَوْ قَالَ: ـ حَمِيَّةِ السَّيْلِ. وَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَلَمْ تَرَوْا أَنَّهَا تَنْبُتُ صَفْرَاءَ مُلْتَوِيَةً."],"takhrij":"متفق عليه: رواه البخاري في الرقاق (6560)، ومسلم في الإيمان (184) كلاهما من طريق عمرو بن يحيى بن عمارة، عن أبيه، عن أبي سعيد فذكره.","grade":"متفق عليه","chapter_ar":"باب أهل الجنة الذين يقال لهم: الجهنميون","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6560) and Muslim (184).","chapter_en":"The People of Paradise Who Will Be Called “al-Jahannamiyyūn”","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise","part_no":67,"group_no":2,"chapter_no":20,"content":{"translation":{"en":["Abū Saʿīd al-Khudrī narrated that the Prophet ﷺ said: “When the people of Paradise have entered Paradise and the people of the Fire have entered the Fire, Allah will say: ‘Bring out whoever has in his heart faith equal to the weight of a mustard seed.’ They will be brought out after having been completely charred and turned to coal. Then they will be cast into the River of Life and will grow just as a seed grows in the sediment carried by a flood.” The Prophet ﷺ said: “Have you not seen how it emerges yellow and twisted?”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (6560)، ومسلم (184)."},{"num":16405,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي حَدِيثِ الرؤية الطويل: إِذَا فَرَغَ اللَّهُ مِنَ الْقَضَاءِ بَيْنَ الْعِبَادِ، وَأَرَادَ أَنْ يُخْرِجَ بِرَحْمَتِهِ مَنْ أَرَادَ مِنْ أَهْلِ النَّارِ، أَمَرَ الْمَلَائِكَةَ أَنْ يُخْرِجُوا مِنَ النَّارِ مَنْ كَانَ لَا يُشْرِكُ بِاللهِ شَيْئًا مِمَّنْ أَرَادَ اللَّهُ تَعَالَى أَنْ يَرْحَمَهُ مِمَّنْ يَقُولُ: لَا إِلَهَ إِلَّا اللَّهُ، فَيَعْرِفُونَهُمْ فِي النَّار، يَعْرِفُونَهُمْ بِأَثَرِ السُّجُودِ، تَأْكُلُ النّارُ مِنَ ابنِ آدَمَ إلاّ أَثَرَ السُّجُودِ، حرَّم اللَّهُ عَلَى النَّارِ أَنْ تَأْكُلَ أَثَرَ السُّجُودِ، فيُخْرجُون مِنَ النَّارِ وَقَدِ امْتَحَشُوا، فَيُصَبُّ عَلَيْهِمْ ماءُ الْحَيَاةِ، فَيَنْبُتُون مِنْهُ كَمَا تَنْبُتُ الحبَّةُ فِي حَمِيل السَّيْل.... الحديث."],"takhrij":"متفق عليه: رواه البخاريّ في التوحيد (7437)، ومسلم في الإيمان (182) كلاهما من حديث إبراهيم بن سعد، عن ابن شهاب، عن عطاء بن يزيد اللّيثيّ، أنّ أبا هريرة، فذكره في حديث طويل.","grade":"متفق عليه","chapter_ar":"باب أهل الجنة الذين يقال لهم: الجهنميون","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (7437) and Muslim (182).","chapter_en":"The People of Paradise Who Will Be Called “al-Jahannamiyyūn”","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise","part_no":67,"group_no":2,"chapter_no":20,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said in the lengthy hadith of the Vision: “When Allah has finished judging between the servants and wishes by His mercy to bring out whomever He wills from the people of the Fire, He will command the angels to bring out from the Fire those whom Allah, the Exalted, wishes to have mercy upon from among those who did not associate anything with Allah and who used to say: ‘There is no deity except Allah.’ The angels will recognize them in the Fire by the marks of prostration. The Fire consumes the son of Ādam except for the marks of prostration; Allah has forbidden the Fire from consuming the marks of prostration. They will be brought out of the Fire completely charred. Then the Water of Life will be poured over them, and they will grow from it just as a seed grows in the sediment carried by a flood…” The hadith continues."]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (7437)، ومسلم (182)."},{"num":16406,"demo":false,"sanad":"","matn":["عَنْ حُذَيْفَةَ، أنّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: يُخرجُ اللَّهُ قَوْمًا مُنْتِنِينَ قَدْ مَحَشَتْهُمُ النّارُ بِشَفَاعَةِ الشَّافِعِينَ، فَيُدْخِلُهُمُ الْجَنَّةَ، فيُسَمَّون الْجَهَنَّمِيُّونَ."],"takhrij":"حسن: رواه أحمد (23423)، وأبو داود الطيالسيّ في \"مسنده\" (420) ومن طريقه ابنُ خزيمة (545)، والآجريّ في الشّريعة (805) كلّهم من طريق شعبة، عن حمّاد، عن ربعي بن حراش، عن حذيفة بن اليمان، فذكره.","grade":"حسن","chapter_ar":"باب أهل الجنة الذين يقال لهم: الجهنميون","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (23423) and Abū Dāwūd al-Ṭayālisī in his Musnad (420).","chapter_en":"The People of Paradise Who Will Be Called “al-Jahannamiyyūn”","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise","part_no":67,"group_no":2,"chapter_no":20,"content":{"translation":{"en":["Ḥudhayfah narrated that the Messenger of Allah ﷺ said: “Allah will bring out people who have become foul-smelling and whom the Fire has charred, through the intercession of the intercessors. He will admit them into Paradise, and they will be called al-Jahannamiyyūn.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (23423)، وأبو داود الطيالسي في “مسنده” (420)."},{"num":16407,"demo":false,"sanad":"","matn":["عَنْ عُبَيْدَ بْنَ عُمَيْرٍ قال: قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم: يُخْرِجُ الله تعالى قَوْمًا من النار بعدما امْتُحِشُوا فِيهَا، وَصَارُوا فَحْمًا، فَيُلْقَوْنَ فِي نَهْرٍ عَلَى بَابِ الْجَنَّةِ، يُسَمَّى نَهْرُ الحياة، فينبتون فيها كَمَا تَنْبُتُ الْحَبَّةُ فِي حَمِيلِ السَّيْلِ، أَوْ كَمَا تَنْبُتُ الثَّعَارِيرُ، فَيَدْخُلُونَ الْجَنَّةَ، فَيُقَالَ: هَؤُلَاءِ عُتَقَاءُ اللَّهِ عز وجل من النار. وقال رجل متهم بِرَأْيِ الْخَوَارِجِ، يُقَالُ لَهُ هَارُونَ أَبُو مُوسَى أَوْ أَبُو مُوسَى بْنُ هَارُونَ: مَا هَذَا الَّذِي تُحُدِّثَ بِهِ أبا عَاصِمٍ؟ فَقَالَ: إِلَيْكَ عَنِّي يَا عِلْجُ! فَلَوْ لَمْ أَسْمَعْهُ مِنْ أَكْثَرِ مِنْ ثَلَاثِينَ مِنْ أَصْحَابِ رَسُولِ اللَّهِ صلى الله عليه وسلم لَمْ أُحَدِّثْ بِهِ."],"takhrij":"صحيح: رواه ابن أبي عمر – المطالب العالية (4560) واللفظ له-، والبيهقي في شعب الإيمان (319) كلاهما من طريق سفيان بن عيينة، عن عمرو بن دينار قال: أنه سمع عبيد بن عمير يقول: فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب أهل الجنة الذين يقال لهم: الجهنميون","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by Ibn Abī ʿUmar, as cited in al-Maṭālib al-ʿĀliyah (4560), whose wording this is, and al-Bayhaqī in Shuʿab al-Īmān (319).","chapter_en":"The People of Paradise Who Will Be Called “al-Jahannamiyyūn”","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise","part_no":67,"group_no":2,"chapter_no":20,"content":{"translation":{"en":["ʿUbayd ibn ʿUmayr narrated that the Messenger of Allah ﷺ said: “Allah, the Exalted, will bring people out of the Fire after they have been completely charred in it and become like coal. They will be cast into a river at the gate of Paradise called the River of Life. There they will grow as a seed grows in the sediment carried by a flood, or as tender shoots grow. Then they will enter Paradise, and it will be said: ‘These are those whom Allah, Mighty and Majestic, has freed from the Fire.’” A man suspected of holding the views of the Khawārij, named Hārūn Abū Mūsā—or Abū Mūsā ibn Hārūn—said: “What is this that you are narrating, O Abū ʿĀṣim?” He replied: “Away from me, you uncouth man! Had I not heard it from more than thirty of the Companions of the Messenger of Allah ﷺ, I would not have narrated it.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه ابن أبي عمر - المطالب العالية (4560) واللفظ له -، والبيهقي في شعب الإيمان (319)."},{"num":16408,"demo":false,"sanad":"","matn":["عَنْ مَسْرُوقٍ، قَالَ:  سَأَلْنَا عَبْدَ اللَّهِ عَنْ هَذِهِ الْآيَةِ: ﴿وَلا تَحْسَبَنَّ الَّذِينَ قُتِلُوا فِي سَبِيلِ اللَّهِ أَمْوَاتًا بَلْ أَحْيَاءٌ عِنْدَ رَبِّهِمْ يُرْزَقُونَ﴾ قَالَ: أَمَا إِنَّا قَدْ سَأَلْنَا عَنْ ذَلِكَ، فَقَالَ: أَرْوَاحُهُمْ فِي جَوْفِ طَيْرٍ خُضْرٍ، لَهَا قَنَادِيلُ مُعَلَّقَةٌ بِالْعَرْشِ، تَسْرَحُ مِنَ الْجَنَّةِ حَيْثُ شَاءَتْ، ثُمَّ تَأْوِي إِلَى تِلْكَ الْقَنَادِيلِ."],"takhrij":"صحيح: رواه مسلم في الإمارة (1887) من طرق عن الأعمش، عن عبد الله بن مرة، عن مسروق قال: فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء أن أرواح المؤمنين من الشهداء وغيرهم كالطير تعلق في شجر الجنة","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1887).","chapter_en":"What Has Been Narrated That the Souls of the Believers, Including the Martyrs and Others, Are Like Birds That Feed Among the Trees of Paradise","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise","part_no":67,"group_no":2,"chapter_no":21,"content":{"translation":{"en":["Masrūq narrated: We asked ʿAbdullāh about this verse: “Do not think of those who have been killed in the path of Allah as dead. Rather, they are alive with their Lord, receiving provision.” [Āl ʿImrān 3:169] He said: “We ourselves asked about that, and he said: ‘Their souls are inside green birds. They have lamps suspended from the Throne. They roam freely throughout Paradise wherever they wish, then return to those lamps…’”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (1887)."},{"num":16409,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ الرَّحْمَنِ بْنِ كَعْبٍ الأَنْصَارِيِّ، أَنَّهُ أَخْبَرَهُ أَنَّ أَبَاهُ كَانَ يُحَدِّثُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِنَّمَا نَسَمَةُ الْمُؤْمِنِ طَائِرٌ يَعْلُقُ فِي شَجَرِ الْجَنَّةِ، حَتَّى يَرْجِعَ إِلَى جَسَدِهِ يَوْمَ يُبْعَثُ."],"takhrij":"صحيح: رواه مالك في الجنائز (49) عن ابن شهاب، عن عبد الله بن كعب بن مالك، فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء أن أرواح المؤمنين من الشهداء وغيرهم كالطير تعلق في شجر الجنة","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by Mālik in al-Janāʾiz (49), al-Nasā’ī (2073), and Ibn Mājah (4271).","chapter_en":"What Has Been Narrated That the Souls of the Believers, Including the Martyrs and Others, Are Like Birds That Feed Among the Trees of Paradise","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise","part_no":67,"group_no":2,"chapter_no":21,"content":{"translation":{"en":["ʿAbd al-Raḥmān ibn Kaʿb ibn Mālik al-Anṣārī reported that his father, Kaʿb ibn Mālik, used to narrate that the Messenger of Allah ﷺ said: “The soul of the believer is a bird that feeds among the trees of Paradise until Allah returns it to his body on the Day of Resurrection.”"]},"buhuth":{"en":["Regarding the phrase “nasamat al-muʾmin,” with both vowels pronounced as fatḥah, it means: the soul."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مالك (49) والنسائي (2073)، وابن ماجه (4271)."},{"num":16410,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيَّ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : يَخْلُصُ الْمُؤْمِنُونَ مِنَ النَّارِ، فَيُحْبَسُونَ عَلَى قَنْطَرَةٍ بَيْنَ الْجَنَّةِ وَالنَّارِ، فَيُقَصُّ لِبَعْضِهِمْ مِنْ بَعْضٍ مَظَالِمُ كَانَتْ بَيْنَهُمْ فِي الدُّنْيَا، حَتَّى إِذَا هُذِّبُوا وَنُقُّوا أُذِنَ لَهُمْ فِي دُخُولِ الْجَنَّةِ، فَوَالَّذِي نَفْسُ مُحَمَّدٍ بِيَدِهِ، لأَحَدُهُمْ أَهْدَى بِمَنْزِلِهِ فِي الْجَنَّةِ مِنْهُ بِمَنْزِلِهِ كَانَ فِي الدُّنْيَا."],"takhrij":"صحيح: رواه البخاري (6535) عن الصلت بن محمد، حدثنا يزيد بن زريع، حدثنا سعيد، عن قتادة، عن أبي المتوكل الناجي، عن أبي سعيد الخدري فذكره.","grade":"صحيح","chapter_ar":"باب أهل الجنة أهدى بمنازلهم في الجنة من منازلهم كانت لهم في الدنيا","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (6535).","chapter_en":"The People of Paradise Will Know Their Homes in Paradise Better Than They Knew Their Homes in This World","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise","part_no":67,"group_no":2,"chapter_no":22,"content":{"translation":{"en":["Abū Saʿīd al-Khudrī narrated that the Messenger of Allah ﷺ said: “The believers will be delivered from the Fire, then detained upon a bridge between Paradise and the Fire. Retribution will be taken among them for wrongs they committed against one another in the worldly life. When they have been refined and purified, they will be given permission to enter Paradise. By the One in whose hand is the soul of Muḥammad, each of them will know his dwelling in Paradise better than he knew his dwelling in this world.”"]}},"tuhfa":{},"full":1,"rep":[12607,12718,13279,16219,16373],"tks":"صحيح: رواه البخاري (6535)."},{"num":16411,"demo":false,"sanad":"","matn":["عَنِ ابْنِ مَسْعُودٍ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: آخرُ مَنْ يَدْخُلُ الْجَنَّةَ رجلٌ، فَهُوَ يَمْشِي مرّة وَيَكْبُو مرّة، وتَسْفَعُه النَّارُ مرّة، فَإِذَا مَا جَاوَزَهَا الْتَفَتَ إِلَيْهَا، فَقَالَ: تَبَارَكَ الَّذِي نَجَّانِي منكِ، لَقَدْ أَعْطَانِيَ اللَّهُ شَيْئًا مَا أَعْطَاهُ أَحَدًا مِنَ الْأَوَّلِينَ وَالْآخِرِينَ. فَتُرْفَعُ لَهُ شَجَرةٌ، فَيَقُولُ: أيْ ربِّ أَدْنِني مِنْ هَذِهِ الشَّجَرَةِ فَلِأَسْتَظِلَّ بظلِّّها، وَأَشْرَبَ مِنْ مَائِهَا. فَيَقُولُ اللَّهُ عزّ وجلّ: يَا ابنَ آدَمَ لعلِّي إنْ أَعْطَيْتُكَهَا سَأَلْتَنِي غَيْرَهَا؟ فَيَقُولُ: لَا يَا ربّ. وَيُعَاهِدُهُ أَنْ لَا يَسْأَلَهُ غَيْرَهَا، وربُّه يَعْذِرُهُ لِأَنَّهُ يَرَى مَا لَا صَبْرَ لَهُ عَلَيْهِ، فَيُدْنِيهِ مِنْهَا فَيَسْتَظِلُّ بظلِّها وَيَشْرَبُ مِنْ مَائِهَا، ثُمَّ تُرْفَعُ لَهُ شَجَرَةٌ هِيَ أَحْسَنُ مِنَ الْأُولَى، فَيَقُولُ: أيْ ربِّ أَدْنِني مِنْ هَذِهِ لِأَشْرَبَ مِنْ مَائِهَا وَأَسْتَظِلَّ بظلِّها لَا أَسْأَلُكَ غَيْرَهَا. فَيَقُولُ: يَا ابنَ آدَمَ أَلَمْ تُعَاهِدْنِي أَنْ لَا تَسْأَلَنِي غَيْرَهَا؟ فَيَقُولُ: لَعَلِّي إِنْ أَدْنَيْتُكَ مِنْهَا تَسْأَلُنِي غَيْرَهَا؟ فَيُعَاهِدُهُ أَنْ لَا يَسْأَلَهُ غَيْرَهَا، وربُّه يَعْذِرُهُ لِأَنَّهُ يَرَى مَا لَا صبرَ لَهُ عَلَيْهِ، فَيُدْنِيهِ مِنْهَا، فَيَسْتَظِلُّ بِظِلِّهَا، وَيَشْرَبُ مِنْ مَائِهَا، ثُمَّ تُرْفَعُ لَهُ شَجَرَةٌ هِيَ عِنْدَ بَابِ الْجَنَّةِ هِيَ أَحْسَنُ مِنَ الْأُولَيَيْنِ. فَيَقُولُ: أيْ ربِّ، أَدْنِنِي مِنْ هَذِهِ لِأَسْتَظِلَّ بِظِلِّهَا وَأَشْرَبَ مِنْ مَائِهَا، لَا أَسْأَلُكَ غَيْرَهَا. فَيَقُولُ: يَا ابْنَ آدَمَ أَلَمْ تُعَاهِدْنِي أَنْ لَا تَسْأَلَنِي غَيْرَهَا؟ قَالَ: بَلَى يَا ربّ، هَذِهِ لَا أَسْأَلُكَ غَيْرَهَا وربُّه يَعْذِرُهُ لِأَنَّهُ يَرَى مَا لَا صبرَ لَهُ عَلَيْهِ. فَيُدْنِيهِ مِنْهَا، فَإِذَا أَدْنَاهُ مِنْهَا فَيَسْمَعُ أَصْوَاتَ أَهْلِ الْجَنَّةِ، فَيَقُولُ: أيْ ربِّ أَدْخِلْنِيهَا. فَيَقُولُ: يَا ابنّ آدَمَ مَا يَصْرِيني مِنْكَ؟ أيُرْضِيكَ أَنْ أُعْطِيَكَ الدُّنْيَا وَمِثْلَهَا مَعَهَا؟ قَالَ: يَا ربّ، أَتَسْتَهْزِئُ مِنِّي وَأَنْتَ ربُّ الْعَالَمِينَ؟. فَضَحِكَ ابنُ مَسْعُودٍ، فَقَالَ: أَلَا تَسْأَلُونِّي مِمَّ أَضْحَكُ؟ فَقَالُوا: مِمّ تَضْحَكُ؟ قَالَ: هَكَذَا ضَحِكَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ، فَقَالُوا: مِمّ تَضْحَكُ يَا رَسُولَ اللَّهِ؟ قَالَ: مِنْ ضِحْكِ ربّ الْعَالَمِينَ حِينَ قَالَ: أَتَسْتَهْزِئُ مِنِّي وَأَنْتَ ربُّ الْعَالَمِينَ؟. فَيَقُولُ: إنّي لَا أَسْتَهْزِئُ مِنْكَ، وَلَكِنِّي عَلَى مَا أَشَاءُ قَدِيرٌ، فيدخله الْجَنَّةَ."],"takhrij":"صحيح: رواه مسلم في الإيمان (187) عن أبي بكر بن أبي شيبة، حدّثنا عفّان بن مسلم، حدّثنا حمّاد بن سلمة، حدّثنا ثابت، عن أنس، عن ابن مسعود، فذكره.","grade":"صحيح","chapter_ar":"باب أدنى أهل الجنة منزلة فيها","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (187).","chapter_en":"The Lowest-Ranking Person in Paradise","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise","part_no":67,"group_no":2,"chapter_no":23,"content":{"translation":{"en":["Ibn Masʿūd narrated that the Messenger of Allah ﷺ said: “The last person to enter Paradise will be a man who walks at one time, stumbles at another, and at another time is scorched by the Fire. When he has finally passed beyond it, he will turn toward it and say: ‘Blessed is the One who saved me from you. Allah has given me something He has given to no one among the first or the last.’ Then a tree will be raised before him. He will say: ‘My Lord, bring me near this tree so that I may shelter in its shade and drink from its water.’ Allah, Mighty and Majestic, will say: ‘O son of Ādam, perhaps if I give you that, you will ask Me for something else.’ He will say: ‘No, my Lord,’ and he will promise Him that he will ask for nothing else. His Lord will excuse him because he sees something for which he has no patience. So He will bring him near it, and he will take shade beneath it and drink from its water. Then another tree, more beautiful than the first, will be raised before him. He will say: ‘My Lord, bring me near this one so that I may drink from its water and shelter in its shade. I will ask You for nothing else.’ He will say: ‘O son of Ādam, did you not promise Me that you would ask for nothing else? Perhaps if I bring you near it, you will ask Me for something more.’ Again he will promise not to ask for anything else, and his Lord will excuse him because he sees something for which he has no patience. So He will bring him near it, and he will shelter in its shade and drink from its water. Then another tree will be raised before him at the gate of Paradise, more beautiful than the first two. He will say: ‘My Lord, bring me near this one so that I may shelter in its shade and drink from its water. I will ask You for nothing else.’ He will say: ‘O son of Ādam, did you not promise Me that you would ask for nothing else?’ He will say: ‘Yes, my Lord. This one, and I will ask You for nothing beyond it.’ His Lord will excuse him because he sees something for which he has no patience. So He will bring him near it. When he is brought near it, he will hear the voices of the people of Paradise and say: ‘My Lord, admit me into it.’ Allah will say: ‘O son of Ādam, what will finally bring your asking of Me to an end? Would it please you if I gave you the whole world and another like it with it?’ He will say: ‘My Lord, are You mocking me while You are the Lord of all the worlds?’” Ibn Masʿūd laughed and said: “Will you not ask me why I am laughing?” They asked: “Why are you laughing?” He replied: “This is how the Messenger of Allah ﷺ laughed.” They asked: “Why are you laughing, O Messenger of Allah?” He said: “Because of the laughter of the Lord of the worlds when the man says: ‘Are You mocking me while You are the Lord of all the worlds?’ Allah will say: ‘I am not mocking you, but I am capable of whatever I will.’ Then He will admit him into Paradise.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (187)."},{"num":16412,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:  إِنَّ أَدْنَى أَهْلِ الْجَنَّةِ مَنْزِلَةً رَجُلٌ صَرَفَ اللهُ وَجْهَهُ عَنِ النَّارِ قِبَلَ الْجَنَّةِ، وَمَثَّلَ لَهُ شَجَرَةً ذَاتَ ظِلٍّ، فَقَالَ: أَيْ رَبِّ، قَدِّمْنِي إِلَى هَذِهِ الشَّجَرَةِ أَكُونُ فِي ظِلِّهَا، وَسَاقَ الْحَدِيثَ بِنَحْوِ حَدِيثِ ابْنِ مَسْعُودٍ، وَلَمْ يَذْكُرْ: فَيَقُولُ: يَا ابْنَ آدَمَ، مَا يَصْرِينِي مِنْكَ، إِلَى آخِرِ الْحَدِيثِ، وَزَادَ فِيهِ: وَيُذَكِّرُهُ اللهُ، سَلْ كَذَا وَكَذَا، فَإِذَا انْقَطَعَتْ بِهِ الْأَمَانِيُّ، قَالَ اللَّهُ: هُوَ لَكَ وَعَشَرَةُ أَمْثَالِهِ، قَالَ: ثُمَّ يَدْخُلُ بَيْتَهُ، فَتَدْخُلُ عَلَيْهِ زَوْجَتَاهُ مِنَ الْحُورِ الْعِينِ، فَتَقُولَانِ: الْحَمْدُ لِلهِ الَّذِي أَحْيَاكَ لَنَا، وَأَحْيَانَا لَكَ، قَالَ: فَيَقُولُ: مَا أُعْطِيَ أَحَدٌ مِثْلَ مَا أُعْطِيتُ."],"takhrij":"صحيح: رواه مسلم في الإيمان (188) عن أبي بكر بن أبي شيبة، حدثنا يحيى بن أبي بكير، حدثنا زهير بن محمد، عن سُهيل بن أبي صالح، عن النعمان بن أبي عياش، عن أبي سعيد الخدري، فذكره.","grade":"صحيح","chapter_ar":"باب أدنى أهل الجنة منزلة فيها","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (188).","chapter_en":"The Lowest-Ranking Person in Paradise","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise","part_no":67,"group_no":2,"chapter_no":23,"content":{"translation":{"en":["Abū Saʿīd al-Khudrī narrated that the Messenger of Allah ﷺ said: “The lowest-ranking person in Paradise will be a man whose face Allah turns away from the Fire toward Paradise. A tree with shade will be made to appear before him, and he will say: ‘My Lord, bring me near this tree so that I may remain in its shade.’” He then related the hadith in a manner similar to the narration of Ibn Masʿūd, but without the wording: “O son of Ādam, what will finally bring your asking of Me to an end?” up to the end of that narration. He added: “Allah will remind him: ‘Ask for such-and-such, and such-and-such.’ When all his wishes have been exhausted, Allah will say: ‘All of that is yours, and ten times as much.’” He said: “Then he will enter his house, and his two wives from the ḥūr al-ʿīn will enter upon him and say: ‘All praise is for Allah who brought you to life for us and brought us to life for you.’” He will say: “No one has been given anything like what I have been given.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (188)."},{"num":16413,"demo":false,"sanad":"","matn":["عن الْمُغِيرَةِ بن شُعْبَةَ يرفعه إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: سَأَلَ مُوسَى رَبَّهُ: مَا أَدْنَى أَهْلِ الْجَنَّةِ مَنْزِلَةً؟ قَالَ: هُوَ رَجُلٌ يَجِيءُ بَعْدَمَا أُدْخِلَ أَهْلُ الْجَنَّةِ الْجَنَّةَ، فَيُقَالُ لَهُ: ادْخُلِ الْجَنَّةَ، فَيَقُولُ: أَيْ رَبِّ، كَيْفَ وَقَدْ نَزَلَ النَّاسُ مَنَازِلَهُمْ، وَأَخَذُوا أَخَذَاتِهِمْ؟ فَيُقَالُ لَهُ: أَتَرْضَى أَنْ يَكُونَ لَكَ مِثْلُ مُلْكِ مَلِكٍ مِنْ مُلُوكِ الدُّنْيَا؟ فَيَقُولُ: رَضِيتُ رَبِّ، فَيَقُولُ: لَكَ ذَلِكَ، وَمِثْلُهُ وَمِثْلُهُ وَمِثْلُهُ وَمِثْلُهُ، فَقَالَ فِي الْخَامِسَةِ: رَضِيتُ رَبِّ، فَيَقُولُ: هَذَا لَكَ وَعَشَرَةُ أَمْثَالِهِ، وَلَكَ مَا اشْتَهَتْ نَفْسُكَ، وَلَذَّتْ عَيْنُكَ، فَيَقُولُ: رَضِيتُ رَبِّ، قَالَ: رَبِّ، فَأَعْلَاهُمْ مَنْزِلَةً؟ قَالَ: أُولَئِكَ الَّذِينَ أَرَدْتُ، غَرَسْتُ كَرَامَتَهُمْ بِيَدِي، وَخَتَمْتُ عَلَيْهَا، فَلَمْ تَرَ عَيْنٌ، وَلَمْ تَسْمَعْ أُذُنٌ، وَلَمْ يَخْطُرْ عَلَى قَلْبِ بَشَرٍ، قَالَ: وَمِصْدَاقُهُ فِي كِتَابِ اللَّهِ عَزَّ وَجَلَّ: ﴿فَلا تَعْلَمُ نَفْسٌ مَا أُخْفِيَ لَهُمْ مِنْ قُرَّةِ أَعْيُنٍ﴾، الْآيَةَ."],"takhrij":"صحيح: رواه مسلم في الإيمان (189) من طرق عن الشعبي، يخبر عن المغيرة بن شعبة، قال: سمعته على المنبر يرفعه إلى رسول الله صلى الله عليه وسلم.","grade":"صحيح","chapter_ar":"باب أدنى أهل الجنة منزلة فيها","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (189).","chapter_en":"The Lowest-Ranking Person in Paradise","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise","part_no":67,"group_no":2,"chapter_no":23,"content":{"translation":{"en":["Al-Mughīrah ibn Shuʿbah narrated, attributing it to the Messenger of Allah ﷺ: “Mūsā asked his Lord: ‘What is the lowest rank among the people of Paradise?’ He said: ʿIt is a man who will come after the people of Paradise have already entered Paradise. It will be said to him: “Enter Paradise.” He will say: “My Lord, how can I, when the people have already settled in their dwellings and received what was allotted to them?” It will be said to him: “Would you be pleased to have the equivalent of the kingdom of one of the kings of this world?” He will say: “I am pleased, my Lord.” He will say: “You will have that, and another like it, and another like it, and another like it, and another like it.” At the fifth, he will say: “I am pleased, my Lord.” He will say: “All of that is yours, and ten times as much, and you will have whatever your soul desires and whatever delights your eyes.” He will say: “I am pleased, my Lord.” Mūsā asked: “My Lord, what about those of the highest rank?” He said: “Those are the ones whom I chose. I planted their honor with My Hand and sealed it. No eye has seen it, no ear has heard it, and it has never occurred to a human heart.”” He said: Its confirmation is in the Book of Allah, Mighty and Majestic: “No soul knows what comfort of the eyes has been hidden for them.” [al-Sajdah 32:17]"]},"buhuth":{"en":["Regarding the phrase “whom I chose,” the author explains that it means: whom I selected and specially chose.","Regarding the phrase “I planted their honor,” the author explains that it means: I specially selected them and took charge of them, so no alteration can reach the honor prepared for them."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (189)."},{"num":16414,"demo":false,"sanad":"","matn":["عَنْ أَبِي ذَرٍّ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:  إِنِّي لَأَعْلَمُ آخِرَ أَهْلِ الْجَنَّةِ دُخُولًا الْجَنَّةَ، وَآخِرَ أَهْلِ النَّارِ خُرُوجًا مِنْهَا: رَجُلٌ يُؤْتَى بِهِ يَوْمَ الْقِيَامَةِ، فَيُقَالُ: اعْرِضُوا عَلَيْهِ صِغَارَ ذُنُوبِهِ، وَارْفَعُوا عَنْهُ كِبَارَهَا، فَتُعْرَضُ عَلَيْهِ صِغَارُ ذُنُوبِهِ، فَيُقَالُ: عَمِلْتَ يَوْمَ كَذَا وَكَذَا كَذَا وَكَذَا، وَعَمِلْتَ يَوْمَ كَذَا وَكَذَا كَذَا وَكَذَا، فَيَقُولُ: نَعَمْ، لَا يَسْتَطِيعُ أَنْ يُنْكِرَ، وَهُوَ مُشْفِقٌ مِنْ كِبَارِ ذُنُوبِهِ أَنْ تُعْرَضَ عَلَيْهِ، فَيُقَالُ لَهُ: فَإِنَّ لَكَ مَكَانَ كُلِّ سَيِّئَةٍ حَسَنَةً، فَيَقُولُ: رَبِّ، قَدْ عَمِلْتُ أَشْيَاءَ لَا أَرَاهَا هَا هُنَا، فَلَقَدْ رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ضَحِكَ حَتَّى بَدَتْ نَوَاجِذُهُ."],"takhrij":"صحيح: رواه مسلم في الإيمان (190)، من طرق عن الأعمش، عن المعرور بن سويد، عن أبي ذر، فذكره.","grade":"صحيح","chapter_ar":"باب أدنى أهل الجنة منزلة فيها","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (190).","chapter_en":"The Lowest-Ranking Person in Paradise","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise","part_no":67,"group_no":2,"chapter_no":23,"content":{"translation":{"en":["Abū Dharr narrated that the Messenger of Allah ﷺ said: “I certainly know the last person to enter Paradise and the last person to come out of the Fire. A man will be brought on the Day of Resurrection, and it will be said: ‘Present his minor sins to him, but withhold his major sins from him.’ His minor sins will be presented to him, and it will be said: ‘On such-and-such a day you did this and this, and on such-and-such a day you did this and this.’ He will say: ‘Yes,’ unable to deny them, while fearing that his major sins will also be shown to him. Then it will be said to him: ‘For every evil deed, you will have a good deed in its place.’ He will say: ‘My Lord, I committed other things that I do not see here!’” Abū Dharr said: “I saw the Messenger of Allah ﷺ laugh until his molar teeth became visible.”"]}},"tuhfa":{},"full":1,"rep":[11457,12920],"tks":"صحيح: رواه مسلم (190)."},{"num":16415,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُ قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنِّي لأَعْلَمُ آخِرَ أَهْلِ النَّارِ خُرُوجًا مِنْهَا، وَآخِرَ أَهْلِ الْجَنَّةِ دُخُولاً، رَجُلٌ يَخْرُجُ مِنَ النَّارِ كَبْوًا، فَيَقُولُ اللَّهُ: اذْهَبْ فَادْخُلِ الْجَنَّةَ. فَيَأْتِيهَا، فَيُخَيَّلُ إِلَيْهِ أَنَّهَا مَلأَى، فَيَرْجِعُ فَيَقُولُ: يَا رَبِّ، وَجَدْتُهَا مَلأَى، فَيَقُولُ: اذْهَبْ فَادْخُلِ الْجَنَّةَ. فَيَأْتِيهَا فَيُخَيَّلُ إِلَيْهِ أَنَّهَا مَلأَى. فَيَقُولُ: يَا رَبِّ وَجَدْتُهَا مَلأَى، فَيَقُولُ: اذْهَبْ فَادْخُلِ الْجَنَّةَ، فَإِنَّ لَكَ مِثْلَ الدُّنْيَا وَعَشَرَةَ أَمْثَالِهَا. أَوْ: إِنَّ لَكَ مِثْلَ عَشَرَةِ أَمْثَالِ الدُّنْيَا. فَيَقُولُ: تَسْخَرُ مِنِّي، أَوْ: تَضْحَكُ مِنِّي وَأَنْتَ الْمَلِكُ. فَلَقَدْ رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ضَحِكَ حَتَّى بَدَتْ نَوَاجِذُهُ، وَكَانَ يُقَالُ ذَلِكَ أَدْنَى أَهْلِ الْجَنَّةِ مَنْزِلَةً."],"takhrij":"متفق عليه: رواه البخاري في الرقاق (6571)، ومسلم في الإيمان (186: 308) كلاهما عن عثمان بن أبي شيبة، حدثنا جرير، عن منصور، عن إبراهيم، عن عبيدة، عن عبد الله بن مسعود، فذكره.","grade":"متفق عليه","chapter_ar":"باب أدنى أهل الجنة منزلة فيها","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6571) and Muslim (308 :186).","chapter_en":"The Lowest-Ranking Person in Paradise","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise","part_no":67,"group_no":2,"chapter_no":23,"content":{"translation":{"en":["ʿAbdullāh ibn Masʿūd narrated that the Messenger of Allah ﷺ said: “I certainly know the last person to come out of the Fire and the last person to enter Paradise. A man will emerge from the Fire crawling. Allah will say to him: ‘Go and enter Paradise.’ He will go to it, but it will appear to him to be full. So he will return and say: ‘My Lord, I found it full.’ Allah will say: ‘Go and enter Paradise.’ He will go to it, but again it will appear to him to be full. So he will return and say: ‘My Lord, I found it full.’ Allah will say: ‘Go and enter Paradise, for you shall have the equivalent of the world and ten times as much’—or: ‘You shall have the equivalent of ten worlds.’ He will say: ‘Are You mocking me—or laughing at me—while You are the King?’” Ibn Masʿūd said: “I saw the Messenger of Allah ﷺ laugh until his molar teeth became visible.” And he used to say: “That is the lowest-ranking person in Paradise.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (6571)، ومسلم (186: 308)."},{"num":16416,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : إِنَّ أَدْنَى مَقْعَدِ أَحَدِكُمْ مِنَ الْجَنَّةِ أَنْ يَقُولَ لَهُ: تَمَنَّ، فَيَتَمَنَّى، وَيَتَمَنَّى، فَيَقُولُ لَهُ: هَلْ تَمَنَّيْتَ؟ فَيَقُولُ: نَعَمْ، فَيَقُولُ لَهُ: فَإِنَّ لَكَ مَا تَمَنَّيْتَ وَمِثْلَهُ مَعَهُ."],"takhrij":"صحيح: رواه مسلم في الإيمان (182: 301) من طريق عبد الرزاق، عن معمر، عن همام بن منبه قال: هذا ما حدثنا أبو هريرة، عن رسول الله صلى الله عليه وسلم، فذكره.","grade":"صحيح","chapter_ar":"باب أدنى أهل الجنة منزلة فيها","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (301 :182).","chapter_en":"The Lowest-Ranking Person in Paradise","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise","part_no":67,"group_no":2,"chapter_no":23,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “The lowest dwelling of one of you in Paradise will be that it is said to him: ‘Wish.’ So he will wish and continue wishing. Then it will be said to him: ‘Have you finished wishing?’ He will say: ‘Yes.’ Then it will be said to him: ‘You shall have everything you wished for, and another like it with it.’”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (182: 301)."},{"num":16417,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أنّ نَاسًا قَالُوا لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : يَا رَسُولَ اللَّهِ، هَلْ نَرَى ربَّنا يَوْمَ الْقِيَامَةِ؟ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ.. ... فَذَكَرَ حَدِيثًا طويلا، وَفِيهِ: ثُمَّ يفرُغُ اللهُ تَعَالَى مِنَ الْقَضَاءِ بَيْنَ الْعِبَادِ، وَيَبْقَى رَجُلٌ مُقْبِلٌ بِوَجْهِهِ عَلَى النَّارِ - وَهُوَ آخِرُ أَهْلِ الْجَنَّةِ دُخُولًا الْجَنَّةَ - فَيَقُولُ: أَيْ ربِّ اصْرِفْ وَجْهِي عَنِ النَّارِ، فَإِنَّهُ قَدْ قَشَبَنِي رِيحُهَا وَأَحْرَقَنِي ذَكَاؤُهَا، فيدْعُو اللهَ مَا شاءَ اللَّهُ أَنْ يَدْعُوهُ، ثُمَّ يَقُولُ اللَّهُ تَبَارَكَ وَتَعَالَى: هَلْ عَسَيْتَ إنْ فَعَلْتُ ذَلِكَ بِكَ أَنْ تَسْألَ غَيْرَه؟ فَيَقُولُ: لاأسألك غَيْرَهُ، وَيُعْطِي ربَّه مِنْ عُهُودٍ وَمَوَاثِيقَ مَا شَاءَ اللَّهُ، فَيَصْرِفُ اللهُ وَجْهَه عَنِ النَّار، فَإِذَا أَقْبَلَ عَلَى الجنَّة وَرَآهَا سكتَ مَا شَاءَ اللَّهُ أَنْ يَسْكُتَ، ثمّ يَقُولُ: أيْ ربِّ قَدِّمْني إِلَى بَابِ الْجَنَّةِ، فَيَقُولُ اللَّهُ لَهُ: أَلَيْسَ قَدْ أَعْطَيْتَ عُهُودَكَ وَمَوَاثِيقَكَ لَا تَسْأَلُنِي غَيْرَ الَّذِي أَعْطَيْتُكَ، ويَلْك يَا ابنَ آدَمَ مَا أغْدَرَكَ! فَيَقُولُ: أيْ ربِّ وَيَدْعُو اللهَ حتّى يَقُولَ لَهُ: فَهلْ عَسَيْتَ إنْ أَعْطَيْتُكَ ذَلِكَ أَنْ تَسْأَلَ غيْرَه؟ فَيَقُولُ: لَا وعِزَّتِك فَيُعْطِي ربَّه مَا شَاءَ اللَّهُ مِنْ عُهُودٍ وَمَوَاثِيقَ، فيقدِّمُه إِلَى بَابِ الْجَنَّةِ، فَإِذَا قَامَ عَلَى بَابِ الجنَّة انْفَهَقَتْ لَهُ الجنَّةُ، فَرَأَى مَا فِيهَا مِنَ الْخَيْرِ وَالسُّرُورِ. فَيَسْكُتُ مَا شَاءَ اللَّهُ أَنْ يَسْكُتَ، ثُمَّ يَقُولُ: أَيْ ربِّ أَدْخِلني الجنَّةَ. فَيَقُولُ اللَّهُ تَبَارَكَ وَتَعَالَى لَهُ: أَلَيْسَ قَدْ أَعْطَيْتَ عُهُودَكَ وَمَوَاثِيقَكَ أَنْ لَا تَسْأَلَ غَيْرَ مَا أُعْطِيتَ؟! وَيْلَكَ يَا ابْنَ آدَمَ مَا أَغْدَرَكَ! فَيَقُولُ: أيْ ربَّ لَا أَكُونُ أَشْقَى خَلْقِك، فَلَا يَزَالُ يَدْعُو اللَّهَ حتّى يضْحَكَ اللَّهُ تَبَارَكَ وَتَعَالَى مِنْهُ، فَإِذَا ضَحِكَ اللَّهُ مِنْهُ قَالَ: اُدْخُل الجنَّة، فَإِذَا دَخَلَهَا قَالَ اللَّهُ لَهُ: تَمَنَّهْ فَيَسْأَلُ ربَّه وَيَتَمَنَّى، حتّى إنَّ اللَّهَ ليُذَكِّرُه مِنْ كَذَا وَكَذَا، حتَّى إِذَا انْقَطَعَتْ بِهِ الْأَمَانِيُّ. قَالَ اللَّهُ تَعَالَى: ذَلِكَ لَكَ وَمِثْلُهُ مَعَهُ."],"takhrij":"متفق عليه: رواه البخاريّ في التوحيد (7437)، ومسلم في الإيمان (182) كلاهما من حديث إبراهيم بن سعد، عن ابن شهاب، عن عطاء بن يزيد اللّيثيّ، أن أبا هريرة أخبره أن ناسا قالوا: فذكر الحديث بطوله، وهو مذكور في باب جامع في مشاهد يوم القيامة.","grade":"متفق عليه","chapter_ar":"باب أدنى أهل الجنة منزلة فيها","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (7437) and Muslim (182).","chapter_en":"The Lowest-Ranking Person in Paradise","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise","part_no":67,"group_no":2,"chapter_no":23,"content":{"translation":{"en":["Abū Hurayrah narrated that some people asked the Messenger of Allah ﷺ: “O Messenger of Allah, will we see our Lord on the Day of Resurrection?” The Messenger of Allah ﷺ then mentioned a lengthy hadith, in which he said: “Then Allah, the Exalted, will finish judging between the servants, and one man will remain facing the Fire. He will be the last person from the people of Paradise to enter Paradise. He will say: ‘My Lord, turn my face away from the Fire, for its wind has poisoned me and its flame has burned me.’ He will supplicate to Allah for as long as Allah wills that he supplicate. Then Allah, Blessed and Exalted, will say: ‘If I do that for you, perhaps you will ask for something else.’ He will say: ‘I will ask You for nothing else,’ and he will give his Lord whatever covenants and pledges Allah wills. So Allah will turn his face away from the Fire. When he faces Paradise and sees it, he will remain silent for as long as Allah wills. Then he will say: ‘My Lord, bring me to the gate of Paradise.’ Allah will say to him: ‘Did you not give your covenants and pledges that you would ask Me for nothing beyond what I had already given you? Woe to you, O son of Ādam! How treacherous you are!’ He will say: ‘My Lord…’ and continue supplicating to Allah until He says to him: ‘If I give you that, perhaps you will ask for something else.’ He will say: ‘No, by Your Might,’ and he will give his Lord whatever covenants and pledges Allah wills. So He will bring him to the gate of Paradise. When he stands at the gate of Paradise, Paradise will open wide before him, and he will see all the goodness and joy within it. He will remain silent for as long as Allah wills, then say: ‘My Lord, admit me into Paradise.’ Allah, Blessed and Exalted, will say to him: ‘Did you not give your covenants and pledges that you would ask for nothing beyond what I had given you? Woe to you, O son of Ādam! How treacherous you are!’ He will say: ‘My Lord, do not make me the most wretched of Your creation.’ He will continue supplicating to Allah until Allah, Blessed and Exalted, laughs at him. When Allah laughs at him, He will say: ‘Enter Paradise.’ When he enters it, Allah will say to him: ‘Wish.’ So he will ask his Lord and make wishes, until Allah Himself reminds him of such-and-such things. When all his wishes are exhausted, Allah, the Exalted, will say: ‘All of that is yours, and another like it with it.’”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (7437)، ومسلم (182)."},{"num":16418,"demo":false,"sanad":"","matn":["عن سَهْلِ بْنِ سَعْدٍ قَالَ: قَالَ رَسُولُ اللهِ صلى الله عليه وسلم: إِنَّ أَدْنَى أَهْلِ الْجَنَّةِ مَنْزِلَةً -- وَلَيْسَ فِيهَا دَنِيٌّ -- الَّذِي يَتَمَنَّى، فَيَقُولُ بِلِسَانٍ طَلْقٍ ذَلْقٍ وَعَقَلٍ مُجْتَمِعٍ: أَعْطِنِي أَعْطِنِي كَذَا، حَتَّى إِذَا لَمْ يَجِدْ شَيْئًا لُقِّنَ، فَقِيلَ لَهُ: قُلْ كَذَا، قُلْ كَذَا، فَيُقَالُ لَهُ: هُوَ لَكَ وَمِثْلُهُ مَعَهُ."],"takhrij":"صحيح: رواه الطبراني في الكبير (5884)، وأبو نعيم في صفة الجنة (445) كلاهما من طرق عن عبد العزيز بن أبي حازم، حدثني أبي، عن سهل بن سعد فذكره.","grade":"صحيح","chapter_ar":"باب أدنى أهل الجنة منزلة فيها","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by al-Ṭabarānī in al-Muʿjam al-Kabīr (6/208) and Abū Nuʿaym in Ṣifat al-Jannah (445).","chapter_en":"The Lowest-Ranking Person in Paradise","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise","part_no":67,"group_no":2,"chapter_no":23,"content":{"translation":{"en":["Sahl ibn Saʿd narrated that the Messenger of Allah ﷺ said: “The lowest-ranking person in Paradise—and there is nothing lowly in Paradise—is the one who will make wishes. With a fluent tongue and a fully composed mind he will say: ‘Give me this, give me that,’ until he can think of nothing more. Then he will be prompted and it will be said to him: ‘Ask for such-and-such, ask for such-and-such.’ Then it will be said to him: ‘It is yours, and another like it with it.’”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الطبراني في الكبير (5884)، وأبو نعيم في صفة الجنة (445)."},{"num":16419,"demo":false,"sanad":"","matn":["عن أبي هريرة قال: قال رسول الله صلى الله عليه وسلم: بينا هو- يعني آخر من يدخل الجنة - يمضي فيها، إذ رأى ضوءا فيخر ساجدا، فيقال له: ما لك؟ فيقول: أليس هذا ربي تجلى لي؟ فإذا هو برجل قائم، فيقول: لا، هذا منْزل من منازلك، وأنا قهرمان من قهارمتك، ولك مثلي ألف قهرمان، ثم يمشي أمامه، فيدخل أدنى قصوره، لا يشرف على شيء منها إلا أنفذ بصره، أقصى مملكته مسيرة مائة سنة."],"takhrij":"حسن: رواه أبو نعيم في صفة الجنة (441) عن القاضي أبي أحمد، ثنا محمد بن أيوب، ثنا عبد الرحمن بن المبارك، ثنا قريش بن حيان، ثنا بكر بن وائل، عن الزهري، عن أبي عبد الله الأغر, عن أبي هريرة قال: فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في قهرمان أهل الجنة","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Nuʿaym (441).","chapter_en":"What Has Been Narrated Concerning the Stewards of the People of Paradise","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise","part_no":67,"group_no":2,"chapter_no":24,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “While he—that is, the last person to enter Paradise—is walking through it, he will see a light and fall down in prostration. It will be asked: ‘What is the matter with you?’ He will say: ‘Is this not my Lord manifesting Himself to me?’ But it will only be a man standing there, who will say: ‘No. This is merely one of your dwellings, and I am one steward among your stewards. You have one thousand stewards like me.’ Then he will walk ahead of him until he enters the lowest of his palaces. Whenever he looks out from any part of it, his sight will reach the farthest limit of his kingdom—a journey of one hundred years.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو نعيم (441)."},{"num":16420,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : خَلَقَ اللهُ عزوجل آدَمَ عَلَى صُورَتِهِ، طُولُهُ سِتُّونَ ذِرَاعًا، فَلَمَّا خَلَقَهُ قَالَ: اذْهَبْ فَسَلِّمْ عَلَى أُولَئِكَ النَّفَرِ، وَهُمْ نَفَرٌ مِنَ الْمَلَائِكَةِ جُلُوسٌ، فَاسْتَمِعْ مَا يُحَيُّونَكَ، فَإِنَّهَا تَحِيَّتُكَ وَتَحِيَّةُ ذُرِّيَّتِكَ، قَالَ: فَذَهَبَ فَقَالَ: السَّلَامُ عَلَيْكُمْ، فَقَالُوا: السَّلَامُ عَلَيْكَ وَرَحْمَةُ اللَّهِ، قَالَ فَزَادُوهُ: وَرَحْمَةُ اللَّهِ، قَالَ: فَكُلُّ مَنْ يَدْخُلُ الْجَنَّةَ عَلَى صُورَةِ آدَمَ وَطُولُهُ سِتُّونَ ذِرَاعًا، فَلَمْ يَزَلِ الْخَلْقُ يَنْقُصُ بَعْدَهُ حَتَّى الْآنَ."],"takhrij":"متفق عليه: رواه البخاري في الأنبياء (3326)، ومسلم في الجنة (2841) كلاهما من طريق عبدالرزاق، عن معمر، عن همام بن منبه، عن أبي هريرة، فذكره.","grade":"متفق عليه","chapter_ar":"باب دخول أهل الجنة الجنة على صورة آدم عليه السلام، وطوله ستون ذراعًا","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (3326) and Muslim (2841).","chapter_en":"The People of Paradise Will Enter Paradise in the Form of Ādam عليه السلام, Whose Height Was Sixty Cubits","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise","part_no":67,"group_no":2,"chapter_no":25,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “Allah, Mighty and Majestic, created Ādam upon his form, his height being sixty cubits. When He created him, He said: ‘Go and greet that group,’ and they were a group of angels sitting together, ‘and listen to how they greet you, for that will be your greeting and the greeting of your descendants.’ So he went and said: ‘Peace be upon you.’ They replied: ‘Peace be upon you and the mercy of Allah,’ adding: ‘and the mercy of Allah.’ Everyone who enters Paradise will enter upon the form of Ādam and at a height of sixty cubits. Creation has continued to decrease in stature after him until now.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (3326)، ومسلم (2841)."},{"num":16421,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِنَّ أَهْلَ الْجَنَّةِ يَدْخُلُونَ الْجَنَّةَ عَلَى قَدْرِ آدَمَ سِتُّونَ ذِرَاعًا، وَعَلَى ذَلِكَ قُطِعَتْ سُرُرُهُمْ."],"takhrij":"حسن: رواه الطبراني في مسند الشاميين (2074)، وأبو نعيم في صفة الجنة (248) كلاهما من طريق حرملة بن يحيى، ثنا ابن وهب قال: حدثني معاوية بن صالح، عن عبدالوهاب بن بخت، عن أبي الزناد، عن الأعرج، عن أبي هريرة، فذكره.","grade":"حسن","chapter_ar":"باب دخول أهل الجنة الجنة على صورة آدم عليه السلام، وطوله ستون ذراعًا","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Hasan: Narrated by al-Ṭabarānī in Musnad al-Shāmiyyīn (2074) and Abū Nuʿaym in Ṣifat al-Jannah (248).","chapter_en":"The People of Paradise Will Enter Paradise in the Form of Ādam عليه السلام, Whose Height Was Sixty Cubits","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise","part_no":67,"group_no":2,"chapter_no":25,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “The people of Paradise will enter Paradise at the stature of Ādam—sixty cubits—and their couches have been made according to that measure.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطبراني في مسند الشاميين (2074)، وأبو نعيم في صفة الجنة (248)."},{"num":16422,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَهْلُ الْجَنَّةِ جُرْدٌ مُرْدٌ كُحْلٌ، لاَ يَفْنَى شَبَابُهُمْ، وَلاَ تَبْلَى ثِيَابُهُمْ."],"takhrij":"حسن: رواه الترمذي (2539)، والدارمي (2868)، وأبو نعيم في صفة الجنة (256) كلهم من طريق معاذ بن هشام، عن أبيه، عن عامر الأحول، عن شهر بن حوشب، عن أبي هريرة قال: فذكره.","grade":"حسن","chapter_ar":"باب أن أهل الجنة جرد مرد كحل","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhī (2539), al-Dārimī (2868), and Abū Nuʿaym in Ṣifat al-Jannah (256).","chapter_en":"The People of Paradise Will Be Hairless, Beardless, and Kohl-Eyed","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise","part_no":67,"group_no":2,"chapter_no":26,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “The people of Paradise will be hairless, beardless, and kohl-eyed. Their youth will never fade, and their clothes will never wear out.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الترمذي (2539)، والدارمي (2868)، وأبو نعيم في صفة الجنة (256)."},{"num":16423,"demo":false,"sanad":"","matn":["عَنْ الْمِقْدَامَ بْنَ مَعْدِي كَرِبٍ حَدَّثَهُمْ أَنَّ رَسُولَ اللهِ صلى الله عليه وسلم قَالَ: مَا مِنْ أَحَدٍ يَمُوتُ سِقْطًا وَلَا هَرِمًا، وَإِنَّمَا النَّاسُ فِيمَا بَيْنَ ذَلِكَ إِلَّا بُعِثَ ابْنَ ثَلَاثِينَ سَنَةً، فَمَنْ كَانَ مِنْ أَهْلِ الْجَنَّةِ كَانَ عَلَى مَسْحَةِ آدَمَ، وصُورَةِ يُوسُفَ، وَقَلَبِ أَيُّوبَ، وَمَنْ كَانَ مِنْ أَهْلِ النَّارِ عُظِّمُوا وَفُخِّمُوا كَالْجِبَالِ."],"takhrij":"حسن: رواه الطبراني في الكبير (20/ح 663) من طريقين، أحدهما حسن.","grade":"حسن","chapter_ar":"باب أطفال المؤمنين يكمل خلقهم عند دخولهم الجنة أبناء ثلاث وثلاثين سنة على خلق آدم ستون ذراعًا","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Hasan: Narrated by al-Ṭabarānī in al-Muʿjam al-Kabīr (20/280) through two routes, one of which is good.","chapter_en":"The Children of the Believers Will Have Their Creation Completed upon Entering Paradise at the Age of Thirty-Three, upon the Form of Ādam, Sixty Cubits Tall","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise","part_no":67,"group_no":2,"chapter_no":27,"content":{"translation":{"en":["Al-Miqdām ibn Maʿdī Karib narrated to them that the Messenger of Allah ﷺ said: “No one dies as a miscarried child or in extreme old age—and people die at all ages between those two—except that he will be resurrected at the age of thirty. Whoever is among the people of Paradise will be upon the appearance of Ādam, the beauty of Yūsuf, and the heart of Ayyūb. As for those who are among the people of the Fire, they will be enlarged and made huge like mountains.”"]},"buhuth":{"en":["Shaykh al-Islām Ibn Taymiyyah was asked whether the children of the believers will remain in the same state in which they died, or whether they will grow up and marry, and likewise whether girls will marry.","He replied:","“Praise be to Allah. When they enter Paradise, they will enter it just as adults enter it, upon the form of their father Ādam, whose height was sixty cubits and whose width was seven cubits. They will marry just as adults marry. A woman who died without having married will be married in the Hereafter, and likewise a man who died will marry in the Hereafter. And Allah, the Exalted, knows best.”","Majmūʿ al-Fatāwā (4/310).","As for the statement of Allah, the Exalted:","“Immortal youths will circulate among them.”","[al-Wāqiʿah 56:17]","And His statement:","“Immortal youths will circulate among them; when you see them, you would think them scattered pearls.”","[al-Insān 76:19]","the author explains that these are beings created by Allah, the Exalted, in Paradise to serve the people of Paradise and attend to their needs. They will be young in age and at the utmost degree of beauty and splendor.","They are not the children of the believers, as is commonly assumed among people, because the children of the believers will be with their fathers and mothers, as Allah, the Exalted, says:","“Those who believed and whose descendants followed them in faith—We will join their descendants with them.”","[al-Ṭūr 52:21]","They will be in the condition mentioned in the hadith of Maʿdī Karib, namely, at the age of thirty."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطبراني في الكبير (20/ح 663)."},{"num":16424,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، قَالَ:  مَنْ يَدْخُلُ الْجَنَّةَ يَنْعَمُ لَا يَبْأَسُ، لَا تَبْلَى ثِيَابُهُ، وَلَا يَفْنَى شَبَابُهُ."],"takhrij":"صحيح: رواه مسلم في الجنة وصفة نعيمها وأهلها (2836) عن زهير بن حرب، حدثنا عبد الرحمن بن مهدي، حدثنا حماد بن سلمة، عن ثابت، عن أبي رافع، عن أبي هريرة، فذكره.","grade":"صحيح","chapter_ar":"باب أهل الجنة لا يمرضون ولا يهرمون ولا يموتون","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2836).","chapter_en":"The People of Paradise Will Not Become Ill, Grow Old, or Die","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise","part_no":67,"group_no":2,"chapter_no":28,"content":{"translation":{"en":["Abū Hurayrah narrated that the Prophet ﷺ said: “Whoever enters Paradise will live in bliss and never suffer misery. His clothes will never wear out, and his youth will never fade.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (2836)."},{"num":16425,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ، وَأَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:  يُنَادِي مُنَادٍ: إِنَّ لَكُمْ أَنْ تَصِحُّوا فَلَا تَسْقَمُوا أَبَدًا، وَإِنَّ لَكُمْ أَنْ تَحْيَوْا فَلَا تَمُوتُوا أَبَدًا، وَإِنَّ لَكُمْ أَنْ تَشِبُّوا فَلَا تَهْرَمُوا أَبَدًا، وَإِنَّ لَكُمْ أَنْ تَنْعَمُوا فَلَا تَبْتَئِسُوا أَبَدًا. فَذَلِكَ قَوْلُهُ عَزَّ وَجَلَّ: ﴿وَنُودُوا أَنْ تِلْكُمُ الْجَنَّةُ أُورِثْتُمُوهَا بِمَا كُنْتُمْ تَعْمَلُونَ ﴾."],"takhrij":"صحيح: رواه مسلم في الجنة وصفة نعيمها وأهلها (2837) من طرق عن عبد الرزاق قال: قال الثوري: فحدثني أبو إسحاق، أن الأغر حدثه، عن أبي سعيد الخدري وأبي هريرة، فذكراه.","grade":"صحيح","chapter_ar":"باب أهل الجنة لا يمرضون ولا يهرمون ولا يموتون","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2837).","chapter_en":"The People of Paradise Will Not Become Ill, Grow Old, or Die","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise","part_no":67,"group_no":2,"chapter_no":28,"content":{"translation":{"en":["Abū Saʿīd al-Khudrī and Abū Hurayrah narrated that the Prophet ﷺ said: “A caller will proclaim: ‘You shall remain healthy and never become ill. You shall live and never die. You shall remain young and never grow old. And you shall live in bliss and never suffer misery.’” That is the meaning of the statement of Allah, Mighty and Majestic: “They will be called: ‘This is the Paradise which you have inherited for what you used to do.’” [al-Aʿrāf 7:43]"]}},"tuhfa":{},"full":1,"rep":[12334,13254],"tks":"صحيح: رواه مسلم (2837)."},{"num":16426,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قُلْنَا: يَا رَسُولَ اللَّهِ، حَدِّثْنَا عَنِ الْجَنَّةِ، مَا بِنَاؤُهَا؟ قَالَ: لَبِنَةُ ذَهَبٍ وَلَبِنَةُ فِضَّةٍ، وَمِلَاطُهَا الْمِسْكُ الْأَذْفَرُ، وَحَصْبَاؤُهَا اللُّؤْلُؤُ وَالْيَاقُوتُ، وَتُرَابُهَا الزَّعْفَرَانُ، مَنْ يَدْخُلُهَا يَنْعَمُ وَلَا يَبْأَسُ، وَيَخْلُدُ وَلَا يَمُوتُ، لَا تَبْلَى ثِيَابُهُ، وَلَا يَفْنَى شَبَابُهُ."],"takhrij":"حسن: رواه أحمد (8043)، وعبد بن حميد (1420)، وصحّحه ابن حبان (7387) كلهم من طريق زهير بن معاوية، حدثنا أبو مجاهد سعد الطائي، حدثنا أبو المدلة مولى أم المؤمنين، أنه سمع أبا هريرة يقول: فذكره.","grade":"حسن","chapter_ar":"باب أهل الجنة لا يمرضون ولا يهرمون ولا يموتون","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (8043), ʿAbd ibn Ḥumayd (1420), and authenticated by Ibn Ḥibbān (7387).","chapter_en":"The People of Paradise Will Not Become Ill, Grow Old, or Die","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise","part_no":67,"group_no":2,"chapter_no":28,"content":{"translation":{"en":["Abū Hurayrah narrated: We said: “O Messenger of Allah, tell us about Paradise. What is its construction?” He replied: “A brick of gold and a brick of silver. Its mortar is fragrant musk, its pebbles are pearls and rubies, and its soil is saffron. Whoever enters it will live in bliss and never suffer misery, will remain forever and never die, his clothes will never wear out, and his youth will never fade.”"]},"buhuth":{"en":["Regarding the word “mulāṭuhā,” with a kasrah on the letter mīm, it means the mortar that a builder places between each layer of bricks in a wall."]}},"tuhfa":{},"full":1,"dr":1,"rep":[13193,16291],"tks":"حسن: رواه أحمد (8043)، وعبد بن حميد (1420)، وصححه ابن حبان (7387)."},{"num":16427,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : إِنَّ أَوَّلَ زُمْرَةٍ يَدْخُلُونَ الْجَنَّةَ عَلَى صُورَةِ الْقَمَرِ لَيْلَةَ الْبَدْرِ، ثُمَّ الَّذِينَ يَلُونَهُمْ عَلَى أَشَدِّ كَوْكَبٍ دُرِّيٍّ فِي السَّمَاءِ إِضَاءَةً، لاَ يَبُولُونَ وَلاَ يَتَغَوَّطُونَ، وَلاَ يَتْفِلُونَ وَلاَ يَمْتَخِطُونَ، أَمْشَاطُهُمُ الذَّهَبُ، وَرَشْحُهُمُ الْمِسْكُ، وَمَجَامِرُهُمُ الأَلُوَّةُ، وَأَزْوَاجُهُمُ الْحُورُ الْعِينُ، عَلَى خَلْقِ رَجُلٍ وَاحِدٍ، عَلَى صُورَةِ أَبِيهِمْ آدَمَ، سِتُّونَ ذِرَاعًا فِي السَّمَاءِ."],"takhrij":"متفق عليه: رواه البخاري في الأنبياء (3327)، ومسلم في الجنة وصفة نعيمها وأهلها (2834: 15) كلاهما عن قتيبة بن سعيد-وقرنه مسلم بزهير بن حرب- قالا: حدثنا جرير، عن عمارة، عن أبي زرعة، عن أبي هريرة قال: فذكره.","grade":"متفق عليه","chapter_ar":"باب أهل الجنة يأكلون ويشربون، ولكن لا يبولون ولا يتغوطون","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (3327) and Muslim (15 :2834).","chapter_en":"The People of Paradise Will Eat and Drink, but They Will Neither Urinate nor Defecate","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise","part_no":67,"group_no":2,"chapter_no":29,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “The first group to enter Paradise will have the appearance of the full moon. Those who follow them will be like the brightest shining star in the sky. They will neither urinate nor defecate, spit nor blow their noses. Their combs will be of gold, their perspiration will be musk, and their incense burners will contain aloeswood. Their spouses will be the ḥūr al-ʿīn. They will all be of one physical form, upon the form of their father Ādam, sixty cubits tall.”"]},"buhuth":{"en":["The word “al-alūwah” refers to the wood burned as incense, namely Indian aloeswood.","Regarding the phrase “akhlaqahum ʿalā khalqi rajulin wāḥid,” al-Nawawī said:","“Muslim mentioned in his book the difference between Ibn Abī Shaybah and Abū Kurayb in how this word is vocalized. Ibn Abī Shaybah narrated it with a ḍammah on the khāʾ and lām, while Abū Kurayb narrated it with a fatḥah on the khāʾ and a sukūn on the lām. Both readings are correct. The narrators of Ṣaḥīḥ al-Bukhārī also differed concerning it.","The reading with the ḍammah may be supported by the other hadith: ‘There will be no disagreement or hatred among them; their hearts will be one heart.’","The reading with the fatḥah may be supported by the end of the hadith: ‘upon the form of their father Ādam,’ or ‘upon his height.’”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (3327)، ومسلم (2834: 15)."},{"num":16428,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَوَّلُ زُمْرَةٍ تَلِجُ الْجَنَّةَ صُورَتُهُمْ عَلَى صُورَةِ الْقَمَرِ لَيْلَةَ الْبَدْرِ، لاَ يَبْصُقُونَ فِيهَا، وَلاَ يَمْتَخِطُونَ، وَلاَ يَتَغَوَّطُونَ، آنِيَتُهُمْ فِيهَا الذَّهَبُ، أَمْشَاطُهُمْ مِنَ الذَّهَبِ وَالْفِضَّةِ، وَمَجَامِرُهُمُ الأَلُوَّةُ، وَرَشْحُهُمُ الْمِسْكُ، وَلِكُلِّ وَاحِدٍ مِنْهُمْ زَوْجَتَانِ، يُرَى مُخُّ سُوقِهِمَا مِنْ وَرَاءِ اللَّحْمِ، مِنَ الْحُسْنِ، لاَ اخْتِلاَفَ بَيْنَهُمْ وَلاَ تَبَاغُضَ، قُلُوبُهُمْ قَلْبٌ وَاحِدٌ، يُسَبِّحُونَ اللَّهَ بُكْرَةً وَعَشِيًّا."],"takhrij":"متفق عليه: رواه البخاري في بدء الخلق (3245)، ومسلم في الجنة وصفة نعيمها وأهلها (2834: 17) كلاهما من طريق معمر، عن همام بن منبه قال: هذا ما حدثنا أبو هريرة عن رسول الله صلى الله عليه وسلم، فذكر أحاديث منها، فذكره.","grade":"متفق عليه","chapter_ar":"باب أهل الجنة يأكلون ويشربون، ولكن لا يبولون ولا يتغوطون","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (3245) and Muslim (17:2834).","chapter_en":"The People of Paradise Will Eat and Drink, but They Will Neither Urinate nor Defecate","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise","part_no":67,"group_no":2,"chapter_no":29,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “The first group to enter Paradise will have the appearance of the full moon. They will neither spit, blow their noses, nor defecate therein. Their vessels will be of gold, their combs of gold and silver, their incense burners will contain aloeswood, and their perspiration will be musk. Each one of them will have two wives, and because of their beauty the marrow of their shins will be visible through the flesh. There will be no disagreement or hatred among them. Their hearts will be as one heart, glorifying Allah morning and evening.”"]}},"tuhfa":{},"full":1,"rep":[13468],"tks":"متفق عليه: رواه البخاري (3245)، ومسلم (2834: 17)."},{"num":16429,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ قَالَ: سَمِعْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ:  إِنَّ أَهْلَ الْجَنَّةِ يَأْكُلُونَ فِيهَا وَيَشْرَبُونَ، وَلَا يَتْفُلُونَ، وَلَا يَبُولُونَ، وَلَا يَتَغَوَّطُونَ، وَلَا يَمْتَخِطُونَ. قَالُوا: فَمَا بَالُ الطَّعَامِ؟ قَالَ: جُشَاءٌ، وَرَشْحٌ كَرَشْحِ الْمِسْكِ، يُلْهَمُونَ التَّسْبِيحَ وَالتَّحْمِيدَ، كَمَا تُلْهَمُونَ النَّفَسَ."],"takhrij":"صحيح: رواه مسلم في الجنة وصفة نعيمها وأهلها (2835) من طرق عن جرير، عن الأعمش، عن أبي سفيان، عن جابر بن عبد الله قال: فذكره.","grade":"صحيح","chapter_ar":"باب أهل الجنة يأكلون ويشربون، ولكن لا يبولون ولا يتغوطون","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2835).","chapter_en":"The People of Paradise Will Eat and Drink, but They Will Neither Urinate nor Defecate","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise","part_no":67,"group_no":2,"chapter_no":29,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh narrated: I heard the Prophet ﷺ say: “The people of Paradise will eat and drink therein, but they will neither spit, urinate, defecate, nor blow their noses.” They asked: “Then what becomes of the food?” He replied: “It will be discharged as belching and perspiration like the fragrance of musk. They will be inspired to glorify and praise Allah just as you are inspired to breathe.”"]}},"tuhfa":{},"full":1,"rep":[11896],"tks":"صحيح: رواه مسلم (2835)."},{"num":16430,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ يَهُودِيًّا سَأَلَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، ، فَقَالَ: إِلَامَ يَصِيرُ طَعَامُ أَهْلِ الْجَنَّةِ؟ قَالَ: يَصِيرُ رَشْحًا مِثْلَ حُبَابِ الْمِسْكِ."],"takhrij":"حسن: رواه البزار (7675)، والطبراني في مسند الشاميين (1714) من طريق عمرو بن الحارث-، والطبراني وأبو نعيم في صفة الجنة (334) من طريق أبي التقي عبدالحميد بن إبراهيم-، كلاهما عن عبد الله بن سالم (وهو الأشعري الحمصي)، عن الزبيدي – واسمه محمد بن الوليد- قال: أخبرني الزهري، عن أبي سلمة وسعيد, عن أبي هريرة، فذكره.","grade":"حسن","chapter_ar":"باب أهل الجنة يأكلون ويشربون، ولكن لا يبولون ولا يتغوطون","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Hasan: Narrated by al-Bazzār (7675) and al-Ṭabarānī in Musnad al-Shāmiyyīn (1714).","chapter_en":"The People of Paradise Will Eat and Drink, but They Will Neither Urinate nor Defecate","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise","part_no":67,"group_no":2,"chapter_no":29,"content":{"translation":{"en":["Abū Hurayrah narrated that a Jewish man asked the Messenger of Allah ﷺ: “What does the food of the people of Paradise become?” He replied: “It becomes perspiration like droplets of musk.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه البزار (7675)، والطبراني في مسند الشاميين (1714)."},{"num":16431,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ، قَالَ: قِيلَ: يَا رَسُولَ اللَّهِ، هَلْ يَنَامُ أَهْلُ الْجَنَّةِ؟ قَالَ: لا، النَّوْمُ أَخُو الْمَوْتِ."],"takhrij":"حسن: رواه البزار –كشف الأستار (3517) عن الفضل بن يعقوب، حدثنا محمد بن يوسف الفريابي، عن سفيان، عن محمد بن المنكدر، عن جابر فذكره.","grade":"حسن","chapter_ar":"باب أهل الجنة لا ينامون","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Hasan: Narrated by al-Bazzār in Kashf al-Astār (3517).","chapter_en":"The People of Paradise Will Not Sleep","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise","part_no":67,"group_no":2,"chapter_no":30,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh narrated: It was asked: “O Messenger of Allah, will the people of Paradise sleep?” He replied: “No. Sleep is the brother of death.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[13255],"tks":"حسن: رواه البزار في كشف الأستار (3517)."},{"num":16432,"demo":false,"sanad":"","matn":["عَنْ مُحَمَّدٍ قَالَ:  إِمَّا تَفَاخَرُوا وَإِمَّا تَذَاكَرُوا: الرِّجَالُ فِي الْجَنَّةِ أَكْثَرُ أَمِ النِّسَاءُ؟ فَقَالَ أَبُو هُرَيْرَةَ: أَوَلَمْ يَقُلْ أَبُو الْقَاسِمِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّ أَوَّلَ زُمْرَةٍ تَدْخُلُ الْجَنَّةَ عَلَى صُورَةِ الْقَمَرِ لَيْلَةَ الْبَدْرِ، وَالَّتِي تَلِيهَا عَلَى أَضْوَإِ كَوْكَبٍ دُرِّيٍّ فِي السَّمَاءِ، لِكُلِّ امْرِئٍ مِنْهُمْ زَوْجَتَانِ اثْنَتَانِ، يُرَى مُخُّ سُوقِهِمَا مِنْ وَرَاءِ اللَّحْمِ، وَمَا فِي الْجَنَّةِ أَعْزَبُ."],"takhrij":"صحيح: رواه مسلم في الجنة وصفة نعيمها وأهلها (2834) من طرق عن إسماعيل بن علية، أخبرنا أيوب، عن محمد بن سيرين قال: فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في صفة نساء أهل الجنة","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2834).","chapter_en":"What Has Been Narrated Concerning the Description of the Women of Paradise","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise","part_no":67,"group_no":2,"chapter_no":31,"content":{"translation":{"en":["Muḥammad ibn Sīrīn narrated: The people were either boasting or discussing whether men or women would be more numerous in Paradise. Abū Hurayrah said: “Did Abū al-Qāsim ﷺ not say: ‘The first group to enter Paradise will have the appearance of the full moon, and the group after them will be like the brightest shining star in the sky. Every man among them will have two wives, and the marrow of their shins will be visible through the flesh. There will be no unmarried person in Paradise.’”"]},"intro":{"ar":["قال اللّٰه تعالى:","﴿وَحُورٌ عِينٌ ۝ كَأَمْثَالِ اللُّؤْلُؤِ الْمَكْنُونِ﴾ [سورة الواقعة: ٢٢-٢٣].","وقال تعالى:","﴿وَعِنْدَهُمْ قَاصِرَاتُ الطَّرْفِ أَتْرَابٌ﴾ [سورة ص: ٥٢].","وقال تعالى:","﴿فِيهِنَّ خَيْرَاتٌ حِسَانٌ ۝ فَبِأَيِّ آلَاءِ رَبِّكُمَا تُكَذِّبَانِ ۝ حُورٌ مَقْصُورَاتٌ فِي الْخِيَامِ ۝ فَبِأَيِّ آلَاءِ رَبِّكُمَا تُكَذِّبَانِ ۝ لَمْ يَطْمِثْهُنَّ إِنْسٌ قَبْلَهُمْ وَلَا جَانٌّ﴾ [سورة الرحمن: ٧٠-٧٤].","وقال تعالى:","﴿وَالَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ سَنُدْخِلُهُمْ جَنَّاتٍ تَجْرِي مِنْ تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا أَبَدًا لَهُمْ فِيهَا أَزْوَاجٌ مُطَهَّرَةٌ وَنُدْخِلُهُمْ ظِلًّا ظَلِيلًا﴾ [سورة النساء: ٥٧]."],"en":["Allah, the Exalted, says:","“And fair women with wide, beautiful eyes, like well-protected pearls.”","[al-Wāqiʿah 56:22-23]","And He, the Exalted, says:","“And with them will be women who restrain their glances, equal in age.”","[Ṣād 38:52]","And He, the Exalted, says:","“In them are good and beautiful women. So which of the favors of your Lord will you both deny? Fair women secluded in pavilions. So which of the favors of your Lord will you both deny? No human or jinn has touched them before.”","[al-Raḥmān 55:70-74]","And He, the Exalted, says:","“Those who believe and perform righteous deeds, We will admit them into Gardens beneath which rivers flow, remaining therein forever. They will have purified spouses therein, and We will admit them into deep shade.”","[al-Nisāʾ 4:57]"]}},"tuhfa":{},"full":1,"dr":1,"rep":[13469],"tks":"صحيح: رواه مسلم (2834)."},{"num":16433,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، قَالَ: لِلرَّجُلِ مِنْ أَهْلِ الْجَنَّةِ زَوْجَتَانِ مِنْ حُورِ الْعِينِ، عَلَى كُلِّ وَاحِدَةٍ سَبْعُونَ حُلَّةً، يُرَى مُخُّ سَاقِهَا مِنْ وَرَاءِ الثِّيَابِ."],"takhrij":"صحيح: رواه أحمد (8542) عن عفان، حدثنا حماد بن سلمة، أخبرنا يونس، عن محمد بن سيرين، عن أبي هريرة، فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب ما جاء في صفة نساء أهل الجنة","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by Aḥmad (8542).","chapter_en":"What Has Been Narrated Concerning the Description of the Women of Paradise","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise","part_no":67,"group_no":2,"chapter_no":31,"content":{"translation":{"en":["Abū Hurayrah narrated that the Prophet ﷺ said: “A man from the people of Paradise will have two wives from the ḥūr al-ʿīn. Each one will wear seventy garments, yet the marrow of her shin will be visible through the garments.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[13471],"tks":"صحيح: رواه أحمد (8542)."},{"num":16434,"demo":false,"sanad":"","matn":["عَنْ أنس قَالَ: قَالَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : غَدْوَةٌ فِي سَبِيلِ اللَّهِ أَوْ رَوْحَةٌ خَيْرٌ مِنَ الدُّنْيَا وَمَا فِيهَا، ولَقَابَ قوسِ أَحَدِكُمْ أَوْ مَوْضِعُ قَدَمٍ مِنَ الْجَنَّةِ خَيْرٌ مِنَ الدُّنْيَا وَمَا فِيهَا، وَلَوْ أَنَّ امْرَأَةً مِنْ نِسَاءِ أَهْلِ الْجَنَّةِ اطَّلَعَتْ إِلَى الأَرْضِ لأَضَاءَتْ مَا بَيْنَهُمَا، وَلَمَلأَتْ مَا بَيْنَهُمَا رِيحًا، وَلَنَصِيفُهَا - يَعْنِي الْخِمَارَ- خَيْرٌ مِنَ الدُّنْيَا وَمَا فِيهَا."],"takhrij":"صحيح: رواه البخاري في الرقاق (6568) عن قتيبة، عن إسماعيل بن جعفر، عن حميد، عن أنس، فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في صفة نساء أهل الجنة","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (6568).","chapter_en":"What Has Been Narrated Concerning the Description of the Women of Paradise","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise","part_no":67,"group_no":2,"chapter_no":31,"content":{"translation":{"en":["Anas narrated that the Messenger of Allah ﷺ said: “A morning journey in the path of Allah or an evening journey is better than the world and everything in it. The space occupied by the bow of one of you, or a single footstep in Paradise, is better than the world and everything in it. And if a woman from among the women of Paradise were to look toward the earth, she would illuminate everything between them and fill everything between them with fragrance. Even her head-covering is better than the world and everything in it.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[16306],"tks":"صحيح: رواه البخاري (6568)."},{"num":16435,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، قَالَ: أَوَّلُ زُمْرَةٍ يَدْخُلُ الْجَنَّةَ مِنْ أُمَّتِي وُجُوهُهُمْ كَالْقَمَرِ لَيْلَةَ الْبَدْرِ، وَالزُّمْرَةُ الثَّانِيَةُ كَأَحْسَنِ كَوَكْبٍ دُرِّيٍّ فِي السَّمَاءِ، لِكُلِّ امْرِئٍ مِنْهُمْ زَوْجَتَانِ، عَلَى كُلِّ زَوْجَةٍ سَبْعُونَ حُلَّةً، يُرَى مُخُّ سُوقِهِنَّ مِنْ وَرَاءِ الْحُلَلِ، كَمَا تَرَى الشَّرَابَ الأَحْمَرَ فِي الزُّجَاجَةِ الْبَيْضَاءِ."],"takhrij":"حسن: رواه البزار (1855)، والطبراني في الكبير (10/198-199)، وأبو نعيم في صفة الجنة (254) كلهم من طريق فضيل بن مرزوق، عن أبي إسحاق، عن عمرو بن ميمون، عن عبد الله بن مسعود، فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في صفة نساء أهل الجنة","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Hasan: Narrated by al-Bazzār (1855), al-Ṭabarānī in al-Muʿjam al-Kabīr (10/198-199), and Abū Nuʿaym in Ṣifat al-Jannah (254).","chapter_en":"What Has Been Narrated Concerning the Description of the Women of Paradise","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise","part_no":67,"group_no":2,"chapter_no":31,"content":{"translation":{"en":["ʿAbdullāh ibn Masʿūd narrated that the Prophet ﷺ said: “The first group from my Ummah to enter Paradise will have faces like the full moon, and the second group will be like the most beautiful shining star in the sky. Each man among them will have two wives. Each wife will wear seventy garments, yet the marrow of their shins will be visible through those garments, just as red drink can be seen through a clear white glass vessel.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه البزار (1855)، والطبراني في الكبير (10/198-199)، وأبو نعيم في صفة الجنة (254)."},{"num":16436,"demo":false,"sanad":"","matn":["عن سَعِيدِ بْنِ عَامِرٍ بن حذيم قَالَ: بَلَغَ عُمَرُ أَنَّهُ لَا يَدَّخِرُ فِي بَيْتِهِ مِنَ الْحَاجَةِ، فَبَعَثَ إِلَيْهِ بِعَشَرَةِ آلَافٍ، فَأَخَذَهَا، فَجَعَلَ يُفَرِّقُهَا صُرَرًا، فَقَالَتْ لَهُ امْرَأَتُهُ: أَيْنَ تَذْهَبُ بِهَذِهِ؟ قَالَ: أَذْهَبُ بِهَا إِلَى مَنْ يُرَجِّحُ لَنَا فِيهَا، فَمَا أُبْقِي لَنَا إِلَّا شَيْئًا يَسِيرًا. فَلَمَّا نَفَدَ الَّذِي كَانَ عِنْدَهُمْ قَالَتْ لَهُ امْرَأَتُهُ: اذْهَبْ إِلَى بَعْضِ أَصْحَابِكَ الَّذِينَ أَعْطَيْتَهُمْ يُرَجِّحُونَ لَكَ، فَخُذْ مِنْ أَرْبَاحِهِمْ. وَجَعَلَ يُدَافِعُهَا وَيُمَاطِلُهَا حَتَّى طَالَ ذَلِكَ، فَقَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: يَقُولُ: لَوْ أَنَّ حَوْرَاءَ أَطْلَعَتْ أُصْبُعًا مِنْ أَصَابِعِهَا لَوَجَدَ رِيحَهَا كُلُّ ذِي رُوحٍ، فَأَنَا أَدَعُهُنَّ، لَكُنَّ، لَا وَاللَّهِ لَأَنْتُنَّ أَحَقُّ أَنْ أَدَعَكُنَّ لَهُنَّ مِنْهُنَّ لَكُنَّ."],"takhrij":"حسن: رواه أبو يعلى كما في المطالب العالية (4608)، والطبراني في الكبير (5511) –واللفظ له-، وأبو نعيم في الحلية (1/246-247) كلهم من طريق أبي معاوية محمد بن خازم، عن موسى بن قيس الصغير، عن عبد الرحمن بن سابط، عن سعيد بن عامر بن حذيم قال: فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في صفة نساء أهل الجنة","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Yaʿlā, as cited in al-Maṭālib al-ʿĀliyah (4608), al-Ṭabarānī in al-Muʿjam al-Kabīr (6/71-72), whose wording this is, and Abū Nuʿaym in al-Ḥilyah (1/246-247).","chapter_en":"What Has Been Narrated Concerning the Description of the Women of Paradise","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise","part_no":67,"group_no":2,"chapter_no":31,"content":{"translation":{"en":["Saʿīd ibn ʿĀmir ibn Ḥudhaym narrated: ʿUmar learned that Saʿīd kept nothing in his home beyond what was needed, so he sent him ten thousand. Saʿīd took it and began dividing it into small bundles. His wife asked: “Where are you taking this?” He replied: “I am giving it to those who will make it yield greater profit for us.” He kept only a very small amount. When what they had was exhausted, his wife said: “Go to some of your companions to whom you gave the money so that they can make a profit for you, and take from its returns.” He kept delaying her and putting her off for a long time, then said: “I heard the Messenger of Allah ﷺ say: ‘If a ḥūrī were merely to reveal one of her fingers, every living creature would smell its fragrance.’ So I am abandoning them? By Allah, you women are even more deserving that I abandon you for them than they are.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو يعلى كما في المطالب العالية (4608)، والطبراني في الكبير (5488) - واللفظ له -، وأبو نعيم في الحلية (1/246-247)."},{"num":16437,"demo":false,"sanad":"","matn":["عَنْ سَعِيدِ بْنِ عَامِرِ بْنِ حِذْيَمٍ قَالَ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  يَقُولُ: لَوْ أَنَّ امْرَأَةً مِنْ أَهْلِ الْجَنَّةِ أَشْرَفَتْ إِلَى أَهْلِ الْأَرْضِ لَمَلَأَتِ الْأَرْضَ رِيحَ مِسْكٍ، وَلَأَذْهَبَتْ ضَوْءَ الشَّمْسِ وَالْقَمَرِ، وَإِنِّي وَاللهِ مَا كُنْتُ لِأَخْتَارَكِ عَلَيْهِنَّ، وَدَفَعَ فِي صَدْرِهَا - يَعْنِي امْرَأَتَهُ."],"takhrij":"حسن: رواه البزار في كشف الأستار (3528)، والطبراني في الكبير (5512) كلاهما من طريق حماد بن الحسن بن عنبسة الوراق، ثنا سيار بن حاتم، ثنا جعفر بن سليمان والحارث بن نبهان، عن مالك بن دينار، عن شهر بن حوشب، عن سعيد بن عامر بن حذيم، فذكره. واللفظ للطبراني، ولفظ البزار مختصر.","grade":"حسن","chapter_ar":"باب ما جاء في صفة نساء أهل الجنة","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Hasan: Narrated by al-Bazzār in Kashf al-Astār (3528) and al-Ṭabarānī in al-Muʿjam al-Kabīr (6/72).","chapter_en":"What Has Been Narrated Concerning the Description of the Women of Paradise","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise","part_no":67,"group_no":2,"chapter_no":31,"content":{"translation":{"en":["Saʿīd ibn ʿĀmir ibn Ḥudhaym narrated: I heard the Messenger of Allah ﷺ say: “If a woman from among the people of Paradise were to look down upon the people of the earth, she would fill the earth with the fragrance of musk and would overwhelm the light of the sun and the moon.” Saʿīd then said to his wife: “By Allah, I would never choose you over them,” and he pushed her in the chest."]},"buhuth":{"en":["Regarding the phrase “his wife,” the author clarifies that it refers to the wife of Saʿīd ibn ʿĀmir, and that it was her husband Saʿīd who pushed her in the chest."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه البزار في كشف الأستار (3528)، والطبراني في الكبير (5512)."},{"num":16438,"demo":false,"sanad":"","matn":["عَنْ زَيْدِ بْنِ أَرْقَمَ قَالَ: أَتَى النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَجُلٌ مِنَ الْيَهُودِ، فَقَالَ: يَا أَبَا الْقَاسِمِ، أَلَسْتَ تَزْعُمُ أَنَّ أَهْلَ الْجَنَّةِ يَأْكُلُونِ فِيهَا وَيَشْرَبُونَ؟ وَقَالَ لِأَصْحَابِهِ: إِنْ أَقَرَّ لِي بِهَذِهِ خَصَمْتُهُ. قَالَ: فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: بَلَى وَالَّذِي نَفْسِي بِيَدِهِ، إِنَّ أَحَدَهُمْ لَيُعْطَى قُوَّةَ مِائَةِ رَجُلٍ فِي الْمَطْعَمِ وَالْمَشْرَبِ وَالشَّهْوَةِ وَالْجِمَاعِ. قَالَ: فَقَالَ لَهُ الْيَهُودِيُّ: فَإِنَّ الَّذِي يَأْكُلُ وَيَشْرَبُ تَكُونُ لَهُ الْحَاجَةُ. قَالَ: فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: حَاجَةُ أَحَدِهِمْ عَرَقٌ يَفِيضُ مِنْ جُلُودِهِمْ مِثْلُ رِيحِ الْمِسْكِ، فَإِذَا الْبَطْنُ قَدْ ضَمُرَ."],"takhrij":"صحيح: رواه أحمد (19269)، وابن حبان (7424)، وأبو نعيم في صفة الجنة (329) كلهم من حديث أبي معاوية، حدثنا الأعمش، عن ثمامة بن عقبة المحلمي، عن زيد بن أرقم قال: فذكره. واللفظ لأحمد. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب ما جاء في جماع أهل الجنة","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by Aḥmad (19269), Ibn Ḥibbān (7424), and Abū Nuʿaym in Ṣifat al-Jannah (329).","chapter_en":"What Has Been Narrated Concerning Sexual Intercourse of the People of Paradise","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise","part_no":67,"group_no":2,"chapter_no":32,"content":{"translation":{"en":["Zayd ibn Arqam narrated: A Jewish man came to the Prophet ﷺ and said: “O Abū al-Qāsim, do you not claim that the people of Paradise will eat and drink there?” He said to his companions: “If he admits this to me, I will defeat him in argument.” The Messenger of Allah ﷺ replied: “Yes, by the One in whose hand is my soul, each one of them will be given the strength of one hundred men in eating, drinking, desire, and sexual intercourse.” The Jewish man said: “But one who eats and drinks must relieve himself.” The Messenger of Allah ﷺ replied: “The relief of one of them will be perspiration flowing from his skin with the fragrance of musk, and then his abdomen will become flat.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه أحمد (19269)، وابن حبان (7424)، وأبو نعيم في صفة الجنة (329)."},{"num":16439,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ يُعْطَى الْمُؤْمِنُ فِي الْجَنَّةِ قُوَّةَ كَذَا وَكَذَا مِنَ الْجِمَاعِ. قِيلَ: يَا رَسُولَ اللَّهِ، أَوَيُطِيقُ ذَلِكَ؟ قَالَ: يُعْطَى قُوَّةَ مِائَةٍ."],"takhrij":"حسن: رواه الترمذي (2536)، وأبو داود الطيالسي (2124) وابن حبان (7400) كلهم من طريق عمران القطان، عن قتادة، عن أنس، فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في جماع أهل الجنة","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhī (2536), Abū Dāwūd al-Ṭayālisī (2124), and Ibn Ḥibbān (7400).","chapter_en":"What Has Been Narrated Concerning Sexual Intercourse of the People of Paradise","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise","part_no":67,"group_no":2,"chapter_no":32,"content":{"translation":{"en":["Anas narrated that the Prophet ﷺ said: “The believer in Paradise will be given such-and-such strength for sexual intercourse.” It was asked: “O Messenger of Allah, will he really be capable of that?” He replied: “He will be given the strength of one hundred.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الترمذي (2536)، وأبو داود الطيالسي (2124) وابن حبان (7400)."},{"num":16440,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، أَنَّهُ قِيلَ لَهُ: أَنَطَأُ فِي الْجَنَّةِ؟ قَالَ: نَعَمْ، وَالَّذِي نَفْسِي بِيَدِهِ دَحْمًا دَحْمًا، فَإِذَا قَامَ عَنْهَا رَجَعَتْ مُطَهَّرَةً بِكْرًا."],"takhrij":"حسن: رواه ابن حبان (7402)، وأبو نعيم في صفة الجنة (393) كلاهما من طريق ابن وهب قال: أخبرني عمرو بن الحارث، عن دراج، عن ابن حجيرة، عن أبي هريرة، فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في جماع أهل الجنة","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Ḥibbān (7402) and Abū Nuʿaym in Ṣifat al-Jannah (393).","chapter_en":"What Has Been Narrated Concerning Sexual Intercourse of the People of Paradise","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise","part_no":67,"group_no":2,"chapter_no":32,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ was asked: “Will there be sexual intercourse in Paradise?” He replied: “Yes, by the One in whose hand is my soul, vigorously and repeatedly. When he rises from her, she will return purified and a virgin.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[13488],"tks":"حسن: رواه ابن حبان (7402)، وأبو نعيم في صفة الجنة (393)."},{"num":16441,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ: قِيلَ: يَا رَسُولَ اللَّهِ، أَنُفْضِي إِلَى نِسَائِنَا فِي الْجَنَّةِ، قَالَ: إِي وَالَّذِي نَفْسِي بِيَدِهِ، إِنَّ الرَّجُلَ لَيُفْضِي فِي الْيَوْمِ الْوَاحِدِ إِلَى مِائَةِ عَذْرَاءَ."],"takhrij":"صحيح: رواه البزار (10072)، والطبراني في الصغير (795)، وفي الأوسط (722) كلاهما من طريق حسين بن علي الجعفي، عن زائدة, عن هشام بن حسان, عن محمد بن سيرين, عن أبي هريرة قال: فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب ما جاء في جماع أهل الجنة","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bazzār (10072), al-Ṭabarānī in al-Muʿjam al-Ṣaghīr (795), and al-Muʿjam al-Awsaṭ (722).","chapter_en":"What Has Been Narrated Concerning Sexual Intercourse of the People of Paradise","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise","part_no":67,"group_no":2,"chapter_no":32,"content":{"translation":{"en":["Abū Hurayrah narrated: It was asked: “O Messenger of Allah, will we have intimate relations with our wives in Paradise?” He replied: “Yes, by the One in whose hand is my soul, a man will have intimate relations with one hundred virgins in a single day.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[13487],"tks":"صحيح: رواه البزار (10072)، والطبراني في الصغير (795)، وفي الأوسط (722)."},{"num":16442,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: الْمُؤْمِنُ إِذَا اشْتَهَى الْوَلَدَ فِي الْجَنَّةِ كَانَ حَمْلُهُ وَوَضْعُهُ وَسِنُّهُ فِي سَاعَةٍ كَمَا يَشْتَهِي."],"takhrij":"حسن: رواه الترمذي (2563)، وابن ماجه (4338)، وأحمد (11063)، وابن حبان (7404) كلهم من طريق معاذ بن هشام قال: حدثني أبي، عن عامر الأحول، عن أبي الصديق الناجي، عن أبي سعيد الخدري فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في الحمل والولادة في الجنة","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhī (2563), Ibn Mājah (4338), Aḥmad (11063), and Ibn Ḥibbān (7404).","chapter_en":"What Has Been Narrated Concerning Pregnancy and Childbirth in Paradise","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise","part_no":67,"group_no":2,"chapter_no":33,"content":{"translation":{"en":["Abū Saʿīd al-Khudrī narrated that the Messenger of Allah ﷺ said: “If a believer desires a child in Paradise, its pregnancy, birth, and reaching the age he desires will all take place within a single hour, exactly as he wishes.”"]},"buhuth":{"en":["The author states that this hadith indicates the occurrence of pregnancy and childbirth in Paradise for whoever among its people desires that, and that the general purport of the Qurʾānic texts also indicates this."]},"intro":{"ar":["قال تعالى:","﴿لَهُمْ مَا يَشَاءُونَ فِيهَا وَلَدَيْنَا مَزِيدٌ﴾ [سورة ق: ٣٥].","قوله: ﴿لَهُمْ مَا يَشَاءُونَ فِيهَا﴾ أي: أنهم يجدون فيها جميع أصناف الملاذ، وكلما طلبوا أحضر لهم، قال تعالى:","﴿وَلَكُمْ فِيهَا مَا تَشْتَهِي أَنْفُسُكُمْ وَلَكُمْ فِيهَا مَا تَدَّعُونَ﴾ [فصلت: ٣١]."],"en":["Allah, the Exalted, says:","“They will have whatever they wish therein, and with Us is even more.”","[Qāf 50:35]","Regarding His statement:","“They will have whatever they wish therein,”","the author explains that they will find therein every kind of pleasure, and whatever they request will be brought to them.","Allah, the Exalted, says:","“You will have therein whatever your souls desire, and you will have therein whatever you ask for.”","[Fuṣṣilat 41:31]"]}},"tuhfa":{},"full":1,"dr":1,"rep":[13391],"tks":"حسن: رواه الترمذي (2563)، وابن ماجه (4338)، وأحمد (11063)، وابن حبان (7404)."},{"num":16443,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، رَضِيَ اللَّهُ عَنْهُ أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَوْمًا يُحَدِّثُ، وَعِنْدَهُ رَجُلٌ مِنْ أَهْلِ الْبَادِيَةِ: أَنَّ رَجُلاً مِنْ أَهْلِ الْجَنَّةِ اسْتَأْذَنَ رَبَّهُ فِي الزَّرْعِ، فَقَالَ لَهُ: أَلَسْتَ فِيمَا شِئْتَ؟ قَالَ: بَلَى، وَلَكِنِّي أُحِبُّ أَنْ أَزْرَعَ. قَالَ فَبَذَرَ فَبَادَرَ الطَّرْفَ نَبَاتُهُ وَاسْتِوَاؤُهُ وَاسْتِحْصَادُهُ، فَكَانَ أَمْثَالَ الْجِبَالِ، فَيَقُولُ اللَّهُ دُونَكَ يَا ابْنَ آدَمَ، فَإِنَّهُ لاَ يُشْبِعُكَ شَىْءٌ. فَقَالَ الأَعْرَابِيُّ: وَاللَّهِ لاَ تَجِدُهُ إِلاَّ قُرَشِيًّا أَوْ أَنْصَارِيًّا، فَإِنَّهُمْ أَصْحَابُ زَرْعٍ، وَأَمَّا نَحْنُ فَلَسْنَا بِأَصْحَابِ زَرْعٍ. فَضَحِكَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ."],"takhrij":"صحيح: رواه البخاري في الحرث والزراعة (2348) وفي التوحيد bukhari(7519) من طرق عن فليح، حدثنا هلال، عن عطاء بن يسار، عن أبي هريرة، فذكره.","grade":"صحيح","chapter_ar":"باب من أهل الجنة من يرغب في الزراعة","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (2348) and (7519).","chapter_en":"Some of the People of Paradise Will Desire Farming","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise","part_no":67,"group_no":2,"chapter_no":34,"content":{"translation":{"en":["Abū Hurayrah narrated: One day the Prophet ﷺ was speaking while a Bedouin man was present. He said: “A man from the people of Paradise will ask his Lord for permission to farm. Allah will say to him: ‘Are you not already enjoying whatever you desire?’ He will reply: ‘Yes, but I love farming.’ So he will quickly sow the seed, and in the blink of an eye it will sprout, mature, be harvested, and gathered into heaps like mountains. Allah, the Exalted, will say: ‘Take it, O son of Ādam, for nothing ever satisfies you.’” The Bedouin said: “O Messenger of Allah, you will only find such a man to be from Quraysh or the Anṣār, because they are farmers. As for us, we are not farmers.” The Messenger of Allah ﷺ laughed."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (2348، 7519)."},{"num":16444,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ قَالَ: سَمِعْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ:  إِنَّ أَهْلَ الْجَنَّةِ يَأْكُلُونَ فِيهَا وَيَشْرَبُونَ، وَلَا يَتْفُلُونَ، وَلَا يَبُولُونَ، وَلَا يَتَغَوَّطُونَ، وَلَا يَمْتَخِطُونَ. قَالُوا: فَمَا بَالُ الطَّعَامِ؟ قَالَ: جُشَاءٌ، وَرَشْحٌ كَرَشْحِ الْمِسْكِ، يُلْهَمُونَ التَّسْبِيحَ وَالتَّحْمِيدَ، كَمَا تُلْهَمُونَ النَّفَسَ.","وفي لفظ: ويلهمون التسبيح والتكبير، كما يلهمون النفس."],"takhrij":"صحيح: رواه مسلم في الجنة وصفة نعيمها وأهلها (2835: 18) من طرق عن جرير، عن الأعمش، عن أبي سفيان، عن جابر بن عبد الله قال: فذكره.","grade":"صحيح","chapter_ar":"باب أهل الجنة يلهمون التسبيح والتحميد كما تلهمون النفس","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (20, 18 :2835).","chapter_en":"The People of Paradise Will Be Inspired to Glorify and Praise Allah Just as You Are Inspired to Breathe","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise","part_no":67,"group_no":2,"chapter_no":35,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh narrated: I heard the Prophet ﷺ say: “The people of Paradise will eat and drink therein, but they will neither spit, urinate, defecate, nor blow their noses.” They asked: “Then what becomes of the food?” He replied: “It will be discharged as belching and perspiration like the fragrance of musk. They will be inspired to glorify and praise Allah just as you are inspired to breathe.” In another wording: “They will be inspired to glorify Allah and proclaim His greatness just as they are inspired to breathe.”"]},"intro":{"ar":["قال اللّٰه تعالى:","﴿إِنَّ الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ يَهْدِيهِمْ رَبُّهُمْ بِإِيمَانِهِمْ تَجْرِي مِنْ تَحْتِهِمُ الْأَنْهَارُ فِي جَنَّاتِ النَّعِيمِ ۝ دَعْوَاهُمْ فِيهَا سُبْحَانَكَ اللَّهُمَّ وَتَحِيَّتُهُمْ فِيهَا سَلَامٌ وَآخِرُ دَعْوَاهُمْ أَنِ الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ﴾ [سورة يونس: ٩-١٠]."],"en":["Allah, the Exalted, says:","“Indeed, those who believe and perform righteous deeds—their Lord will guide them by their faith. Rivers will flow beneath them in Gardens of Bliss. Their prayer therein will be: ‘Glory be to You, O Allah,’ and their greeting therein will be: ‘Peace,’ and the conclusion of their prayer will be: ‘All praise belongs to Allah, Lord of the worlds.’”","[Yūnus 10:9-10]"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (20، 18 :2835)."},{"num":16445,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّ اللَّهَ يَقُولُ لأَهْلِ الْجَنَّةِ: يَا أَهْلَ الْجَنَّةِ. فَيَقُولُونَ: لَبَّيْكَ رَبَّنَا، وَسَعْدَيْكَ، وَالْخَيْرُ فِي يَدَيْكَ. فَيَقُولُ: هَلْ رَضِيتُمْ؟ فَيَقُولُونَ: وَمَا لَنَا لاَ نَرْضَى يَا رَبِّ وَقَدْ أَعْطَيْتَنَا مَا لَمْ تُعْطِ أَحَدًا مِنْ خَلْقِكَ. فَيَقُولُ: أَلاَ أُعْطِيكُمْ أَفْضَلَ مِنْ ذَلِكَ. فَيَقُولُونَ: يَا رَبِّ وَأَىُّ شَىْءٍ أَفْضَلُ مِنْ ذَلِكَ؟ فَيَقُولُ: أُحِلُّ عَلَيْكُمْ رِضْوَانِي، فَلاَ أَسْخَطُ عَلَيْكُمْ بَعْدَهُ أَبَدًا."],"takhrij":"متفق عليه: رواه البخاري في التوحيد (7518)، ومسلم في الجنة وصفة نعيمها وأهلها (2829) كلاهما من طريق عبد الله بن وهب، حدثني مالك بن أنس، عن زيد بن أسلم، عن عطاء بن يسار، عن أبي سعيد الخدري، فذكره.","grade":"متفق عليه","chapter_ar":"باب لا يسخط الله على أهل الجنة أبدًا","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (7518) and Muslim (2829).","chapter_en":"Allah Will Never Be Angry with the People of Paradise Again","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise","part_no":67,"group_no":2,"chapter_no":36,"content":{"translation":{"en":["Abū Saʿīd al-Khudrī narrated that the Prophet ﷺ said: “Allah will say to the people of Paradise: ‘O people of Paradise!’ They will reply: ‘Here we are at Your service, our Lord, ready to obey You, and all good is in Your Hands.’ He will ask: ‘Are you pleased?’ They will say: ‘Why should we not be pleased, our Lord, when You have given us what You have not given to anyone else among Your creation?’ He will say: ‘Shall I not give you something better than that?’ They will ask: ‘Our Lord, what could be better than that?’ He will say: ‘I bestow My pleasure upon you, and I will never be angry with you after this.’”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (7518)، ومسلم (2829)."},{"num":16446,"demo":false,"sanad":"","matn":["عن جابر بن عبد الله قال: قال رسول الله صلى الله عليه وسلم: إذا دخل أهل الجنة الجنة، قال الله تعالى: هل تشتهون شيئا فأزيدكموه؟ قالوا: يا ربنا، وهل بقي شيء إلا وقد نلناه؟ فيقول: نعم، رضائي، فلا أسخط عليكم أبدا."],"takhrij":"صحيح: رواه ابن حبان (7439)، والحاكم (276)، وأبو نعيم في صفة الجنة (283) والطبري في تفسيره (5/271) كلهم من طرق عن سفيان الثوري، عن محمد بن المنكدر, عن جابر بن عبد الله قال: فذكره.","grade":"صحيح","chapter_ar":"باب لا يسخط الله على أهل الجنة أبدًا","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by Ibn Ḥibbān (7439), al-Ḥākim (1/82), and Abū Nuʿaym in Ṣifat al-Jannah (283).","chapter_en":"Allah Will Never Be Angry with the People of Paradise Again","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise","part_no":67,"group_no":2,"chapter_no":36,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh narrated that the Messenger of Allah ﷺ said: “When the people of Paradise enter Paradise, Allah, the Exalted, will say: ‘Do you desire anything so that I may increase you?’ They will say: ‘Our Lord, is there anything left that we have not already received?’ He will say: ‘Yes—My pleasure. I will never be angry with you again.’”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه ابن حبان (7439)، والحاكم (276)، وأبو نعيم في صفة الجنة (283)."},{"num":16447,"demo":false,"sanad":"","matn":["عَنْ عَدِيِّ بْنِ حَاتِمٍ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:  مَا مِنْكُمْ مِنْ أَحَدٍ إِلَّا سَيُكَلِّمُهُ اللهُ، لَيْسَ بَيْنَهُ وَبَيْنَهُ تُرْجُمَانٌ، فَيَنْظُرُ أَيْمَنَ مِنْهُ، فَلَا يَرَى إِلَّا مَا قَدَّمَ، وَيَنْظُرُ أَشْأَمَ مِنْهُ، فَلَا يَرَى إِلَّا مَا قَدَّمَ، وَيَنْظُرُ بَيْنَ يَدَيْهِ فَلَا يَرَى إِلَّا النَّارَ تِلْقَاءَ وَجْهِهِ، فَاتَّقُوا النَّارَ وَلَوْ بِشِقِّ تَمْرَةٍ."],"takhrij":"متفق عليه: رواه البخــاري في الرقاق (6539)، ومسلم في الزكاة (1016: 67) كلاهما من طريق الأعمش، عن خيثمة، عن عدي بن حاتم قال: فذكره. واللفظ لمسلم ولفظ البخاري نحوه.","grade":"متفق عليه","chapter_ar":"باب الوقاية من النار","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6539) and Muslim (67 :1016).","chapter_en":"Protecting Oneself from the Fire","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة النار","group_en":"A Collection of What Has Been Narrated Concerning the Description of the Fire","part_no":67,"group_no":3,"chapter_no":1,"content":{"translation":{"en":["ʿAdī ibn Ḥātim narrated that the Messenger of Allah ﷺ said: “There is none among you except that Allah will speak to him directly, with no interpreter between him and Allah. He will look to his right and see nothing except what he sent forward. He will look to his left and see nothing except what he sent forward. Then he will look ahead and see nothing except the Fire directly before his face. So protect yourselves from the Fire, even with half a date.”"]},"buhuth":{"en":["Another narration adds:","“And whoever cannot find even that, then with a good word.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (6539)، ومسلم (1016: 67)."},{"num":16448,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:  يُؤْتَى بِجَهَنَّمَ يَوْمَئِذٍ لَهَا سَبْعُونَ أَلْفَ زِمَامٍ، مَعَ كُلِّ زِمَامٍ سَبْعُونَ أَلْفَ مَلَكٍ يَجُرُّونَهَا."],"takhrij":"صحيح: رواه مسلم في الجنة (2842) عن عمر بن حفص بن غياث، حدثنا أبي، عن العلاء بن خالد الكاهلي، عن شقيق، عن عبد الله قال: فذكره.","grade":"صحيح","chapter_ar":"باب أن جهنم لها سبعون ألف زمام","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2842).","chapter_en":"Hell Will Have Seventy Thousand Reins","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة النار","group_en":"A Collection of What Has Been Narrated Concerning the Description of the Fire","part_no":67,"group_no":3,"chapter_no":2,"content":{"translation":{"en":["ʿAbdullāh ibn Masʿūd narrated that the Messenger of Allah ﷺ said: “Hell will be brought forth on that Day with seventy thousand reins, and with every rein will be seventy thousand angels dragging it.”"]}},"tuhfa":{},"full":1,"rep":[12695,13643,13721],"tks":"صحيح: رواه مسلم (2842)."},{"num":16449,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ، قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لاَ تَزَالُ جَهَنَّمُ تَقُولُ: هَلْ مِنْ مَزِيدٍ؟ حَتَّى يَضَعَ رَبُّ الْعِزَّةِ فِيهَا قَدَمَهُ، فَتَقُولُ: قَطْ قَطْ وَعِزَّتِكَ. وَيُزْوَى بَعْضُهَا إِلَى بَعْضٍ."],"takhrij":"متفق عليه: رواه البخاري في الأيمان والنذور (6661)، ومسلم في الجنة (2848: 37) كلاهما من طريق شيبان، حدثنا قتادة، حدثنا أنس بن مالك فذكره. واللفظ لمسلم ولفظ البخاري نحوه.","grade":"متفق عليه","chapter_ar":"باب ما جاء في سعة جهنم","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6661) and Muslim (37 :2848).","chapter_en":"What Has Been Narrated Concerning the Vastness of Hell","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة النار","group_en":"A Collection of What Has Been Narrated Concerning the Description of the Fire","part_no":67,"group_no":3,"chapter_no":3,"content":{"translation":{"en":["Anas ibn Mālik narrated that the Prophet ﷺ said: “Hell will continue saying: ‘Is there any more?’ until the Lord of Might, Blessed and Exalted, places His Foot in it. Then it will say: ‘Enough! Enough! By Your Might!’ and its parts will contract together.”"]},"intro":{"ar":["قال الله تعالى:","﴿يَوْمَ نَقُولُ لِجَهَنَّمَ هَلِ امْتَلَأْتِ وَتَقُولُ هَلْ مِنْ مَزِيدٍ﴾ [سورة ق: ٣٠]."],"en":["Allah, the Exalted, says:","“On the Day We will say to Hell, ‘Are you filled?’ and it will say, ‘Is there any more?’”","[Qāf 50:30]"]}},"tuhfa":{},"full":1,"rep":[359,7048],"tks":"متفق عليه: رواه البخاري (6661)، ومسلم (2848: 37)."},{"num":16450,"demo":false,"sanad":"","matn":["عَنْ سَمُرَةَ، قَالَ: قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: رَأَيْتُ اللَّيْلَةَ رَجُلَيْنِ أَتَيَانِي قَالاَ: الَّذِي يُوقِدُ النَّارَ مَالِكٌ خَازِنُ النَّارِ، وَأَنَا جِبْرِيلُ، وَهَذَا مِيكَائِيلُ."],"takhrij":"متفق عليه: رواه البخاري في بدء الخلق (3236)، ومسلم في الرؤيا (2275) كلاهما من طريق جرير، حدثنا أبو رجاء، عن سمرة قال: فذكره.","grade":"متفق عليه","chapter_ar":"باب خازن النار يوقد النار","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (3236) and Muslim (2275).","chapter_en":"The Keeper of the Fire Tends the Fire","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة النار","group_en":"A Collection of What Has Been Narrated Concerning the Description of the Fire","part_no":67,"group_no":3,"chapter_no":4,"content":{"translation":{"en":["Samurah narrated that the Prophet ﷺ said: “Last night I saw two men who came to me. They said: ‘The one tending the Fire is Mālik, the keeper of the Fire. I am Jibrīl, and this is Mīkāʾīl.’”"]}},"tuhfa":{},"full":1,"rep":[649],"tks":"متفق عليه: رواه البخاري (3236)، ومسلم (2275)."},{"num":16451,"demo":false,"sanad":"","matn":["عن ابْنِ عَبَّاسٍ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:  مَرَرْتُ لَيْلَةَ أُسْرِيَ بِي عَلَى مُوسَى بْنِ عِمْرَانَ عَلَيْهِ السلام، رَجُلٌ آدَمُ طُوَالٌ جَعْدٌ، كَأَنَّهُ مِنْ رِجَالِ شَنُوءَةَ، وَرَأَيْتُ عِيسَى ابْنَ مَرْيَمَ مَرْبُوعَ الْخَلْقِ إِلَى الْحُمْرَةِ وَالْبَيَاضِ سَبِطَ الرَّأْسِ. وَأُرِيَ مَالِكًا خَازِنَ النَّارِ، وَالدَّجَّالَ."],"takhrij":"متفق عليه: رواه البخاري في بدء الخلق (3239)، ومسلم في الإيمان (165: 267) كلاهما عن طريق قتادة، عن أبي العالية، حدثنا ابن عم نبيكم يعني ابن عباس قال: فذكره. واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب خازن النار يوقد النار","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (3239) and Muslim (267 :165).","chapter_en":"The Keeper of the Fire Tends the Fire","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة النار","group_en":"A Collection of What Has Been Narrated Concerning the Description of the Fire","part_no":67,"group_no":3,"chapter_no":4,"content":{"translation":{"en":["Ibn ʿAbbās narrated that the Messenger of Allah ﷺ said: “On the night I was taken on the Night Journey, I passed by Mūsā ibn ʿImrān, peace be upon him, a tall, dark-complexioned man with curly hair, as though he were one of the men of Shanūʾah. I saw ʿĪsā ibn Maryam, of medium stature, with a complexion inclining toward red and white, and with straight hair. And Mālik, the keeper of the Fire, was shown to me…” The hadith continues."]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (3239)، ومسلم (165: 267)."},{"num":16452,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ:  كُنَّا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذْ سَمِعَ وَجْبَةً، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: تَدْرُونَ مَا هَذَا؟. قَالَ: قُلْنَا: اللَّهُ وَرَسُولُهُ أَعْلَمُ. قَالَ: هَذَا حَجَرٌ رُمِيَ بِهِ فِي النَّارِ مُنْذُ سَبْعِينَ خَرِيفًا، فَهُوَ يَهْوِي فِي النَّارِ الْآنَ، حَتَّى انْتَهَى إِلَى قَعْرِهَا."],"takhrij":"صحيح: رواه مسلم في الجنة (2844) عن يحيى بن أيوب، حدثنا خلف بن خليفة، حدثنا يزيد بن كيسان، عن أبي حازم، عن أبي هريرة قال: فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في بعد قعر جهنم","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2844).","chapter_en":"What Has Been Narrated Concerning the Great Depth of Hell","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة النار","group_en":"A Collection of What Has Been Narrated Concerning the Description of the Fire","part_no":67,"group_no":3,"chapter_no":5,"content":{"translation":{"en":["Abū Hurayrah narrated: We were with the Messenger of Allah ﷺ when he heard a loud crash. The Prophet ﷺ asked: “Do you know what that was?” We replied: “Allah and His Messenger know best.” He said: “That was a stone which was thrown into the Fire seventy years ago. It has been falling through the Fire until just now it reached its bottom.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (2844)."},{"num":16453,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِنَّ الْعَبْدَ لَيَتَكَلَّمُ بِالْكَلِمَةِ مَا يَتَبَيَّنُ فِيهَا، يهوي بِهَا فِي النَّارِ أَبْعَدَ مَا بَيْنَ الْمَشْرِقِ وَالْمَغْرِبِ."],"takhrij":"متفق عليه: رواه البخاري في الرقاق (647)، ومسلم في الزهد والرقائق (2988: 50) كلاهما من طريق يزيد بن الهاد، عن محمد بن إبراهيم، عن عيسى بن طلحة، عن أبي هريرة فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في بعد قعر جهنم","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6477) and Muslim (50 :2988).","chapter_en":"What Has Been Narrated Concerning the Great Depth of Hell","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة النار","group_en":"A Collection of What Has Been Narrated Concerning the Description of the Fire","part_no":67,"group_no":3,"chapter_no":5,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “A servant may utter a word without considering its consequences, and because of it he will fall into the Fire farther than the distance between the east and the west.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (647)، ومسلم (2988: 50)."},{"num":16454,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِنَّ الْعَبْدَ لَيَتَكَلَّمُ بِالْكَلِمَةِ مِنْ رِضْوَانِ اللَّهِ لاَ يُلْقِي لَهَا بَالاً، يَرْفَعُ اللَّهُ بِهَا دَرَجَاتٍ، وَإِنَّ الْعَبْدَ لَيَتَكَلَّمُ بِالْكَلِمَةِ مِنْ سَخَطِ اللَّهِ لاَ يُلْقِي لَهَا بَالاً يَهْوِي بِهَا فِي جَهَنَّمَ."],"takhrij":"صحيح: رواه البخاري في الرقاق (6478) عن عبد الله بن منير، سمع أبا النضر، حدثنا عبد الرحمن بن عبد الله يعني ابن دينار، عن أبيه، عن أبي صالح، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في بعد قعر جهنم","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (6478).","chapter_en":"What Has Been Narrated Concerning the Great Depth of Hell","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة النار","group_en":"A Collection of What Has Been Narrated Concerning the Description of the Fire","part_no":67,"group_no":3,"chapter_no":5,"content":{"translation":{"en":["Abū Hurayrah narrated that the Prophet ﷺ said: “A servant may utter a word pleasing to Allah without giving it much thought, and Allah will raise him by it many ranks. And a servant may utter a word displeasing to Allah without giving it much thought, and because of it he will fall into Hell.”"]}},"tuhfa":{},"full":1,"rep":[13380,14550],"tks":"صحيح: رواه البخاري (6478)."},{"num":16455,"demo":false,"sanad":"","matn":["عَنْ خَالِدِ بْنِ عُمَيْرٍ الْعَدَوِيِّ قَالَ:  خَطَبَنَا عُتْبَةُ بْنُ غَزْوَانَ، فَحَمِدَ اللَّهَ وَأَثْنَى عَلَيْهِ، ثُمَّ قَالَ: أَمَّا بَعْدُ، فَإِنَّ الدُّنْيَا قَدْ آذَنَتْ بِصُرْمٍ، وَوَلَّتْ حَذَّاءَ، وَلَمْ يَبْقَ مِنْهَا إِلَّا صُبَابَةٌ كَصُبَابَةِ الْإِنَاءِ، يَتَصَابُّهَا صَاحِبُهَا، وَإِنَّكُمْ مُنْتَقِلُونَ مِنْهَا إِلَى دَارٍ لَا زَوَالَ لَهَا، فَانْتَقِلُوا بِخَيْرِ مَا بِحَضْرَتِكُمْ، فَإِنَّهُ قَدْ ذُكِرَ لَنَا: أَنَّ الْحَجَرَ يُلْقَى مِنْ شَفَةِ جَهَنَّمَ فَيَهْوِي فِيهَا سَبْعِينَ عَامًا لَا يُدْرِكُ لَهَا قَعْرًا، وَوَاللهِ لَتُمْلَأَنَّ، أَفَعَجِبْتُمْ؟ وَلَقَدْ ذُكِرَ."],"takhrij":"صحيح: رواه مسلم في الزهد (2967) عن شيبان بن فروخ، حدثنا سليمان بن المغيرة، حدثنا حميد بن هلال، عن خالد بن عمير العدوي قال: فذكره بطوله.","grade":"صحيح","chapter_ar":"باب ما جاء في بعد قعر جهنم","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2967).","chapter_en":"What Has Been Narrated Concerning the Great Depth of Hell","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة النار","group_en":"A Collection of What Has Been Narrated Concerning the Description of the Fire","part_no":67,"group_no":3,"chapter_no":5,"content":{"translation":{"en":["Khālid ibn ʿUmayr al-ʿAdawī narrated: ʿUtbah ibn Ghazwān delivered a sermon to us. He praised Allah and extolled Him, then said: “To proceed: This world has announced that it is coming to an end and has turned away swiftly. Nothing remains of it except a small amount like the dregs remaining in a vessel, which its owner tries to drink. You are moving from it to an abode that will never pass away, so move there with the best deeds you are able to take with you. We have been told that a stone will be thrown from the edge of Hell and will fall through it for seventy years without reaching its bottom. By Allah, it will certainly be filled. Are you surprised?…” The hadith continues at length."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (2967)."},{"num":16456,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيَّ يَقُولُ: إِنَّا يَوْمًا عِنْدَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَرَأَيْنَاهُ كَئِيبًا، فَقَالَ بَعْضُهُمْ: يَا رَسُولَ اللَّهِ! بِأَبِي وَأُمِّي ومالي أَرَاكَ هَكَذَا؟ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : سَمِعْتُ هَدَّةً لَمْ أَسْمَعْ مِثْلَهَا، فَأَتَانِي جِبْرِيلُ، فَسَأَلْتُهُ عَنْهَا، فَقَالَ: هَذَا صَخْرٌ قُذِفَ بِهِ فِي النَّارِ مُنْذُ سَبْعِينَ خَرِيفًا فَالْيَوْمُ اسْتَقَرَّ قَرَارُهُ. فَقَالَ أَبُو سَعِيدٍ: وَالَّذِي ذَهَبَ بِنَفْسِ نَبِيِّنَا صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ! ! مَا رَأَيْتُهُ ضَاحِكًا بَعْدَ ذَلِكَ الْيَوْمِ حَتَّى وَارَاهُ التُّرَابُ."],"takhrij":"صحيح: رواه ابن أبي شيبة (35286) عن محمد بن بشر، عن هارون بن أبي إبراهيم، عن أبي نضرة قال: سمعت أبا سعيد الخدري يقول: فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في بعد قعر جهنم","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by Ibn Abī Shaybah (35286).","chapter_en":"What Has Been Narrated Concerning the Great Depth of Hell","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة النار","group_en":"A Collection of What Has Been Narrated Concerning the Description of the Fire","part_no":67,"group_no":3,"chapter_no":5,"content":{"translation":{"en":["Abū Saʿīd al-Khudrī narrated: One day we were with the Messenger of Allah ﷺ and noticed that he appeared deeply distressed. Someone said: “O Messenger of Allah, may my father, mother, and wealth be sacrificed for you; why do I see you in this state?” The Messenger of Allah ﷺ replied: “I heard a tremendous crash unlike anything I had ever heard. Then Jibrīl came to me, so I asked him about it. He said: ‘This is a rock that was thrown into the Fire seventy years ago, and today it finally reached its resting place.’” Abū Saʿīd said: “By the One who took the soul of our Prophet ﷺ, I never saw him laugh after that day until the earth covered him.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه ابن أبي شيبة (35286)."},{"num":16457,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ الْعَاصِي، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَوْ أَنَّ رُصَاصَةً مِثْلَ هَذِهِ وَأَشَارَ إِلَى مِثْلِ الْجُمْجُمَةِ أُرْسِلَتْ مِنَ السَّمَاءِ إِلَى الأَرْضِ وَهِيَ مَسِيرَةُ خَمْسِمِائَةِ سَنَةٍ لَبَلَغَتِ الأَرْضَ قَبْلَ اللَّيْلِ، وَلَوْ أَنَّهَا أُرْسِلَتْ مِنْ رَأْسِ السِّلْسِلَةِ لَصَارَتْ أَرْبَعِينَ خَرِيفًا اللَّيْلَ وَالنَّهَارَ قَبْلَ أَنْ تَبْلُغَ أَصْلَهَا أَوْ قَعْرَهَا."],"takhrij":"حسن: رواه الترمذي (2588)، وأحمد (6856)، والحاكم (3640) مختصرا كلهم من طرق عن عبد الله بن يزيد المقرئ قال: أخبرنا سعيد بن يزيد، عن أبي السمح، عن عيسى بن هلال الصدفي، عن عبد الله بن عمرو قال: فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في بعد قعر جهنم","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhī (2588), Aḥmad (6856), and al-Ḥākim (2/438-439).","chapter_en":"What Has Been Narrated Concerning the Great Depth of Hell","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة النار","group_en":"A Collection of What Has Been Narrated Concerning the Description of the Fire","part_no":67,"group_no":3,"chapter_no":5,"content":{"translation":{"en":["ʿAbdullāh ibn ʿAmr narrated that the Messenger of Allah ﷺ said: “If a lead ball like this”—and he gestured to something the size of a skull—“were released from the sky toward the earth, though the distance is a journey of five hundred years, it would reach the earth before nightfall. But if it were released from the top of the chain in Hell, it would travel for forty years, by night and day, before reaching its end or its bottom.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الترمذي (2588)، وأحمد (6856)، والحاكم (3640)."},{"num":16458,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: يَخْرُجُ عُنُقٌ مِنَ النَّارِ يَوْمَ الْقِيَامَةِ، لَهُ عَيْنَانِ تُبْصِرَانِ، وَأُذُنَانِ تَسْمَعَانِ، وَلِسَانٌ يَنْطِقُ يَقُولُ: إِنِّي وُكِّلْتُ بِثَلاَثَةٍ: بِكُلِّ جَبَّارٍ عَنِيدٍ، وَبِكُلِّ مَنْ دَعَا مَعَ اللَّهِ إِلَهًا آخَرَ، وَبِالْمُصَوِّرِينَ."],"takhrij":"صحيح: رواه الترمذي (2574)، وأحمد (8430)، والبيهقي في \"الشعب\" (5904) كلهم من طريق عبد العزيز بن مسلم، عن الأعمش، عن أبي صالح، عن أبي هريرة قال: فذكره. وإسناده صحيح. وأبو صالح هو ذكوان السمان.","grade":"صحيح","chapter_ar":"باب تخرج عنق من النار يوم القيامة تتكلم","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by al-Tirmidhī (2574), Aḥmad (8430), and al-Bayhaqī in al-Shuʿab (5904).","chapter_en":"A Neck Will Emerge from the Fire on the Day of Resurrection and Speak","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة النار","group_en":"A Collection of What Has Been Narrated Concerning the Description of the Fire","part_no":67,"group_no":3,"chapter_no":6,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “A neck will emerge from the Fire on the Day of Resurrection. It will have two eyes with which it sees, two ears with which it hears, and a tongue with which it speaks. It will say: ‘I have been entrusted with three: every obstinate tyrant, everyone who called upon another deity alongside Allah, and the image-makers.’”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الترمذي (2574)، وأحمد (8430)، والبيهقي في “الشعب” (5904)."},{"num":16459,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ، عَنْ نَبِيِّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ قَالَ: يَخْرُجُ عُنُقٌ مِنَ النَّارِ يَتَكَلَّمُ يَقُولُ: وُكِّلْتُ الْيَوْمَ بِثَلَاثَةٍ: بِكُلِّ جَبَّارٍ، وَبِمَنْ جَعَلَ مَعَ اللَّهِ إِلَهًا آخَرَ، وَبِمَنْ قَتَلَ نَفْسًا بِغَيْرِ نَفْسٍ، فَيَنْطَوِي عَلَيْهِمْ، فَيَقْذِفُهُمْ فِي غَمَرَاتِ جَهَنَّمَ."],"takhrij":"حسن: رواه أحمد (11354)، وابن أبي شيبة (35278)، وأبو يعلى (1146)، والبزار –كشف الأستار (3500) كلهم من طرق عن عطية، عن أبي سعيد فذكره.","grade":"حسن","chapter_ar":"باب تخرج عنق من النار يوم القيامة تتكلم","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (11354), Ibn Abī Shaybah (35278), Abū Yaʿlā (1146), and al-Bazzār in Kashf al-Astār (3500).","chapter_en":"A Neck Will Emerge from the Fire on the Day of Resurrection and Speak","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة النار","group_en":"A Collection of What Has Been Narrated Concerning the Description of the Fire","part_no":67,"group_no":3,"chapter_no":6,"content":{"translation":{"en":["Abū Saʿīd narrated that the Prophet of Allah ﷺ said: “A neck will emerge from the Fire and speak, saying: ‘Today I have been entrusted with three: every tyrant, whoever set up another deity alongside Allah, and whoever killed a soul without just cause.’ It will wrap itself around them and cast them into the depths of Hell.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[13386],"tks":"حسن: رواه أحمد (11354)، وابن أبي شيبة (35278)، وأبو يعلى (1146)، والبزار في كشف الأستار (3500)."},{"num":16460,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: نَارُ بَنِي آدَمَ الَّتِي يُوقِدُونَ جُزْءٌ مِنْ سَبْعِينَ جُزْءًا مِنْ نَارِ جَهَنَّمَ. فَقَالُوا: يَا رَسُولَ اللَّهِ إِنْ كَانَتْ لَكَافِيَةً. قَالَ: إِنَّهَا فُضِّلَتْ عَلَيْهَا بِتِسْعَةٍ وَسِتِّينَ جُزْءًا."],"takhrij":"متفق عليه: رواه مالك في كتاب جهنم (1) عن أبي الزناد، عن الأعرج، عن أبي هريرة فذكره. ورواه البخاري في بدء الخلق (3265) من طريق مالك به.","grade":"متفق عليه","chapter_ar":"باب ما جاء في شدة نار جهنم","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Agreed upon: Narrated by Mālik in Kitāb Jahannam (1), Muslim (2843), and al-Bukhārī (3265).","chapter_en":"What Has Been Narrated Concerning the Intensity of the Fire of Hell","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة النار","group_en":"A Collection of What Has Been Narrated Concerning the Description of the Fire","part_no":67,"group_no":3,"chapter_no":7,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “The fire which the children of Ādam kindle is one part out of seventy parts of the Fire of Hell.” They said: “O Messenger of Allah, this fire would have been sufficient!” He replied: “The Fire of Hell has been made sixty-nine parts more intense than it.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[12504,13491],"tks":"متفق عليه: رواه مالك (1) ومسلم (2843) والبخاري (3265)."},{"num":16461,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: هَذِهِ النَّارُ جُزْءٌ مِنْ مِائَةِ جُزْءٍ مِنْ جَهَنَّمَ."],"takhrij":"حسن: رواه أحمد (8921) عن قتيبة، حدثنا عبد العزيز، عن سهيل، عن أبيه، عن أبي هريرة فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في شدة نار جهنم","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (8921).","chapter_en":"What Has Been Narrated Concerning the Intensity of the Fire of Hell","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة النار","group_en":"A Collection of What Has Been Narrated Concerning the Description of the Fire","part_no":67,"group_no":3,"chapter_no":7,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “This fire is one part out of one hundred parts of Hell.”"]},"buhuth":{"en":["The author says that the wording “seventy parts” and the wording “one hundred parts” may be understood as referring to different times of greater or lesser intensity, and may also vary according to those who enter it."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (8921)."},{"num":16462,"demo":false,"sanad":"","matn":["عَنْ سَمُرَةَ بْنِ جُنْدَبٍ أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:  مِنْهُمْ مَنْ تَأْخُذُهُ النَّارُ إِلَى كَعْبَيْهِ، وَمِنْهُمْ مَنْ تَأْخُذُهُ النَّارُ إِلَى رُكْبَتَيْهِ، وَمِنْهُمْ مَنْ تَأْخُذُهُ النَّارُ إِلَى حُجْزَتِهِ، وَمِنْهُمْ مَنْ تَأْخُذُهُ النَّارُ إِلَى تَرْقُوَتِهِ."],"takhrij":"صحيح: رواه مسلم في الجنة (2845: 33) عن عمرو بن زرارة، أخبرنا عبدالوهاب –يعني ابن عطاء-، عن سعيد، عن قتادة قال: سمعت أبا نضرة يحدث عن سمرة بن جندب فذكره.","grade":"صحيح","chapter_ar":"باب أن الداخلين في جهنم تصيبهم النار حسب ذنوبهم","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (33 :2845).","chapter_en":"Those Who Enter Hell Will Be Reached by the Fire According to Their Sins","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة النار","group_en":"A Collection of What Has Been Narrated Concerning the Description of the Fire","part_no":67,"group_no":3,"chapter_no":8,"content":{"translation":{"en":["Samurah ibn Jundub narrated that the Prophet ﷺ said: “Among them are those whom the Fire will reach up to their ankles; among them are those whom it will reach up to their knees; among them are those whom it will reach up to their waist; and among them are those whom it will reach up to their collarbones.”"]},"buhuth":{"en":["The word “ḥujzatihi” refers to the place where the waist-wrapper or trousers are tied.","The word “tarquwatihi” refers to the collarbone between the hollow at the base of the throat and the neck."]}},"tuhfa":{},"full":1,"dr":1,"rep":[12606],"tks":"صحيح: رواه مسلم (2845: 33)."},{"num":16463,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : اشْتَكَتِ النَّارُ إِلَى رَبِّهَا، فَقَالَتْ: رَبِّ أَكَلَ بَعْضِي بَعْضًا، فَأَذِنَ لَهَا بِنَفَسَيْنِ: نَفَسٍ فِي الشِّتَاءِ، وَنَفَسٍ فِي الصَّيْفِ، فَأَشَدُّ مَا تَجِدُونَ مِنَ الْحَرِّ وَأَشَدُّ مَا تَجِدُونَ مِنَ الزَّمْهَرِيرِ."],"takhrij":"متفق عليه: رواه البخاري في بدء الخلق (3260)، ومسلم في المساجد (617) كلاهما من طريق ابن شهاب الزهري، قال: حدثني أبو سلمة بن عبد الرحمن، أنه سمع أبا هريرة يقول: فذكره. واللفظ للبخاري ولفظ مسلم نحوه.","grade":"متفق عليه","chapter_ar":"باب ما جاء في شكوى النار إلى ربها من شدة حرها وبردها","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (3260) and Muslim (617).","chapter_en":"What Has Been Narrated Concerning the Fire Complaining to Its Lord About the Severity of Its Heat and Cold","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة النار","group_en":"A Collection of What Has Been Narrated Concerning the Description of the Fire","part_no":67,"group_no":3,"chapter_no":9,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “The Fire complained to its Lord, saying: ‘My Lord, one part of me is consuming another.’ So He permitted it two breaths: one in winter and one in summer. Thus the most severe heat you experience and the most severe bitter cold you experience are from it.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (3260)، ومسلم (617)."},{"num":16464,"demo":false,"sanad":"","matn":["عن مجاهد أن الناس كانوا يطوفون بالبيت وابنُ عباسٍ جالسٌ معه محْجَنٌ، فقال: قال رسول الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ﴿يَا أَيُّهَا الَّذِينَ آمَنُوا اتَّقُوا اللَّهَ حَقَّ تُقَاتِهِ وَلَا تَمُوتُنَّ إِلَّا وَأَنْتُمْ مُسْلِمُونَ﴾ [سورة آل عمران: 102] ولو أن قطرة من الزقوم قطرت لأمّرتْ على أهل الأرض عيشهم، فكيف من ليس لهم طعام إلا الزقوم."],"takhrij":"صحيح: رواه الترمذي (2585)، وابن ماجه (4325)، وأحمد (2735)، وابن أبي حاتم (3/723)، وصحّحه ابن حبان (7470)، والحاكم (3158) كلهم من طرق عن شعبة قال: سمعت سليمان الأعمش، عن مجاهد قال: فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في طعام أهل النار وشرابهم","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by al-Tirmidhī (2585), Ibn Mājah (4325), Aḥmad (2735), Ibn Abī Ḥātim (3/723), and authenticated by Ibn Ḥibbān (7470) and al-Ḥākim (2/294).","chapter_en":"What Has Been Narrated Concerning the Food and Drink of the People of the Fire","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة النار","group_en":"A Collection of What Has Been Narrated Concerning the Description of the Fire","part_no":67,"group_no":3,"chapter_no":10,"content":{"translation":{"en":["Mujāhid narrated: The people were circumambulating the House while Ibn ʿAbbās was sitting with a hooked staff. He said: The Messenger of Allah ﷺ said: “‘O you who believe, fear Allah as He should be feared and do not die except in a state of submission.’ If a single drop of Zaqqūm were to fall upon the earth, it would ruin the livelihood of the people of the earth. So what of those whose only food will be Zaqqūm?”"]},"intro":{"ar":["قال اللّٰه تعالى:","﴿إِنَّ شَجَرَتَ الزَّقُّومِ ۝ طَعَامُ الْأَثِيمِ ۝ كَالْمُهْلِ يَغْلِي فِي الْبُطُونِ ۝ كَغَلْيِ الْحَمِيمِ ۝ خُذُوهُ فَاعْتِلُوهُ إِلَىٰ سَوَاءِ الْجَحِيمِ ۝ ثُمَّ صُبُّوا فَوْقَ رَأْسِهِ مِنْ عَذَابِ الْحَمِيمِ﴾ [الدخان: ٤٣-٤٨].","وقال تعالى:","﴿فَلَيْسَ لَهُ الْيَوْمَ هَاهُنَا حَمِيمٌ ۝ وَلَا طَعَامٌ إِلَّا مِنْ غِسْلِينٍ ۝ لَا يَأْكُلُهُ إِلَّا الْخَاطِئُونَ﴾ [الحاقة: ٣٥-٣٧].","وقال تعالى:","﴿تَصْلَىٰ نَارًا حَامِيَةً ۝ تُسْقَىٰ مِنْ عَيْنٍ آنِيَةٍ ۝ لَيْسَ لَهُمْ طَعَامٌ إِلَّا مِنْ ضَرِيعٍ ۝ لَا يُسْمِنُ وَلَا يُغْنِي مِنْ جُوعٍ﴾ [الغاشية: ٤-٧]."],"en":["Allah, the Exalted, says:","“Indeed, the tree of Zaqqūm is the food of the sinful. Like molten metal, it will boil in the bellies like the boiling of scalding water. ‘Seize him and drag him into the midst of the blazing Fire. Then pour over his head the torment of scalding water.’”","[al-Dukhān 44:43-48]","And He, the Exalted, says:","“So today he has no devoted friend here, nor any food except foul discharge, which none will eat except the sinners.”","[al-Ḥāqqah 69:35-37]","And He, the Exalted, says:","“They will enter a blazing Fire, given drink from a boiling spring. They will have no food except from a bitter thorny plant, which neither nourishes nor satisfies hunger.”","[al-Ghāshiyah 88:4-7]"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الترمذي (2585)، وابن ماجه (4325)، وأحمد (2735)، وابن أبي حاتم (3/723)، وصححه ابن حبان (7470)، والحاكم (3158)."},{"num":16465,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِنَّ الْحَمِيمَ لَيُصَبُّ عَلَى رُءُوسِهِمْ فَيَنْفُذُ الْحَمِيمُ حَتَّى يَخْلُصَ إِلَى جَوْفِهِ، فَيَسْلِتَ مَا فِي جَوْفِهِ حَتَّى يَمْرُقَ مِنْ قَدَمَيْهِ وَهُوَ الصَّهْرُ ثُمَّ يُعَادُ كَمَا كَانَ."],"takhrij":"حسن: رواه الترمذي (2582)، وأحمد (8864)، والحاكم (3458) كلهم من طريق عبد الله بن المبارك، أخبرنا سعيد بن يزيد، عن أبي السمح، عن ابن حجيرة، عن أبي هريرة فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في طعام أهل النار وشرابهم","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhī (2582), Aḥmad (8864), and al-Ḥākim (2/387).","chapter_en":"What Has Been Narrated Concerning the Food and Drink of the People of the Fire","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة النار","group_en":"A Collection of What Has Been Narrated Concerning the Description of the Fire","part_no":67,"group_no":3,"chapter_no":10,"content":{"translation":{"en":["Abū Hurayrah narrated that the Prophet ﷺ said: “Scalding water will be poured over their heads. It will penetrate until it reaches their insides, dissolving whatever is within them, until it exits through their feet. This is the melting. Then they will be restored as they were.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[12780],"tks":"حسن: رواه الترمذي (2582)، وأحمد (8864)، والحاكم (3458)."},{"num":16466,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ:  أَنَّ رَجُلًا قَدِمَ مِنْ جَيْشَانَ، وَجَيْشَانُ مِنَ الْيَمَنِ، فَسَأَلَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ شَرَابٍ يَشْرَبُونَهُ بِأَرْضِهِمْ مِنَ الذُّرَةِ يُقَالُ لَهُ: الْمِزْرُ. فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَوَمُسْكِرٌ هُوَ؟. قَالَ: نَعَمْ، قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: كُلُّ مُسْكِرٍ حَرَامٌ، إِنَّ عَلَى اللَّهِ عَزَّ وَجَلَّ عَهْدًا لِمَنْ يَشْرَبُ الْمُسْكِرَ أَنْ يَسْقِيَهُ مِنْ طِينَةِ الْخَبَالِ. قَالُوا: يَا رَسُولَ اللَّهِ، وَمَا طِينَةُ الْخَبَالِ؟ قَالَ: عَرَقُ أَهْلِ النَّارِ، أَوْ عُصَارَةُ أَهْلِ النَّارِ."],"takhrij":"صحيح: رواه مسلم في الأشربة (2002) عن قتيبة بن سعيد، حدثنا عبد العزيز الدراوردي، عن عُمارة بن غزية، عن أبي الزبير، عن جابر فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في طعام أهل النار وشرابهم","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2002).","chapter_en":"What Has Been Narrated Concerning the Food and Drink of the People of the Fire","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة النار","group_en":"A Collection of What Has Been Narrated Concerning the Description of the Fire","part_no":67,"group_no":3,"chapter_no":10,"content":{"translation":{"en":["Jābir narrated: A man came from Jayshān—and Jayshān is in Yemen—and asked the Prophet ﷺ about a drink they made in their land from millet called al-mizr. The Prophet ﷺ asked: “Is it intoxicating?” He replied: “Yes.” The Messenger of Allah ﷺ said: “Every intoxicant is forbidden. Allah, Mighty and Majestic, has made a covenant that whoever drinks intoxicants will be given to drink from Ṭīnat al-Khabāl.” They asked: “O Messenger of Allah, what is Ṭīnat al-Khabāl?” He replied: “The sweat of the people of the Fire, or the discharge of the people of the Fire.”"]}},"tuhfa":{},"full":1,"rep":[7005,7455],"tks":"صحيح: رواه مسلم (2002)."},{"num":16467,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو، عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ قَالَ: مَنْ تَرَكَ الصَّلَاةَ سُكْرًا مَرَّةً وَاحِدَةً، فَكَأَنَّمَا كَانَتْ لَهُ الدُّنْيَا وَمَا عَلَيْهَا فَسُلِبَهَا، وَمَنْ تَرَكَ الصَّلَاةَ سُكْرًا أَرْبَعَ مَرَّاتٍ، كَانَ حَقًّا عَلَى اللَّهِ عَزَّ وَجَلَّ أَنْ يَسْقِيَهُ مِنْ طِينَةِ الْخَبَالِ، قِيلَ: وَمَا طِينَةُ الْخَبَالِ يَا رَسُولَ اللَّهِ؟ قَالَ: عُصَارَةُ أَهْلِ جَهَنَّمَ."],"takhrij":"حسن: رواه أحمد (6659) عن هارون بن معروف، ثنا ابن وهب، حدثني عمرو بن الحارث، عن عمرو بن شعيب، عن أبيه، عن عبد الله بن عمرو فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في طعام أهل النار وشرابهم","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (6659).","chapter_en":"What Has Been Narrated Concerning the Food and Drink of the People of the Fire","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة النار","group_en":"A Collection of What Has Been Narrated Concerning the Description of the Fire","part_no":67,"group_no":3,"chapter_no":10,"content":{"translation":{"en":["ʿAbdullāh ibn ʿAmr ibn al-ʿĀṣ narrated that the Messenger of Allah ﷺ said: “Whoever abandons the prayer because of intoxication one time, it is as though he possessed the whole world and everything upon it and then had it taken away from him. And whoever abandons the prayer because of intoxication four times, it becomes a right upon Allah, Mighty and Majestic, to give him drink from Ṭīnat al-Khabāl.” It was asked: “What is Ṭīnat al-Khabāl, O Messenger of Allah?” He replied: “The discharge of the people of Hell.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[7458],"tks":"حسن: رواه أحمد (6659)."},{"num":16468,"demo":false,"sanad":"","matn":["عن عَبْدِ اللَّهِ بن الْحَارِثِ بْنِ جَزْءٍ الزبيدي قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّ فِي النَّارِ حَيَّاتٍ كَأَمْثَالِ أَعْنَاقِ الْبُخْتِ، تَلْسَعُ إِحْدَاهُنَّ اللَّسْعَةَ، فَيَجِدُ حَمْوَتَهَا أَرْبَعِينَ خَرِيفًا، وَإِنَّ فِي النَّارِ عَقَارِبَ كَأَمْثَالِ الْبِغَالِ الْمُوكَفَةِ، تَلْسَعُ إِحْدَاهُنَّ اللَّسْعَةَ، فَيَجِدُ حَمْوَتَهَا أَرْبَعِينَ سَنَةً."],"takhrij":"حسن: رواه الإمام أحمد (17712) عن موسى بن داود وحسن بن موسى قالا:حدثنا ابن لهيعة ، عن دراج قال: سمعت عبد الله بن الحارث بن جزء الزبيدي قال: فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في حيات النار وعقاربها","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Hasan: Narrated by Imām Aḥmad (17712).","chapter_en":"What Has Been Narrated Concerning the Snakes and Scorpions of the Fire","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة النار","group_en":"A Collection of What Has Been Narrated Concerning the Description of the Fire","part_no":67,"group_no":3,"chapter_no":11,"content":{"translation":{"en":["ʿAbdullāh ibn al-Ḥārith ibn Jazʾ al-Zubaydī narrated that the Messenger of Allah ﷺ said: “Indeed, in the Fire are snakes like the necks of Bactrian camels. One of them will bite a person, and he will feel the burning pain of its venom for forty years. And in the Fire are scorpions like saddled mules. One of them will sting a person, and he will feel the burning pain of its venom for forty years.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الإمام أحمد (17712)."},{"num":16469,"demo":false,"sanad":"","matn":["عَنْ عِتْبَانَ بن مَالِكٍ الأنصاري قَالَ: غَدَا عليّ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: لَنْ يُوَافِيَ عَبْدٌ يَوْمَ الْقِيَامَةِ يَقُولُ: لاَ إِلَهَ إِلاَّ اللَّهُ يَبْتَغِي بِهِ وَجْهَ اللَّهِ إِلاَّ حرّم اللَّهُ عَلَيْهِ النَّارَ."],"takhrij":"متفق عليه: رواه البخاري في الرقاق (6422-6423)، ومسلم في المساجد (33: 264) كلاهما من طريق معمر، عن الزهري قال: حدثني محمود بن الربيع قال: سمعت عتبان بن مالك الأنصاري قال: فذكره. واللفظ للبخاري.","grade":"متفق عليه","chapter_ar":"باب تحريم الله النار على من قال: لا إله إلا الله يبتغي به وجه الله","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6422-6423) and Muslim (264 :33). The wording is al-Bukhārī’s.","chapter_en":"Allah Has Forbidden the Fire to Whoever Says “Lā Ilāha Illā Allah,” Seeking Thereby the Face of Allah","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل النار","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of the Fire","part_no":67,"group_no":4,"chapter_no":1,"content":{"translation":{"en":["ʿItbān ibn Mālik al-Anṣārī narrated: The Messenger of Allah ﷺ came to me one morning and said: “No servant will come on the Day of Resurrection saying, ‘There is no deity except Allah,’ seeking thereby the Face of Allah, except that Allah will forbid the Fire to him.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (6423-6422)، ومسلم (33: 264). واللفظ للبخاري."},{"num":16470,"demo":false,"sanad":"","matn":["عَنْ أَبِي بَكْرَةَ، عَنِ النّبيّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ فِي حَدِيثِ طَوِيلٍ: ثُمَّ يُؤْذَنُ لِلْمَلَائِكَةِ وَالنَّبِيِّينَ وَالشُّهَدَاءِ أَنْ يَشْفَعُوا، فَيَشْفَعُونَ وَيُخْرِجُونَ، وَيَشْفَعُونَ وَيُخْرِجُونَ، وَيَشْفَعُونَ وَيُخْرِجُونَ، وَزَادَ عَفَّانُ مَرَّةً فَقَالَ أَيْضًا: وَيَشْفَعُونَ وَيُخْرِجُونَ مَنْ كَانَ فِي قَلْبِهِ مَا يَزِنُ ذرّة مِنْ إِيمَانٍ."],"takhrij":"حسن: رواه أحمد (20440)، والبزّار (3671)، والطبرانيّ في الصغير (929)، وابن أبي عاصم في السنة (838) كلّهم من حديث عفّان بن مسلم، حدّثنا سعيد بن زيد، قال: سمعت أبا سليمان العصريّ، حدّثنا عقبة بن صُهبان، عن أبي بكرة، عن النبيّ صلى الله عليه وسلم، فذكره.","grade":"حسن","chapter_ar":"باب يخرج من النار من كان في قلبه ما يزن ذرة من إيمان","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (20440), al-Bazzār (3671), al-Ṭabarānī in al-Muʿjam al-Ṣaghīr (929), and Ibn Abī ʿĀṣim in al-Sunnah (838).","chapter_en":"Whoever Has in His Heart Faith Weighing as Much as an Atom Will Be Brought Out of the Fire","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل النار","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of the Fire","part_no":67,"group_no":4,"chapter_no":2,"content":{"translation":{"en":["Abū Bakrah narrated from the Prophet ﷺ in a lengthy hadith: “Then permission will be given to the angels, the Prophets, and the martyrs to intercede. So they will intercede and bring people out; they will intercede and bring people out; they will intercede and bring people out.” On one occasion, ʿAffān added: “They will intercede and bring out whoever has in his heart faith weighing as much as an atom.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (20440)، والبزار (3671)، والطبراني في الصغير (929)، وابن أبي عاصم في السنة (838)."},{"num":16471,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: يُوضَعُ الصِّرَاطُ بَيْنَ ظَهْرَي جَهَنَّمَ، عَلَيْهِ حَسَكٌ كحَسَكِ السَّعْدان، ثُمَّ يَسْتجيزُ النّاسُ، فَنَاجٍ مُسَلَّمٌ، ومجروحٌ بِهِ، ثُمَّ ناجِ ومُحْتَبس بِهِ منكوس فِيهَا، فَإِذَا فَرَغَ اللَّهُ عَزَّ وَجَلَّ مِنَ الْقَضَاءِ بَيْنَ الْعِبَادِ يَفْقِدُ الْمُؤْمِنُونَ رِجَالًا كَانُوا مَعَهُمْ فِي الدُّنْيَا يُصَلُّون بِصَلَاتِهِمْ، ويُزَكُّون بِزَكَاتِهِمْ، ويَصُومُون صِيَامَهُمْ، ويَحُجُّون حَجَّهم، ويَغْزُون غَزْوَهم، فَيَقُولُونَ: أيْ ربَّنا عِبَادٌ مِنْ عِبَادِكَ كَانُوا مَعَنَا فِي الدُّنْيَا يُصَلُّونَ صَلَاتَنَا، وَيُزَكُّونَ زَكَاتَنَا، وَيَصُومُونَ صِيَامَنَا، وَيَحُجُّونَ حَجَّنَا، وَيَغْزُونَ غَزْوَنَا، لَا نَرَاهُمْ؟! فَيَقُولُ: اذْهَبُوا إِلَى النَّارِ فَمَنْ وَجَدْتُمْ فِيهَا مِنْهُمْ فَأَخْرِجُوهُ. قَالَ: فَيَجِدُونَهُمْ قَدْ أَخَذَتْهُمُ النَّارُ عَلَى قَدْرِ أَعْمَالِهِمْ، فَمِنْهُمْ مَنْ أَخَذَتْهُ إِلَى قَدَمَيْهِ، وَمِنْهُمْ مَنْ أخذَتْه إِلَى نِصْفِ سَاقَيْهِ، وَمِنْهُمْ مَنْ أَخَذَتْهُ إِلَى رُكْبَتَيْهِ، وَمِنْهُمْ مَنْ أَزَّرَتْه، وَمِنْهُمْ مَنْ أَخَذَتْهُ إِلَى ثَدْيَيْهِ، وَمِنْهُمْ مَنْ أَخَذَتْهُ إِلَى عُنُقِهِ، وَلَمْ تغشَ الْوُجُوهَ، فَيَسْتَخْرِجُونَهُمْ مِنْهَا، فَيُطْرَحُونَ فِي مَاءِ الْحَيَاةِ. قِيلَ: يَا رَسُولَ اللَّهِ، وَمَا الْحَيَاةُ؟ قَالَ: غُسْلُ أَهْلِ الْجَنَّةِ، فَيَنْبُتُونَ نَبَاتَ الزَّرْعَةِ. وَقَالَ مَرَّةً فِيهِ: كَمَا تَنْبُتُ الزَّرْعَةُ فِي غُثَاءِ السَّيْلِ. ثُمَّ يَشْفَعُ الْأَنْبِيَاءُ فِي كلِّ مَنْ كَانَ يَشْهَدُ أَنْ لَا إِلَهَ إلاّ اللَّهُ مُخْلِصًا فَيُخْرِجُونَهُمْ مِنْهَا، قَالَ: ثُمَّ يَتَحَنَّنُ اللهُ بِرَحْمَتِهِ عَلَى مَنْ فِيهَا، فَمَا يَتْرُكُ فِيهَا عَبْدًا فِي قَلْبِهِ مِثْقَالُ حَبَّةٍ مِنْ إِيمَانٍ إِلَّا أَخْرَجَهُ مِنْهَا."],"takhrij":"حسن: رواه أحمد (11081) واللّفظ له، وابن خزيمة في التوحيد (648)، وابن ماجه (4280) مختصراً، والحاكم (8738) كلّهم من طريق محمد بن إسحاق، قال: حدّثني عبيد الله بن المغيرة بن مُعيقيب، عن سليمان بن عمرو بن عبد العُتْواريّ -أحد بني ليث- وكان يتيماً في حجر أبي سعيد، قال: سمعت أبا سعيد يقول فذكره.","grade":"حسن","chapter_ar":"باب يخرج من النار من كان في قلبه ما يزن ذرة من إيمان","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (11081), whose wording this is, Ibn Khuzaymah in al-Tawḥīd (648), Ibn Mājah (4280) in abbreviated form, and al-Ḥākim (4/585-586), who authenticated it.","chapter_en":"Whoever Has in His Heart Faith Weighing as Much as an Atom Will Be Brought Out of the Fire","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل النار","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of the Fire","part_no":67,"group_no":4,"chapter_no":2,"content":{"translation":{"en":["Abū Saʿīd al-Khudrī narrated: I heard the Messenger of Allah ﷺ say: “The Ṣirāṭ will be placed across Hell. Upon it will be hooks like the thorns of al-Saʿdān. Then the people will attempt to cross. Some will be saved unharmed, some will be wounded by it yet escape, while others will be held back and thrown headfirst into it. When Allah, Mighty and Majestic, has finished judging between the servants, the believers will notice that certain men who had been with them in the worldly life are missing—men who used to pray as they prayed, pay zakāh as they paid zakāh, fast as they fasted, perform Ḥajj as they performed Ḥajj, and fight as they fought. They will say: ‘Our Lord, there were servants among Your servants who were with us in the world. They prayed as we prayed, paid zakāh as we did, fasted as we fasted, performed Ḥajj as we did, and fought as we fought, yet we do not see them.’ He will say: ‘Go to the Fire, and whoever among them you find there, bring him out.’ They will find that the Fire has reached them according to their deeds. Some will have been reached up to their feet, some halfway up their shins, some up to their knees, some up to their waists, some up to their chests, and some up to their necks, while their faces will not have been covered. They will bring them out and cast them into the Water of Life.” It was asked: “O Messenger of Allah, what is the Water of Life?” He replied: “It is the washing-water of the people of Paradise, and they will grow as a plant grows.” On another occasion he said: “Just as a plant grows in the debris carried by a flood. Then the Prophets will intercede for everyone who sincerely testified that there is no deity except Allah, and they will bring them out of it. Then Allah, through His mercy, will show compassion to those remaining therein, and He will not leave in it any servant who has in his heart the weight of a grain of faith except that He will bring him out.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (11081) واللفظ له، وابن خزيمة في التوحيد (648)، وابن ماجه (4280) مختصرا، والحاكم (8738) - وصححه -."},{"num":16472,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:  يَخْرُجُ مِنَ النَّارِ أَرْبَعَةٌ، فَيُعْرَضُونَ عَلَى اللَّهِ، فَيَلْتَفِتُ أَحَدُهُمْ، فَيَقُولُ: أَيْ رَبِّ، إِذْ أَخْرَجْتَنِي مِنْهَا فَلَا تُعِدْنِي فِيهَا، فَيُنْجِيهِ اللهُ مِنْهَا."],"takhrij":"صحيح: رواه مسلم في الإيمان 192: 321) عن هداب بن خالد الأزدي، حدثنا حماد بن سلمة، عن أبي عمران وثابت، عن أنس فذكره.","grade":"صحيح","chapter_ar":"باب من يخرج من النار يحسن الظن بالله أن لا يعيده فيها","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (321 :192).","chapter_en":"One Who Is Brought Out of the Fire Thinks Well of Allah That He Will Not Return Him to It","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل النار","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of the Fire","part_no":67,"group_no":4,"chapter_no":3,"content":{"translation":{"en":["Anas ibn Mālik narrated that the Messenger of Allah ﷺ said: “Four people will be brought out of the Fire and presented before Allah. One of them will turn back and say: ‘My Lord, now that You have brought me out of it, do not return me to it.’ So Allah will save him from it.”"]}},"tuhfa":{},"full":1,"rep":[75,152,16189],"tks":"صحيح: رواه مسلم (321 :192)."},{"num":16473,"demo":false,"sanad":"","matn":["عن النُّعْمَانِ بْنِ بَشِيرٍ قَالَ: سَمِعْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: إِنَّ أَهْوَنَ أَهْلِ النَّارِ عَذَابًا يَوْمَ الْقِيَامَةِ لَرَجُلٌ تُوضَعُ فِي أَخْمَصِ قَدَمَيْهِ جَمْرَةٌ يَغْلِي مِنْهَا دِمَاغُهُ."],"takhrij":"متفق عليه: رواه البخاري في الرقاق (6561)، ومسلم في الإيمان (213) كلاهما عن محمد بن بشار، حدثنا غندر قال: حدثنا شعبة، قال: سمعت أبا إسحاق قال: سمعت النعمان بن بشير فذكر الحديث. واللفظ للبخاري.","grade":"متفق عليه","chapter_ar":"باب أهون أهل النار عذابًا","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6561) and Muslim (213).","chapter_en":"The Person Receiving the Lightest Punishment among the People of the Fire","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل النار","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of the Fire","part_no":67,"group_no":4,"chapter_no":4,"content":{"translation":{"en":["Al-Nuʿmān ibn Bashīr narrated: I heard the Prophet ﷺ say: “The person receiving the lightest punishment among the people of the Fire on the Day of Resurrection will be a man beneath the arches of whose feet a burning coal will be placed, causing his brain to boil.”"]},"buhuth":{"en":["Muslim also narrates:","“Two burning coals will be placed beneath the arches of his feet, causing his brain to boil.”","Al-Bukhārī (6562) adds at the end:","“Just as a cooking pot or a narrow-necked vessel boils.”","Muslim also narrates through another route:","“The person receiving the lightest punishment among the people of the Fire will be one who has two sandals and two straps of fire, because of which his brain will boil just as a cooking pot boils. He will think that no one is suffering a punishment more severe than his, yet he will in fact be the one receiving the lightest punishment among them.”","The author explains that “akhmaṣ” is the hollow part of the foot that does not touch the ground.","“Shirākān” is the dual of shirāk, one of the straps of a sandal which lies across its surface and over the top of the foot.","“Al-mirjal” is a well-known cooking pot, whether made of iron, copper, stone, or earthenware."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (6561)، ومسلم (213)."},{"num":16474,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:  إِنَّ أَدْنَى أَهْلِ النَّارِ عَذَابًا يَنْتَعِلُ بِنَعْلَيْنِ مِنْ نَارٍ يَغْلِي دِمَاغُهُ مِنْ حَرَارَةِ نَعْلَيْهِ."],"takhrij":"صحيح: رواه مسلم في الإيمان (211) عن أبي بكر بن أبي شيبة، حدثنا يحيى بن أبي بكير، حدثنا زهير بن محمد، عن سهيل بن أبي صالح، عن النعمان بن أبي عياش، عن أبي سعيد الخدري فذكره.","grade":"صحيح","chapter_ar":"باب أهون أهل النار عذابًا","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (211).","chapter_en":"The Person Receiving the Lightest Punishment among the People of the Fire","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل النار","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of the Fire","part_no":67,"group_no":4,"chapter_no":4,"content":{"translation":{"en":["Abū Saʿīd al-Khudrī narrated that the Messenger of Allah ﷺ said: “The person receiving the lightest punishment among the people of the Fire will wear two sandals of fire, from whose heat his brain will boil.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (211)."},{"num":16475,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:  أَهْوَنُ أَهْلِ النَّارِ عَذَابًا أَبُو طَالِبٍ، وَهُوَ مُنْتَعِلٌ بِنَعْلَيْنِ يَغْلِي مِنْهُمَا دِمَاغُهُ."],"takhrij":"صحيح: رواه مسلم في الإيمان (212) عن أبي بكر بن أبي شيبة، حدثنا عفان، حدثنا حماد بن سلمة، حدثنا ثابت، عن أبي عثمان النهدي، عن ابن عباس فذكره.","grade":"صحيح","chapter_ar":"باب أهون أهل النار عذابًا","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (212).","chapter_en":"The Person Receiving the Lightest Punishment among the People of the Fire","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل النار","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of the Fire","part_no":67,"group_no":4,"chapter_no":4,"content":{"translation":{"en":["Ibn ʿAbbās narrated that the Messenger of Allah ﷺ said: “The person receiving the lightest punishment among the people of the Fire is Abū Ṭālib. He will wear two sandals because of which his brain will boil.”"]}},"tuhfa":{},"full":1,"rep":[8605],"tks":"صحيح: رواه مسلم (212)."},{"num":16476,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَهْوَنُ أَهْلِ النَّارِ عَذَابًا، عَلَيْهِ نَعْلَانِ يَغْلِي مِنْهُمَا دِمَاغُهُ."],"takhrij":"حسن: رواه أحمد (9576)، وابن حبان (7472)، والحاكم (8729) كلهم من طريق محمد بن عجلان قال: سمعت أبي، يحدث عن أبي هريرة فذكره.","grade":"حسن","chapter_ar":"باب أهون أهل النار عذابًا","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (9576), Ibn Ḥibbān (7472), and al-Ḥākim (4/580).","chapter_en":"The Person Receiving the Lightest Punishment among the People of the Fire","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل النار","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of the Fire","part_no":67,"group_no":4,"chapter_no":4,"content":{"translation":{"en":["Abū Hurayrah narrated that the Prophet ﷺ said: “The person receiving the lightest punishment among the people of the Fire will have two sandals upon him, because of which his brain will boil.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (9576)، وابن حبان (7472)، والحاكم (8729)."},{"num":16477,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ  أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ذُكِرَ عِنْدَهُ عَمُّهُ أَبُو طَالِبٍ فَقَالَ: لَعَلَّهُ تَنْفَعُهُ شَفَاعَتِي يَوْمَ الْقِيَامَةِ، فَيُجْعَلُ فِي ضَحْضَاحٍ مِنْ نَارٍ يَبْلُغُ كَعْبَيْهِ يَغْلِي مِنْهُ دِمَاغُهُ."],"takhrij":"متفق عليه: رواه البخاري في الرقاق (3885)، ومسلم في الإيمان (210) كلاهما من حديث الليث، حدثنا ابن الهاد، عن عبد الله بن خباب، عن أبي سعيد الخدري فذكره.","grade":"متفق عليه","chapter_ar":"باب تخفيف العذاب لأبي طالب بشفاعة النبي ﷺ","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (3885) and Muslim (210).","chapter_en":"The Punishment of Abū Ṭālib Will Be Lightened through the Intercession of the Prophet ﷺ","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل النار","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of the Fire","part_no":67,"group_no":4,"chapter_no":5,"content":{"translation":{"en":["Abū Saʿīd narrated: Abū Ṭālib, the uncle of the Messenger of Allah ﷺ, was mentioned in his presence, and he said: “Perhaps my intercession will benefit him on the Day of Resurrection, so that he will be placed in a shallow portion of the Fire reaching his ankles, from which his brain will boil.”"]},"buhuth":{"en":["The word “ḍaḥḍāḥ” refers literally to shallow water spread over the ground to about ankle level, and here it is used figuratively for the Fire."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (3885)، ومسلم (210)."},{"num":16478,"demo":false,"sanad":"","matn":["عَنْ عَبَّاسِ بْنِ عَبْدِ الْمُطَّلِبِ، قَالَ: يَا رَسُولَ اللَّهِ هَلْ نَفَعْتَ أَبَا طَالِبٍ بِشَىْءٍ، فَإِنَّهُ كَانَ يَحُوطُكَ وَيَغْضَبُ لَكَ، قَالَ: نَعَمْ، هُوَ فِي ضَحْضَاحٍ مِنْ نَارٍ، لَوْلاَ أَنَا لَكَانَ فِي الدَّرَكِ الأَسْفَلِ مِنَ النَّارِ.","وفي لفظ: نعم، وجدته في غمرات من النار فأخرجته إلى ضحضاح."],"takhrij":"متفق عليه: رواه البخاري في الأدب (6208)، ومسلم في الإيمان (209: 357) كلاهما من طريق أبي عوانة، عن عبدالملك بن عمير، عن عبد الله بن الحارث بن نوفل، عن العباس بن عبد المطلب فذكره.","grade":"متفق عليه","chapter_ar":"باب تخفيف العذاب لأبي طالب بشفاعة النبي ﷺ","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6208) and Muslim (357 :209).","chapter_en":"The Punishment of Abū Ṭālib Will Be Lightened through the Intercession of the Prophet ﷺ","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل النار","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of the Fire","part_no":67,"group_no":4,"chapter_no":5,"content":{"translation":{"en":["Al-ʿAbbās ibn ʿAbd al-Muṭṭalib asked: “O Messenger of Allah, have you benefited Abū Ṭālib in any way? He used to protect you and become angry on your behalf.” He replied: “Yes. He is in a shallow portion of the Fire. Were it not for me, he would have been in the lowest depth of the Fire.” In another wording: “Yes. I found him in the depths of the Fire and brought him out to a shallow portion of it.”"]},"buhuth":{"en":["The word “ghamarāt”, singular ghamrah, means the deep or overwhelming part of something."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (6208)، ومسلم (209: 357)."},{"num":16479,"demo":false,"sanad":"","matn":["عن أنس بْنِ مَالِكٍ، رَضِيَ اللَّهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: يَقُولُ اللَّهُ تَعَالَى لأَهْوَنِ أَهْلِ النَّارِ عَذَابًا يَوْمَ الْقِيَامَةِ: لَوْ أَنَّ لَكَ مَا فِي الأَرْضِ مِنْ شَىْءٍ أَكُنْتَ تَفْتَدِي بِهِ؟ فَيَقُولُ: نَعَمْ. فَيَقُولُ: أَرَدْتُ مِنْكَ أَهْوَنَ مِنْ هَذَا، وَأَنْتَ فِي صُلْبِ آدَمَ: أَنْ لاَ تُشْرِكَ بِي شَيْئًا، فَأَبَيْتَ إِلاَّ أَنْ تُشْرِكَ بِي."],"takhrij":"متفق عليه: رواه البخاري في الرقاق (6557)، ومسلم في الجنة (2805) كلاهما من طريق شعبة، عن أبي عمران، عن أنس فذكره.","grade":"متفق عليه","chapter_ar":"باب تمني أهل النار الفداء بكل ما في الأرض والخروج من النار","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6557) and Muslim (2805).","chapter_en":"The People of the Fire Will Wish to Ransom Themselves with Everything on Earth and Escape the Fire","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل النار","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of the Fire","part_no":67,"group_no":4,"chapter_no":6,"content":{"translation":{"en":["Anas ibn Mālik narrated that the Prophet ﷺ said: “Allah, the Exalted, will say to the person receiving the lightest punishment among the people of the Fire on the Day of Resurrection: ‘If you possessed everything on earth, would you ransom yourself with it?’ He will say: ‘Yes.’ Allah will say: ‘I asked of you something easier than that while you were still in the loins of Ādam: that you should not associate anything with Me, but you refused except to associate partners with Me.’”"]},"buhuth":{"en":["Al-Ḥāfiẓ Ibn Ḥajar commented that the words:","“while you were in the loins of Ādam”","allude to the statement of Allah, the Exalted:","“And when your Lord took from the children of Ādam, from their loins, their descendants and made them testify concerning themselves: ‘Am I not your Lord?’ They said: ‘Yes, we testify,’ lest you should say on the Day of Resurrection, ‘Indeed, we were unaware of this.’”","[al-Aʿrāf 7:172]","See: Fatḥ al-Bārī (6/369)."]},"intro":{"ar":["قال اللّٰه تعالى:","﴿إِنَّ الَّذِينَ كَفَرُوا لَوْ أَنَّ لَهُمْ مَا فِي الْأَرْضِ جَمِيعًا وَمِثْلَهُ مَعَهُ لِيَفْتَدُوا بِهِ مِنْ عَذَابِ يَوْمِ الْقِيَامَةِ مَا تُقُبِّلَ مِنْهُمْ وَلَهُمْ عَذَابٌ أَلِيمٌ﴾ [المائدة: ٣٦]."],"en":["Allah, the Exalted, says:","“Indeed, those who disbelieve—even if they possessed everything on earth and another equal amount with it to ransom themselves from the punishment of the Day of Resurrection, it would not be accepted from them, and they will have a painful punishment.”","[al-Māʾidah 5:36]"]}},"tuhfa":{},"full":1,"dr":1,"rep":[208],"tks":"متفق عليه: رواه البخاري (6557)، ومسلم (2805)."},{"num":16480,"demo":false,"sanad":"","matn":["عن أنس بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ أَنَّ نَبِيَّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَقُولُ: يُجَاءُ بِالْكَافِرِ يَوْمَ الْقِيَامَةِ، فَيُقَالُ لَهُ: أَرَأَيْتَ لَوْ كَانَ لَكَ مِلْءُ الأَرْضِ ذَهَبًا أَكُنْتَ تَفْتَدِي بِهِ؟ فَيَقُولُ: نَعَمْ. فَيُقَالُ لَهُ: قَدْ كُنْتَ سُئِلْتَ مَا هُوَ أَيْسَرُ مِنْ ذَلِكَ.","وفي رواية: فيقال له: كذبت، قد سئلت ما هو أيسر من ذلك."],"takhrij":"متفق عليه: رواه البخاري في الرقاق (6538)، ومسلم في الجنة (2805: 52-53) كلاهما من طرق عن قتادة، عن أنس فذكره.","grade":"متفق عليه","chapter_ar":"باب تمني أهل النار الفداء بكل ما في الأرض والخروج من النار","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6538) and Muslim (52-53 :2805).","chapter_en":"The People of the Fire Will Wish to Ransom Themselves with Everything on Earth and Escape the Fire","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل النار","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of the Fire","part_no":67,"group_no":4,"chapter_no":6,"content":{"translation":{"en":["Anas ibn Mālik narrated that the Prophet of Allah ﷺ used to say: “A disbeliever will be brought on the Day of Resurrection and asked: ‘If you possessed enough gold to fill the earth, would you ransom yourself with it?’ He will reply: ‘Yes.’ It will be said to him: ‘You were asked for something far easier than that.’” In another narration: “It will be said to him: ‘You have lied. You were asked for something far easier than that.’”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (6538)، ومسلم (53-52 :2805)."},{"num":16481,"demo":false,"sanad":"","matn":["عن أَبِي أُمَامَةَ الباهلي قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، يَقُولُ: بَيْنَا أَنَا نَائِمٌ إِذْ أَتَانِي رَجُلَانِ، فَأَخَذَا بِضَبْعَيَّ، فَأَتَيَا بِي جَبَلًا وَعْرًا، فَقَالَا لِي: اصْعَدْ حَتَّى إِذَا كُنْتُ فِي سَوَاءِ الْجَبَلِ، فَإِذَا أَنَا بِصَوْتٍ شَدِيدٍ، فَقُلْتُ: مَا هَذِهِ الأَصْوَاتُ؟ قَالَ: هَذَا عُوَاءُ أَهْلِ النَّارِ، ثُمَّ انْطُلِقَ بِي فَإِذَا أَنَا بِقَوْمٍ مُعَلَّقِينَ بِعَرَاقِيبِهِمْ مُشَقَّقَةٍ أَشْدَاقُهُمْ تَسِيلُ أَشْدَاقُهُمْ دَمًا، فَقُلْتُ: مَنْ هَؤُلَاءِ؟ قِيلَ: هَؤُلَاءِ الَّذِينَ يُفْطِرُونَ قَبْلَ تَحِلَّةِ صَوْمِهِمْ. ثُمَّ انْطُلِقَ بِي، فَإِذَا أَنَا بِقَوْمٍ أَشَدِّ شَيْءٍ انْتِفَاخًا، وَأَنْتَنِهِ رِيحًا، وَأَسْوَئِهِ مَنْظَرًا، قُلْتُ: مَنْ هَؤُلَاءِ؟ قِيلَ: الزَّانُونَ وَالزَّوَانِي. ثُمَّ انْطُلِقَ بِي، فَإِذَا أَنَا بِنِسَاءٍ تَنْهَشُ ثُدِيَّهُنَّ الْحَيَّاتُ، قُلْتُ: مَا بَالُ هَؤُلَاءِ؟ قِيلَ: هَؤُلَاءِ اللَاّتِي يَمْنَعْنَ أَوْلَادَهُنَّ أَلْبَانَهُنَّ. ثُمَّ."],"takhrij":"صحيح: رواه ابن خزيمة (1986)، وعنه ابن حبان (7491)، والحاكم (2837)، وعنه البيهقي (8006) كلهم من حديث بشر بن بكر، حدثني ابن جابر، حدثني سليم بن عامر، حدثني أبو أمامة الباهلي فذكره بسياق طويل.","grade":"صحيح","chapter_ar":"باب تنوع العذاب في النار حسب الجرائم","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by Ibn Khuzaymah (1986); through him by Ibn Ḥibbān (7491); al-Ḥākim (1568); and through him by al-Bayhaqī (4/216).","chapter_en":"The Different Forms of Punishment in the Fire According to the Crimes Committed","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل النار","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of the Fire","part_no":67,"group_no":4,"chapter_no":7,"content":{"translation":{"en":["Abū Umāmah al-Bāhilī said: I heard the Messenger of Allah ﷺ say: “While I was sleeping, two men came to me, took hold of me by my upper arms, and brought me to a rugged mountain. They said to me, ‘Climb.’ When I reached the middle of the mountain, I suddenly heard a terrible sound. I said, ‘What are these sounds?’ He said, ‘This is the howling of the people of the Fire.’ “Then I was taken onward, and suddenly I came upon people suspended by their Achilles tendons, with the corners of their mouths torn open and blood flowing from their mouths. I said, ‘Who are these?’ He said, ‘These are those who break their fast before the proper time for ending their fast.’ “Then I was taken onward, and suddenly I came upon people who were extremely swollen, with the foulest odor and the most horrible appearance. I said, ‘Who are these?’ It was said, ‘The male and female adulterers.’ “Then I was taken onward, and suddenly I came upon women whose breasts were being bitten by snakes. I said, ‘What is the matter with these women?’ It was said, ‘These are women who withheld their milk from their children…’” The ḥadīth continues."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه ابن خزيمة (1986)، وعنه ابن حبان (7491)، والحاكم (1568)، وعنه البيهقي (8006)."},{"num":16482,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:  ضِرْسُ الْكَافِرِ، أَوْ نَابُ الْكَافِرِ مِثْلُ أُحُدٍ، وَغِلَظُ جِلْدِهِ مَسِيرَةُ ثَلَاثٍ."],"takhrij":"صحيح: رواه مسلم في الجنة وصفة نعيمها (2851) عن سريج بن يونس، حدثنا حميد بن عبدالرحمن، عن الحسن بن صالح، عن هارون بن سعد، عن أبي حازم، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب في عظم أهل النار وغلظ أجسامهم حسب أعمالهم وجرائمهم في الدنيا","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2851).","chapter_en":"The Enormous Size and Thickness of the Bodies of the People of the Fire According to Their Deeds and Crimes in This World","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل النار","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of the Fire","part_no":67,"group_no":4,"chapter_no":8,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “The molar tooth—or canine tooth—of the disbeliever will be like Mount Uḥud, and the thickness of his skin will be a journey of three days.”"]},"intro":{"ar":["قال الله تعالى:","﴿إِنَّ الَّذِينَ كَفَرُوا بِآيَاتِنَا سَوْفَ نُصْلِيهِمْ نَارًا كُلَّمَا نَضِجَتْ جُلُودُهُمْ بَدَّلْنَاهُمْ جُلُودًا غَيْرَهَا لِيَذُوقُوا الْعَذَابَ إِنَّ اللَّهَ كَانَ عَزِيزًا حَكِيمًا﴾ [النساء: ٥٦].","أي تبدل جلودهم لأن الإحساس بالألم مرتبط بالجلود دون اللحوم.","وقد جاء وصف جلود الكفار في النار في الحديث:"],"en":["Allah, the Exalted, says:","“Indeed, those who disbelieve in Our signs, We will burn them in a Fire. Whenever their skins are completely burned, We will replace them with other skins so that they may taste the punishment. Indeed, Allah is Almighty, All-Wise.”","[al-Nisāʾ 4:56]","That is, their skins will be replaced because the sensation of pain is connected to the skin rather than the flesh.","The description of the skins of the disbelievers in the Fire has also been mentioned in the hadiths:"]}},"tuhfa":{},"full":1,"rep":[12168],"tks":"صحيح: رواه مسلم (2851)."},{"num":16483,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَا بَيْنَ مَنْكِبَىِ الْكَافِرِ مَسِيرَةُ ثَلاَثَةِ أَيَّامٍ لِلرَّاكِبِ الْمُسْرِعِ."],"takhrij":"متفق عليه: رواه البخاري في الرقاق (6551)، ومسلم في الجنة (2852) كلاهما من طريق فضيل (هو ابن غزوان)، عن أبي حازم، عن أبي هريرة فذكره.","grade":"متفق عليه","chapter_ar":"باب في عظم أهل النار وغلظ أجسامهم حسب أعمالهم وجرائمهم في الدنيا","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6551) and Muslim (2852).","chapter_en":"The Enormous Size and Thickness of the Bodies of the People of the Fire According to Their Deeds and Crimes in This World","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل النار","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of the Fire","part_no":67,"group_no":4,"chapter_no":8,"content":{"translation":{"en":["Abū Hurayrah narrated that the Prophet ﷺ said: “The distance between the two shoulders of the disbeliever in the Fire will be a journey of three days for a swift rider.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (6551)، ومسلم (2852)."},{"num":16484,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِنَّ غِلَظَ جِلْدِ الْكَافِرِ اثْنَانِ وَأَرْبَعُونَ ذِرَاعًا، وَإِنَّ ضِرْسَهُ مِثْلُ أُحُدٍ، وَإِنَّ مَجْلِسَهُ مِنْ جَهَنَّمَ كَمَا بَيْنَ مَكَّةَ وَالْمَدِينَةِ."],"takhrij":"صحيح: رواه الترمذي (2577) واللفظ له، وابن أبي عاصم في السنة (610)، وابن حبان (7486)، والحاكم (8760)، والبيهقي في الأسماء والصفات (743) كلهم من طريق عبيد الله بن موسى، أخبرنا شيبان، عن الأعمش، عن أبي صالح، عن أبي هريرة فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب في عظم أهل النار وغلظ أجسامهم حسب أعمالهم وجرائمهم في الدنيا","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by al-Tirmidhī (2577), whose wording this is, Ibn Abī ʿĀṣim in al-Sunnah (610), Ibn Ḥibbān (7486), al-Ḥākim (4/595), and al-Bayhaqī in al-Asmāʾ wa-l-Ṣifāt (743).","chapter_en":"The Enormous Size and Thickness of the Bodies of the People of the Fire According to Their Deeds and Crimes in This World","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل النار","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of the Fire","part_no":67,"group_no":4,"chapter_no":8,"content":{"translation":{"en":["Abū Hurayrah narrated that the Prophet ﷺ said: “The thickness of the disbeliever’s skin will be forty-two cubits, his molar tooth will be like Mount Uḥud, and the space he occupies in Hell will be like the distance between Makkah and Madīnah.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الترمذي (2577) واللفظ له، وابن أبي عاصم في السنة (610)، وابن حبان (7486)، والحاكم (8760)، والبيهقي في الأسماء والصفات (743)."},{"num":16485,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: ضِرْسُ الْكَافِرِ يَوْمَ الْقِيَامَةِ مِثْلُ أُحُدٍ، وَفَخِذُهُ مِثْلُ الْبَيْضَاءِ، وَمَقْعَدُهُ مِنَ النَّارِ مَسِيرَةَ ثَلاَثٍ مِثْلُ الرَّبَذَةِ."],"takhrij":"حسن: رواه الترمذي (2578) عن علي بن حجر، أخبرنا محمد بن عمار، حدثني جدي محمد بن عمار و صالح مولى التوأمة، عن أبي هريرة قال: فذكره.","grade":"حسن","chapter_ar":"باب في عظم أهل النار وغلظ أجسامهم حسب أعمالهم وجرائمهم في الدنيا","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhī (2578).","chapter_en":"The Enormous Size and Thickness of the Bodies of the People of the Fire According to Their Deeds and Crimes in This World","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل النار","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of the Fire","part_no":67,"group_no":4,"chapter_no":8,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “The molar tooth of the disbeliever on the Day of Resurrection will be like Mount Uḥud, his thigh will be like al-Bayḍāʾ, and the space he occupies in the Fire will be a journey of three days, like the distance to al-Rabadhah.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الترمذي (2578)."},{"num":16486,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: ضِرْسُ الْكَافِرِ يَوْمَ الْقِيَامَةِ مِثْلُ أُحُدٍ، وَعَرْضُ جِلْدِهِ سَبْعُونَ ذِرَاعًا، وَفَخِذُهُ مِثْلُ وَرِقَانَ، وَمَقْعَدُهُ مِنَ النَّارِ مِثْلُ مَا بَيْنِي وَبَيْنَ الرَّبَذَةِ."],"takhrij":"حسن: رواه أحمد (8345) عن ربعي بن إبراهيم قال: ثنا عبد الرحمن بن إسحاق، عن سعيد بن أبي سعيد، عن أبي هريرة قال: فذكره.","grade":"حسن","chapter_ar":"باب في عظم أهل النار وغلظ أجسامهم حسب أعمالهم وجرائمهم في الدنيا","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (8345).","chapter_en":"The Enormous Size and Thickness of the Bodies of the People of the Fire According to Their Deeds and Crimes in This World","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل النار","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of the Fire","part_no":67,"group_no":4,"chapter_no":8,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “The molar tooth of the disbeliever on the Day of Resurrection will be like Mount Uḥud, the width of his skin will be seventy cubits, his thigh will be like Mount Warqān, and the space he occupies in the Fire will be like the distance between here and al-Rabadhah.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (8345)."},{"num":16487,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: ضِرْسُ الْكَافِرِ مِثْلُ أُحُدٍ، وَفَخِذُهُ مِثْلُ الْبَيْضَاءِ، وَمَقْعَدُهُ مِنَ النَّارِ كَمَا بَيْنَ قُدَيْدٍ، وَمَكَّةَ، وَكَثَافَةُ جِلْدِهِ اثْنَانِ وَأَرْبَعُونَ ذِرَاعًا بِذِرَاعِ الْجَبَّارِ."],"takhrij":"حسن: رواه أحمد (8410)، وابن أبي عاصم في السنة (611) كلاهما من طريق عبد الرحمن بن عبد الله بن دينار، عن زيد بن أسلم، عن عطاء بن يسار، عن أبي هريرة فذكره.","grade":"حسن","chapter_ar":"باب في عظم أهل النار وغلظ أجسامهم حسب أعمالهم وجرائمهم في الدنيا","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (8410) and Ibn Abī ʿĀṣim in al-Sunnah (611).","chapter_en":"The Enormous Size and Thickness of the Bodies of the People of the Fire According to Their Deeds and Crimes in This World","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل النار","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of the Fire","part_no":67,"group_no":4,"chapter_no":8,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “The molar tooth of the disbeliever will be like Mount Uḥud, his thigh will be like al-Bayḍāʾ, the space he occupies in the Fire will be like the distance between Qudayd and Makkah, and the thickness of his skin will be forty-two cubits measured by the cubit of the jabbār.”"]},"buhuth":{"en":["Regarding the phrase “by the cubit of the jabbār,” the author explains that what is intended is the cubit of an exceptionally tall man whose height is beyond the reach of ordinary people. It is not intended as a reference to the Lord, Blessed and Exalted.","According to what the author considers the sounder view among the scholars, this hadith is not among the hadiths concerning the Divine Attributes. He then cites a number of statements from verifying scholars concerning this matter:","Al-Ḥāfiẓ Abū Bakr ibn Isḥāq, the teacher of al-Ḥākim, said:","“The meaning of his statement, ‘by the cubit of the jabbār,’ is: the cubit of one of the mighty men among human beings from the earlier generations, one who was greater in physical build and whose limbs and forearms were longer than those of ordinary people.”","Al-Ḥākim mentioned this in al-Mustadrak.","Ibn Qutaybah said in Taʾwīl Mukhtalif al-Ḥadīth:","“This hadith has a sound interpretation, if this is what the Prophet ﷺ intended: that al-jabbār here means a king. Allah, Blessed and Exalted, says:","‘And you are not over them a tyrannical controller.’","[Qāf 50:45]","meaning a ruler imposed over them. The jabābirah are kings. This resembles the way people say: ‘It is such-and-such cubits according to the king’s cubit,’ meaning the larger cubit. I think it referred to one of the kings of Persia who possessed an unusually long cubit, and the measure came to be attributed to him.”","Al-Dhahabī said:","“This has nothing to do with the Divine Attributes.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (8410)، وابن أبي عاصم في السنة (611)."},{"num":16488,"demo":false,"sanad":"","matn":["عن يَزِيدَ بْنِ حَيَّانَ التَّيْمِيِّ قَالَ: انْطَلَقْتُ أَنَا وَحُصَيْنُ بْنُ سَبْرَةَ وَعُمَرُ بْنُ مُسْلِمٍ إِلَى زَيْدِ بْنِ أَرْقَمَ، وَحَدَّثَنَا زيد فِي مَجْلِسِهِ ذَلِكَ قَالَ: إِنَّ الرَّجُلَ مِنْ أَهْلِ النَّارِ لَيُعَظَّمُ لِلنَّارِ حَتَّى يَكُونَ الضِّرْسُ مِنْ أَضْرَاسِهِ كأحد."],"takhrij":"صحيح: رواه أحمد (19265، 19266) عن إسماعيل بن إبراهيم، عن أبي حيان التيمي، حدثني يزيد بن حيان التيمي قال: فذكره.","grade":"صحيح","chapter_ar":"باب في عظم أهل النار وغلظ أجسامهم حسب أعمالهم وجرائمهم في الدنيا","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by Aḥmad (19266, 19265).","chapter_en":"The Enormous Size and Thickness of the Bodies of the People of the Fire According to Their Deeds and Crimes in This World","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل النار","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of the Fire","part_no":67,"group_no":4,"chapter_no":8,"content":{"translation":{"en":["Yazīd ibn Ḥayyān al-Taymī narrated: Ḥuṣayn ibn Sabrah, ʿUmar ibn Muslim, and I went to Zayd ibn Arqam. During that gathering, Zayd narrated to us: “A man from among the people of the Fire will be made so enormous for the Fire that one of his molar teeth will be like Mount Uḥud.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (19266، 19265)."},{"num":16489,"demo":false,"sanad":"","matn":["عَنْ مُجَاهِدٍ، قَالَ: قَالَ ابْنُ عَبَّاسٍ: أَتَدْرِي مَا سِعَةُ جَهَنَّمَ؟ قُلْتُ: لَا، قَالَ: أَجَلْ، وَاللهِ مَا تَدْرِي، إِنَّ بَيْنَ شَحْمَةِ أُذُنِ أَحَدِهِمْ وَبَيْنَ عَاتِقِهِ مَسِيرَةَ سَبْعِينَ خَرِيفًا، تَجْرِي فِيهَا أَوْدِيَةُ الْقَيْحِ وَالدَّمِ، قُلْتُ: أَنْهَارًا؟ قَالَ: لَا، بَلْ أَوْدِيَةً، ثُمَّ قَالَ: أَتَدْرُونَ مَا سِعَةُ جَهَنَّمَ؟ قُلْتُ: لَا، قَالَ: أَجَلْ، وَاللهِ مَا نَدْرِي، حَدَّثَتْنِي عَائِشَةُ أَنَّهَا سَأَلَتْ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ قَوْلِهِ: ﴿وَالْأَرْضُ جَمِيعًا قَبْضَتُهُ يَوْمَ الْقِيَامَةِ وَالسَّمَاوَاتُ مَطْوِيَّاتٌ بِيَمِينِهِ﴾ [الزمر: ٦٧] فَأَيْنَ النَّاسُ يَوْمَئِذٍ يَا رَسُولَ اللَّهِ؟ قَالَ: هُمْ عَلَى جِسْرِ جَهَنَّمَ."],"takhrij":"صحيح: رواه أحمد (24856)، والحاكم (3630)، والبغوي في شرح السنة (4415) كلهم من طرق عن عبد الله بن المبارك، عن عنبسة بن سعيد، عن حبيب بن أبي عمرة، عن مجاهد قال: فذكره.","grade":"صحيح","chapter_ar":"باب في عظم أهل النار وغلظ أجسامهم حسب أعمالهم وجرائمهم في الدنيا","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by Aḥmad (24856), al-Ḥākim (2/436), and al-Baghawī in Sharḥ al-Sunnah (4415).","chapter_en":"The Enormous Size and Thickness of the Bodies of the People of the Fire According to Their Deeds and Crimes in This World","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل النار","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of the Fire","part_no":67,"group_no":4,"chapter_no":8,"content":{"translation":{"en":["Mujāhid narrated: Ibn ʿAbbās said: “Do you know how vast Hell is?” I replied: “No.” He said: “Indeed, by Allah, you do not know. The distance between the earlobe of one of its inhabitants and his shoulder will be a journey of seventy years, and through that space valleys of pus and blood will flow.” I asked: “Rivers?” He replied: “No, rather valleys.” Then he said: “Do you know how vast Hell is?” I replied: “No.” He said: “Indeed, by Allah, we do not know. ʿĀ’ishah narrated to me that she asked the Messenger of Allah ﷺ concerning the statement of Allah: ‘The whole earth will be in His Grip on the Day of Resurrection, and the heavens will be folded in His Right Hand.’ [al-Zumar 39:67] ‘Where will the people be at that time, O Messenger of Allah?’” He replied: “They will be upon the bridge over Hell.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (24856)، والحاكم (3630)، والبغوي في شرح السنة (4415)."},{"num":16490,"demo":false,"sanad":"","matn":["عَنْ أُمِّ الْمُؤْمِنِينَ عَائِشَةَ قَالَتْ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : رَأَيْتُ جَهَنَّمَ يَحْطِمُ بعضه بَعْضًا، وَرَأَيْتُ عَمْرًا يَجُرُّ قُصْبَهُ، وَهْوَ أَوَّلُ مَنْ سَيَّبَ السَّوَائِبَ."],"takhrij":"متفق عليه: رواه البخاري في التفسير (4624)، ومسلم في الكسـوف (901: 3) كلاهما من طريق يونس، عن ابن شهاب قال: أخبرني عروة بن الزبير، عن عائشة قالت: فذكرته. واللفظ للبخاري وسياق مسلم طويل.","grade":"متفق عليه","chapter_ar":"باب رؤية النبي ﷺ عمرو بن عامر الخزاعي في النار وهو أول من سيب السوائب","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (4624) and Muslim (3:901).","chapter_en":"The Prophet ﷺ Saw ʿAmr ibn ʿĀmir al-Khuzāʿī in the Fire; He Was the First to Set Free the Sāʾibah Animals","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل النار","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of the Fire","part_no":67,"group_no":4,"chapter_no":9,"content":{"translation":{"en":["ʿĀ’ishah narrated that the Messenger of Allah ﷺ said: “I saw Hell crushing its parts against one another, and I saw ʿAmr dragging his intestines. He was the first to set free the sāʾibah animals.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (4624)، ومسلم (901: 3)."},{"num":16491,"demo":false,"sanad":"","matn":["عن أَبِي هُرَيْرَةَ قَالَ: قَالَ أَبُو هُرَيْرَةَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: رَأَيْتُ عَمْرَو بْنَ عَامِرٍ الْخُزَاعِيَّ يَجُرُّ قُصْبَهُ فِي النَّارِ، كَانَ أَوَّلَ مَنْ سَيَّبَ السَّوَائِبَ."],"takhrij":"متفق عليه: رواه البخاري في التفسير (4623)، ومسلم في الجنة (2856: 51) كلاهما من طريق إبراهيم بن سعد، عن صالح بن كيسان، عن ابن شهاب، عن سعيد بن المسيب، عن أبي هريرة فذكره.","grade":"متفق عليه","chapter_ar":"باب رؤية النبي ﷺ عمرو بن عامر الخزاعي في النار وهو أول من سيب السوائب","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (4623) and Muslim (51 :2856).","chapter_en":"The Prophet ﷺ Saw ʿAmr ibn ʿĀmir al-Khuzāʿī in the Fire; He Was the First to Set Free the Sāʾibah Animals","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل النار","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of the Fire","part_no":67,"group_no":4,"chapter_no":9,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “I saw ʿAmr ibn ʿĀmir al-Khuzāʿī dragging his intestines in the Fire. He was the first to set free the sāʾibah animals.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (4623)، ومسلم (2856: 51)."},{"num":16492,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : رَأَيْتُ عَمْرَو بْنَ لُحَيِّ بْنِ قمحة بْنِ خِنْدِفَ أَخَا بَنِي كَعْبٍ هولاء يضر قُصْبَهُ فِي النَّارِ."],"takhrij":"صحيح: رواه مسلم في الجنة (2856) عن زهير بن حرب، حدثنا جرير، عن سهيل، عن أبيه، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب رؤية النبي ﷺ عمرو بن عامر الخزاعي في النار وهو أول من سيب السوائب","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2856).","chapter_en":"The Prophet ﷺ Saw ʿAmr ibn ʿĀmir al-Khuzāʿī in the Fire; He Was the First to Set Free the Sāʾibah Animals","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل النار","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of the Fire","part_no":67,"group_no":4,"chapter_no":9,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “I saw ʿAmr ibn Luḥayy ibn Qamaʿah ibn Khindif, the forefather of these Banū Kaʿb, dragging his intestines in the Fire.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (2856)."},{"num":16493,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: عُرِضِتْ عَلَيَّ النَّارُ، فَرَأَيْتُ فِيهَا ابْنَ قَمَعَةَ بْنِ خِنْدِفَ، وَهُوَ يَجُرُّ قُصْبَهُ فِي النَّارِ، وَهُوَ أَوَّلُ مَنْ سَيَّبَ السَّائِبَةَ، وَغَيَّرَ عَهْدَ إِبْرَاهِيمَ، وَأَشْبَهُ مَنْ رَأَيْتُ بِهِ أَكْثَمُ بْنُ الْجَوْنِ. قَالَ: فَقَالَ أَكْثَمُ: يَا رَسُولَ اللَّهِ أَيَضُرُّنِي شَبَهُهُ؟ قَالَ: لَا، إِنَّكَ مُسْلِمٌ وَهُوَ كَافِرٌ."],"takhrij":"حسن: رواه أبو يعلى (6121) عن أبي موسى (محمد بن المثنى)، حدثنا محمد بن عبدالله الأنصاري، حدثنا محمد بن عمرو، عن أبي سلمة، عن أبي هريرة فذكره.","grade":"حسن","chapter_ar":"باب رؤية النبي ﷺ عمرو بن عامر الخزاعي في النار وهو أول من سيب السوائب","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Yaʿlā (6121).","chapter_en":"The Prophet ﷺ Saw ʿAmr ibn ʿĀmir al-Khuzāʿī in the Fire; He Was the First to Set Free the Sāʾibah Animals","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل النار","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of the Fire","part_no":67,"group_no":4,"chapter_no":9,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “The Fire was shown to me, and in it I saw Ibn Qamaʿah ibn Khindif dragging his intestines in the Fire. He was the first to set free the sāʾibah animal and the one who altered the covenant and religion of Ibrāhīm. The person I have seen who most resembles him is Aktham ibn al-Jawn.” Aktham asked: “O Messenger of Allah, will my resemblance to him harm me?” He replied: “No. You are a Muslim, while he was a disbeliever.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو يعلى (6121)."},{"num":16494,"demo":false,"sanad":"","matn":["عَنْ قَيْسِ بْنِ عُبَادٍ، قَالَ: قُلْنَا لِعَمَّارٍ: أَرَأَيْتَ قِتَالَكُمْ، أَرَأْيًا رَأَيْتُمُوهُ؟ فَإِنَّ الرَّأْيَ يُخْطِئُ وَيُصِيبُ، أَوْ عَهْدًا عَهِدَهُ إِلَيْكُمْ رَسُولُ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؟ ؟ فَقَالَ: مَا عَهِدَ إِلَيْنَا رَسُولُ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  شَيْئًا لَمْ يَعْهَدْهُ إِلَى النَّاسِ كَافَّةً، وَقَالَ: إِنَّ رَسُولَ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  قَالَ: إِنَّ فِي أُمَّتِي. قَالَ شُعْبَةُ: وَأَحْسِبُهُ قَالَ: حَدَّثَنِي حُذَيْفَةُ. وَقَالَ غُنْدَرٌ: أُرَاهُ قَالَ: فِي أُمَّتِي اثْنَا عَشَرَ مُنَافِقًا، لَا يَدْخُلُونَ الْجَنَّةَ، وَلَا يَجِدُونَ رِيحَهَا، حَتَّى يَلِجَ الْجَمَلُ فِي سَمِّ الْخِيَاطِ، ثَمَانِيَةٌ مِنْهُمْ تَكْفِيكَهُمُ الدُّبَيْلَةُ، سِرَاجٌ مِنَ النَّارِ يَظْهَرُ فِي أَكْتَافِهِمْ، حَتَّى يَنْجُمَ مِنْ صُدُورِهِمْ."],"takhrij":"صحيح: رواه مسلم في صفات المنافقين (2779) من طرق عن محمد بن جعفر، حدثنا شعبة، عن قتادة، عن أبي نضرة، عن قيس بن عباد قال: فذكره.","grade":"صحيح","chapter_ar":"باب أن المنافقين في النار","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2779).","chapter_en":"The Hypocrites Will Be in the Fire","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل النار","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of the Fire","part_no":67,"group_no":4,"chapter_no":10,"content":{"translation":{"en":["Qays ibn ʿUbād narrated: We asked ʿAmmār: “Regarding your fighting, was it based on an opinion you formed? For opinion may be right or wrong. Or was it based on a covenant that the Messenger of Allah ﷺ specifically entrusted to you?” He replied: “The Messenger of Allah ﷺ did not entrust us with anything that he did not entrust to the people generally.” He then said that the Messenger of Allah ﷺ said: “Among my Ummah are twelve hypocrites who will neither enter Paradise nor smell its fragrance until a camel passes through the eye of a needle. For eight of them, al-Dubaylah itself will be sufficient: a blazing fire that will appear in their shoulders and emerge through their chests.”"]},"intro":{"ar":["قال الله تعالى:","﴿بَشِّرِ الْمُنَافِقِينَ بِأَنَّ لَهُمْ عَذَابًا أَلِيمًا﴾ [النساء: ١٣٨].","وقال:","﴿إِنَّ اللَّهَ جَامِعُ الْمُنَافِقِينَ وَالْكَافِرِينَ فِي جَهَنَّمَ جَمِيعًا﴾ [النساء: ١٤٠].","وقال تعالى:","﴿إِنَّ الْمُنَافِقِينَ فِي الدَّرْكِ الْأَسْفَلِ مِنَ النَّارِ﴾ [النساء: ١٤٥].","وقال تعالى:","﴿وَعَدَ اللَّهُ الْمُنَافِقِينَ وَالْمُنَافِقَاتِ وَالْكُفَّارَ نَارَ جَهَنَّمَ﴾ [التوبة: ٦٨]."],"en":["Allah, the Exalted, says:","“Give the hypocrites tidings that for them is a painful punishment.”","[al-Nisāʾ 4:138]","And He says:","“Indeed, Allah will gather the hypocrites and the disbelievers all together in Hell.”","[al-Nisāʾ 4:140]","And He, the Exalted, says:","“Indeed, the hypocrites will be in the lowest depths of the Fire.”","[al-Nisāʾ 4:145]","And He, the Exalted, says:","“Allah has promised the hypocrite men and hypocrite women, and the disbelievers, the Fire of Hell.”","[al-Tawbah 9:68]"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (2779)."},{"num":16495,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: بَيْنَا أَنَا قَائِمٌ إِذَا زُمْرَةٌ، حَتَّى إِذَا عَرَفْتُهُمْ خَرَجَ رَجُلٌ مِنْ بَيْنِي وَبَيْنِهِمْ، فَقَالَ: هَلُمَّ. فَقُلْتُ: أَيْنَ؟ قَالَ: إِلَى النَّارِ وَاللَّهِ. قُلْتُ: وَمَا شَأْنُهُمْ؟ قَالَ: إِنَّهُمُ ارْتَدُّوا بَعْدَكَ عَلَى أَدْبَارِهِمُ الْقَهْقَرَى. ثُمَّ إِذَا زُمْرَةٌ، حَتَّى إِذَا عَرَفْتُهُمْ خَرَجَ رَجُلٌ مِنْ بَيْنِي وَبَيْنِهِمْ، فَقَالَ: هَلُمَّ. قُلْتُ أَيْنَ؟ قَالَ: إِلَى النَّارِ وَاللَّهِ. قُلْتُ: مَا شَأْنُهُمْ؟ قَالَ: إِنَّهُمُ ارْتَدُّوا بَعْدَكَ عَلَى أَدْبَارِهِمُ الْقَهْقَرَى. فَلاَ أُرَاهُ يَخْلُصُ مِنْهُمْ إِلاَّ مِثْلُ هَمَلِ النَّعَمِ."],"takhrij":"صحيح: رواه البخاري في الرقاق (6587) عن إبراهيم بن المنذر الحزامي، حدثنا محمد بن فليح، حدثنا أبي، قال: حدثني هلال بن علي، عن عطاء بن يسار، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب ذهاب المرتدين إلى النار","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (6587).","chapter_en":"The Apostates Will Be Taken to the Fire","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل النار","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of the Fire","part_no":67,"group_no":4,"chapter_no":11,"content":{"translation":{"en":["Abū Hurayrah narrated that the Prophet ﷺ said: “While I am standing, a group will appear. When I recognize them, a man will come out from between me and them and say: ‘Come!’ I will ask: ‘Where?’ He will say: ‘To the Fire, by Allah.’ I will ask: ‘What is the matter with them?’ He will say: ‘They turned back on their heels after you.’ Then another group will appear. When I recognize them, a man will come out from between me and them and say: ‘Come!’ I will ask: ‘Where?’ He will say: ‘To the Fire, by Allah.’ I will ask: ‘What is the matter with them?’ He will say: ‘They turned back on their heels after you.’ I do not think that any of them will escape except as few as stray camels.”"]}},"tuhfa":{},"full":1,"rep":[818],"tks":"صحيح: رواه البخاري (6587)."},{"num":16496,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ، رَضِيَ اللَّهُ عَنْهُمَا أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، قَالَ: عُذِّبَتِ امْرَأَةٌ فِي هِرَّةٍ سَجَنَتْهَا حَتَّى مَاتَتْ، فَدَخَلَتْ فِيهَا النَّارَ، لاَ هِيَ أَطْعَمَتْهَا وَلاَ سَقَتْهَا إِذْ حَبَسَتْهَا، وَلاَ هِيَ تَرَكَتْهَا تَأْكُلُ مِنْ خَشَاشِ الأَرْضِ."],"takhrij":"متفق عليه: رواه البخاري في الأنبياء (3482)، ومسلم في السلام (2242) كلاهما عن عبد الله بن محمد بن أسماء، حدثنا جويرية بن أسماء، عن نافع، عن عبدالله بن عمر فذكره.","grade":"متفق عليه","chapter_ar":"باب أن امرأة دخلت النار في هرة","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (3482) and Muslim (2242).","chapter_en":"A Woman Entered the Fire Because of a Cat","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل النار","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of the Fire","part_no":67,"group_no":4,"chapter_no":12,"content":{"translation":{"en":["ʿAbdullāh ibn ʿUmar narrated that the Messenger of Allah ﷺ said: “A woman was punished because of a cat that she imprisoned until it died, and because of it she entered the Fire. She neither fed it nor gave it water while she kept it confined, nor did she release it to eat from the creatures of the earth.”"]}},"tuhfa":{},"full":1,"rep":[13924,14816],"tks":"متفق عليه: رواه البخاري (3482)، ومسلم (2242)."},{"num":16497,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: دَخَلَتِ امْرَأَةٌ النَّارَ فِي هِرَّةٍ رَبَطَتْهَا، فَلَا هِيَ أَطْعَمَتْهَا، وَلَا هِيَ أَرْسَلَتْهَا تَأْكُلُ مِنْ خَشَاشِ الْأَرْضِ، حَتَّى مَاتَتْ هَزْلًا.","قَالَ الزُّهْرِيُّ: ذَلِكَ، لِئَلَّا يَتَّكِلَ رَجُلٌ، وَلَا يَيْأَسَ رَجُلٌ."],"takhrij":"صحيح: رواه مسلم في التوبة (2619) من طرق عن عبد الرزاق، أخبرنا معمر، قال الزهري، حدثني حميد بن عبد الرحمن، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب أن امرأة دخلت النار في هرة","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2619).","chapter_en":"A Woman Entered the Fire Because of a Cat","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل النار","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of the Fire","part_no":67,"group_no":4,"chapter_no":12,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “A woman entered the Fire because of a cat that she tied up. She neither fed it nor released it to eat from the creatures of the earth, until it died from emaciation.” Al-Zuhrī said: “This is so that no person becomes complacent, and no person falls into despair.”"]}},"tuhfa":{},"full":1,"rep":[8308],"tks":"صحيح: رواه مسلم (2619)."},{"num":16498,"demo":false,"sanad":"","matn":["عَنْ جابر بْنِ عَبْدِ اللَّهِ، قَالَ: كَسَفَتِ الشَّمْسُ عَلَى عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي يَوْمٍ شَدِيدِ الْحَرِّ، فَصَلَّى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِأَصْحَابِهِ، وَفِيهِ: ثُمَّ قَالَ: إِنَّهُ عُرِضَ عَلَيَّ كُلُّ شَيْءٍ تُولَجُونَهُ، فَعُرِضَتْ عَلَيَّ الْجَنَّةُ، حَتَّى لَوْ تَنَاوَلْتُ مِنْهَا قِطْفًا أَخَذْتُهُ - أَوْ قَالَ: تَنَاوَلْتُ مِنْهَا قِطْفًا - فَقَصُرَتْ يَدِي عَنْهُ، وَعُرِضَتْ عَلَيَّ النَّارُ، فَرَأَيْتُ فِيهَا امْرَأَةً مِنْ بَنِي إِسْرَائِيلَ تُعَذَّبُ فِي هِرَّةٍ لَهَا، رَبَطَتْهَا فَلَمْ تُطْعِمْهَا، وَلَمْ تَدَعْهَا تَأْكُلُ مِنْ خَشَاشِ الْأَرْضِ، وَرَأَيْتُ أَبَا ثُمَامَةَ عَمْرَو بْنَ مَالِكٍ يَجُرُّ قُصْبَهُ فِي النَّارِ... الحديث."],"takhrij":"صحيح: رواه مسلم في الكسوف (904: 9) عن يعقوب بن إبراهيم الدورقي، حدثنا إسماعيل ابن علية، عن هشام الدستوائي، قال: حدثنا أبو الزبير، عن جابر بن عبد الله قال: فذكره.","grade":"صحيح","chapter_ar":"باب أن امرأة دخلت النار في هرة","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (9 :904).","chapter_en":"A Woman Entered the Fire Because of a Cat","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل النار","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of the Fire","part_no":67,"group_no":4,"chapter_no":12,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh narrated: The sun was eclipsed during the lifetime of the Messenger of Allah ﷺ on an intensely hot day, and the Messenger of Allah ﷺ led his Companions in prayer. In the hadith, he later said: “Everything that you will enter was shown to me. Paradise was shown to me, to the point that if I had reached for one of its clusters, I would have taken it—or he said: I reached for one of its clusters, but my hand fell short of it. The Fire was also shown to me, and I saw in it a woman from the Children of Israel being punished because of a cat she owned. She had tied it up, neither feeding it nor allowing it to eat from the creatures of the earth. And I saw Abū Thumāmah, ʿAmr ibn Mālik, dragging his intestines in the Fire…” The hadith continues."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (904: 9)."},{"num":16499,"demo":false,"sanad":"","matn":["عَنْ جابر بْنِ عَبْدِ اللَّهِ قَالَ: انكسفت الشَّمْسُ فِي عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَوْمَ مَاتَ إِبْرَاهِيمُ ابْنُ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَذَكَرَ الْحَدِيثَ، وَفِيهِ: مَا مِنْ شَيْءٍ تُوعَدُونَهُ إِلَّا قَدْ رَأَيْتُهُ فِي صَلَاتِي هَذِهِ، لَقَدْ جِيءَ بِالنَّارِ، وَذَلِكُمْ حِينَ رَأَيْتُمُونِي تَأَخَّرْتُ، مَخَافَةَ أَنْ يُصِيبَنِي مِنْ لَفْحِهَا، وَحَتَّى رَأَيْتُ فِيهَا صَاحِبَ الْمِحْجَنِ يَجُرُّ قُصْبَهُ فِي النَّارِ، كَانَ يَسْرِقُ الْحَاجَّ بِمِحْجَنِهِ، فإنْ فطنَ لَهُ قَالَ: إِنَّمَا تَعَلَّقَ بِمِحْجَنِي، وَإِنْ غُفِلَ عَنْهُ ذَهَبَ بِهِ، وَحَتَّى رَأَيْتُ فِيهَا صَاحِبَةَ الْهِرَّةِ الَّتِي رَبَطَتْهَا فَلَمْ تُطْعِمْهَا، وَلَمْ تَدَعْهَا تَأْكُلُ مِنْ خَشَاشِ الْأَرْضِ، حَتَّى مَاتَتْ جُوعًا، ثُمَّ جِيءَ بِالْجَنَّةِ، وَذَلِكُمْ حِينَ رَأَيْتُمُونِي تَقَدَّمْتُ حَتَّى قُمْتُ فِي مَقَامِي، وَلَقَدْ مَدَدْتُ يَدِي وَأَنَا أُرِيدُ أَنْ أَتَنَاوَلَ مِنْ ثَمَرِهَا لِتَنْظُرُوا إِلَيْهِ، ثُمَّ بَدَا لِي أَنْ لَا أَفْعَلَ، فَمَا مِنْ شَيْءٍ تُوعَدُونَهُ إِلَّا قَدْ رَأَيْتُهُ فِي صَلَاتِي هَذِهِ."],"takhrij":"صحيح: رواه مسلم في الكسوف (904: 10) من طرق عن عبد الله بن نمير، حدثنا عبدالملك، عن عطاء، عن جابر قال: فذكره.","grade":"صحيح","chapter_ar":"باب أن امرأة دخلت النار في هرة","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (10 :904).","chapter_en":"A Woman Entered the Fire Because of a Cat","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل النار","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of the Fire","part_no":67,"group_no":4,"chapter_no":12,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh narrated: The sun was eclipsed during the lifetime of the Messenger of Allah ﷺ on the day his son Ibrāhīm died. In the hadith, he said: “There is nothing you have been promised except that I saw it during this prayer. The Fire was brought before me. That was when you saw me step backward, fearing that some of its scorching heat might reach me. I saw in it the man with the hooked staff dragging his intestines in the Fire. He used to steal from the pilgrims with his hooked staff. If he was noticed, he would say: ‘It merely became caught on my staff,’ but if the person did not notice, he would take it away. I also saw in it the woman with the cat, who tied it up, neither feeding it nor allowing it to eat from the creatures of the earth, until it died of hunger. Then Paradise was brought before me. That was when you saw me move forward until I stood in my place. I stretched out my hand intending to take some of its fruit so that you could look at it, but then it occurred to me not to do so. There is nothing you have been promised except that I saw it during this prayer.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (904: 10)."},{"num":16500,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بن عمرو قَالَ: انْكَسَفَتِ الشَّمْسُ عَلَى عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ -فَذَكَرَ الْحَدِيثَ- ثُمَّ قَالَ: لَقَدْ عُرِضَتْ عَلَيَّ الْجَنَّةُ حَتَّى لَوْ شِئْتُ لَتَعَاطَيْتُ قِطْفًا مِنْ قُطُوفِهَا، وَعُرِضَتْ عَلَيَّ النَّارُ حَتَّى جَعَلْتُ أَتَّقِيهَا حَتَّى خَشِيتُ أَنْ تَغْشَاكُمْ، فَجَعَلْتُ أَقُولُ: أَلَمْ تَعِدْنِي أَنْ لَا تُعَذِّبَهُمْ وَأَنَا فِيهِمْ، رَبِّ أَلَمْ تَعِدْنِي أَنْ لَا تُعَذِّبَهُمْ وَهُمْ يَسْتَغْفِرُونَكَ. قَالَ: فَرَأَيْتُ فِيهَا الْحِمْيَرِيَّةَ السَّوْدَاءَ صَاحِبَةَ الْهِرَّةِ، كَانَتْ حَبَسَتْهَا، فَلَمْ تُطْعِمْهَا وَلَمْ تَسْقِهَا، وَلَمْ تَتْرُكْهَا تَأْكُلُ مِنْ خَشَاشِ الأَرْضِ، فَرَأَيْتُهَا كُلَّمَا أَدْبَرَتْ نُهِشَتْ فِي النَّارِ. وَرَأَيْتُ فِيهَا صَاحِبَ بَدَنَتَيْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَخَا دَعْدَعٍ، يُدْفَعُ فِي النَّارِ بقضيبين ذِي شُعْبَتَيْنِ. وَرَأَيْتُ صَاحِبَ الْمِحْجَنِ، فَرَأَيْتُهُ فِي النَّارِ عَلَى مِحْجَنِهِ متوكئا."],"takhrij":"صحيح: رواه أبو داود (1194) من طريق حماد-، ورواه النسائي (1482) من طريق عبد العزيز بن عبد الصمد-، ورواه أحمد (6483، 6763) من طريق محمد بن فضيل وشعبة-، ورواه ابن خزيمة (1393)، والحاكم (1/329) من طريق سفيان الثوري-، ورواه ابن خزيمة (1392)، وابن حبان (2838) من طريق جرير- كلهم عن عطاء بن السائب، عن أبيه، عن عبد الله بن عمرو قال: فذكره. واللفظ لابن حبان.","grade":"صحيح","chapter_ar":"باب أن امرأة دخلت النار في هرة","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (1194), al-Nasā’ī (1482), Aḥmad (6483, 6763), Ibn Khuzaymah (1393), al-Ḥākim (1/329), Ibn Khuzaymah (1392), and Ibn Ḥibbān (2838), whose wording this is.","chapter_en":"A Woman Entered the Fire Because of a Cat","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل النار","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of the Fire","part_no":67,"group_no":4,"chapter_no":12,"content":{"translation":{"en":["ʿAbdullāh ibn ʿAmr narrated: The sun was eclipsed during the lifetime of the Messenger of Allah ﷺ. He then mentioned the hadith and said: “Paradise was shown to me, to the point that, had I wished, I could have reached for one of its clusters. The Fire was also shown to me, and I kept trying to shield myself from it until I feared that it might engulf you. I began saying: ‘Did You not promise me that You would not punish them while I am among them? My Lord, did You not promise me that You would not punish them while they seek Your forgiveness?’” He continued: “I saw in it the black Ḥimyarī woman who owned the cat. She had imprisoned it, neither feeding it nor giving it drink, nor allowing it to eat from the creatures of the earth. I saw that whenever she turned away, it would tear at her in the Fire. I saw in it the man responsible for the sacrificial camels of the Messenger of Allah ﷺ, the brother of Daʿdaʿ, being driven in the Fire with two forked rods. And I saw the man with the hooked staff; I saw him in the Fire leaning upon his hooked staff.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (1194)، والنسائي (1482)، وأحمد (6483، 6763)، وابن خزيمة (1393)، والحاكم (1/329)، وابن خزيمة (1392)، وابن حبان (2838). واللفظ له."},{"num":16501,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، قَالَ: قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أُرِيتُ النَّارَ فَإِذَا أَكْثَرُ أَهْلِهَا النِّسَاءُ، يَكْفُرْنَ. قِيلَ: أَيَكْفُرْنَ بِاللَّهِ؟ قَالَ: يَكْفُرْنَ الْعَشِيرَ، وَيَكْفُرْنَ الإِحْسَانَ، لَوْ أَحْسَنْتَ إِلَى إِحْدَاهُنَّ الدَّهْرَ، ثُمَّ رَأَتْ مِنْكَ شَيْئًا، قَالَتْ: مَا رَأَيْتُ مِنْكَ خَيْرًا قَطُّ."],"takhrij":"متفق عليه: رواه مالك في الكسوف (2) عن زيد بن أسلم، عن عطاء بن يسار، عن عبد الله بن عباس فذكره مطولا.","grade":"متفق عليه","chapter_ar":"باب أكثر أهل النار النساء","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Agreed upon: Narrated by Mālik in al-Kusūf (2), al-Bukhārī (1052), and Muslim (907).","chapter_en":"Most of the People of the Fire Are Women","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل النار","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of the Fire","part_no":67,"group_no":4,"chapter_no":13,"content":{"translation":{"en":["Ibn ʿAbbās narrated that the Prophet ﷺ said: “I was shown the Fire, and I saw that most of its inhabitants were women because they are ungrateful.” It was asked: “Do they disbelieve in Allah?” He replied: “They are ungrateful to their husbands and ungrateful for kindness. If you were good to one of them throughout an entire lifetime, then she saw something from you that displeased her, she might say: ‘I have never seen any good from you at all.’”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (2) والبخاري (1052)، ومسلم (907)."},{"num":16502,"demo":false,"sanad":"","matn":["عَنْ زَيْنَبَ، امْرَأَةِ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ قَالَتْ: خَطَبَنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: يَا مَعْشَرَ النِّسَاءِ تَصَدَّقْنَ، وَلَوْ مِنْ حُلِيِّكُنَّ؛ فَإِنَّكُنَّ أَكْثَرُ أَهْلِ جَهَنَّمَ يَوْمَ الْقِيَامَةِ."],"takhrij":"متفق عليه: رواه الترمذي (635)، وابن ماجه (1834)، وأحمد (27048)، وصحّحه ابن حبان (4248) كلهم من طريق أبي معاوية محمد بن خازم، حدثنا الأعمش، عن شقيق، عن عمرو بن الحارث بن المصطلق، عن ابن أخي زينب امرأة عبد الله، عن زينب فذكر الحديث. واللفظ للترمذي، ولم يذكر هذا اللفظ ابن ماجه.","grade":"متفق عليه","chapter_ar":"باب أكثر أهل النار النساء","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (1466) and Muslim (1000). It was also narrated by al-Tirmidhī (635), Ibn Mājah (1834), Aḥmad (27048), and authenticated by Ibn Ḥibbān (4248).","chapter_en":"Most of the People of the Fire Are Women","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل النار","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of the Fire","part_no":67,"group_no":4,"chapter_no":13,"content":{"translation":{"en":["Zaynab, the wife of ʿAbdullāh ibn Masʿūd, narrated: The Messenger of Allah ﷺ addressed us and said: “O women, give in charity, even from your jewelry, for you will be the majority of the people of Hell on the Day of Resurrection.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (1466)، ومسلم (1000)، ورواه الترمذي (635)، وابن ماجه (1834)، وأحمد (27048)، وصححه ابن حبان (4248)."},{"num":16503,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ، قَالَ: خَرَجَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي أَضْحًى ـ أَوْ فِطْرٍ ـ إِلَى الْمُصَلَّى، فَمَرَّ عَلَى النِّسَاءِ، فَقَالَ: يَا مَعْشَرَ النِّسَاءِ تَصَدَّقْنَ، فَإِنِّي أُرِيتُكُنَّ أَكْثَرَ أَهْلِ النَّارِ. فَقُلْنَ: وَبِمَ يَا رَسُولَ اللَّهِ؟ قَالَ: تُكْثِرْنَ اللَّعْنَ، وَتَكْفُرْنَ الْعَشِيرَ، مَا."],"takhrij":"متفق عليه: رواه البخاريّ في الحيض (304)، ومسلم في الإيمان (80) كلاهما من طريق سعيد بن أبي مريم، أخبرنا محمد بن جعفر، قال: أخبرني زيد - وهو ابن أسلم -، عن عياض بن عبدالله، عن أبي سعيد الخدريّ، فذكره. واللفظ للبخاري، ولم يسق مسلم لفظه بهذا الإسناد، وإنما أحال على حديث آخر.","grade":"متفق عليه","chapter_ar":"باب أكثر أهل النار النساء","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (304) and Muslim (80).","chapter_en":"Most of the People of the Fire Are Women","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل النار","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of the Fire","part_no":67,"group_no":4,"chapter_no":13,"content":{"translation":{"en":["Abū Saʿīd al-Khudrī narrated: The Messenger of Allah ﷺ went out to the prayer place on the day of al-Aḍḥā or al-Fiṭr. He passed by the women and said: “O women, give in charity, for I was shown that you are the majority of the people of the Fire.” They asked: “Why is that, O Messenger of Allah?” He replied: “You frequently curse and are ungrateful to your husbands…” The hadith continues."]}},"tuhfa":{},"full":1,"rep":[6339],"tks":"متفق عليه: رواه البخاري (304)، ومسلم (80)."},{"num":16504,"demo":false,"sanad":"","matn":["عَنْ عبدالله بن عُمَرَ، عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ قَالَ: يَا مَعْشَرَ النِّسَاءِ تَصَدَّقْنَ، وَأَكْثِرْنَ الِاسْتِغْفَارَ، فَإِنِّي رَأَيْتُكُنَّ أَكْثَرَ أَهْلِ النَّارِ فَقَالَتِ امْرَأَةٌ مِنْهُنَّ جَزْلَةٌ: وَمَا لَنَا يَا رَسُولَ اللَّهِ أَكْثَرَ أَهْلِ النَّارِ؟ قَالَ: تُكْثِرْنَ اللَّعْنَ، وَتَكْفُرْنَ الْعَشِيرَ.... الحديث."],"takhrij":"صحيح: رواه مسلم في الإيمان (79) عن محمد بن رمح، أخبرنا اللّيث، عن ابن الهاد، عن عبدالله بن دينار، عن عبدالله بن عمر، فذكره في حديث طويل.","grade":"صحيح","chapter_ar":"باب أكثر أهل النار النساء","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (79).","chapter_en":"Most of the People of the Fire Are Women","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل النار","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of the Fire","part_no":67,"group_no":4,"chapter_no":13,"content":{"translation":{"en":["ʿAbdullāh ibn ʿUmar narrated that the Messenger of Allah ﷺ said: “O women, give in charity and frequently seek forgiveness, for I have seen that you are the majority of the people of the Fire.” An intelligent woman among them asked: “Why is it, O Messenger of Allah, that we are the majority of the people of the Fire?” He replied: “You frequently curse and are ungrateful to your husbands…” The hadith continues."]}},"tuhfa":{},"full":1,"rep":[6341],"tks":"صحيح: رواه مسلم (79)."},{"num":16505,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ. قَالَ:  شَهِدْتُ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الصَّلَاةَ يَوْمَ الْعِيدِ. فَبَدَأَ بِالصَّلَاةِ قَبْلَ الْخُطْبَةِ. بِغَيْرِ أَذَانٍ وَلَا إِقَامَةٍ. ثُمَّ قَامَ مُتَوَكِّئًا عَلَى بِلَالٍ. فَأَمَرَ بِتَقْوَى اللَّهِ. وَحَثَّ عَلَى طَاعَتِهِ. وَوَعَظَ النَّاسَ. وَذَكَّرَهُمْ. ثُمَّ مَضَى. حَتَّى أَتَى النِّسَاءَ. فَوَعَظَهُنَّ وَذَكَّرَهُنَّ. فَقَالَ: تَصَدَّقْنَ. فَإِنَّ أَكْثَرَكُنَّ حَطَبُ جَهَنَّمَ، فَقَامَتِ امْرَأَةٌ مِنْ سِطَةِ النِّسَاءِ سَفْعَاءُ الْخَدَّيْنِ. فَقَالَتْ: لِمَ؟ يَا رَسُولَ اللَّهِ! قَالَ: لِأَنَّكُنَّ تُكْثِرْنَ الشَّكَاةَ. وَتَكْفُرْنَ الْعَشِيرَ."],"takhrij":"صحيح: رواه مسلم في صلاة العيدين (885: 4) عن محمد بن عبد الله بن نمير، حدثنا أبي، حدثنا عبد الملك بن أبي سليمان، عن عطاء، عن جابر بن عبدالله فذكره.","grade":"صحيح","chapter_ar":"باب أكثر أهل النار النساء","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (4 :885).","chapter_en":"Most of the People of the Fire Are Women","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل النار","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of the Fire","part_no":67,"group_no":4,"chapter_no":13,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh narrated: I attended the Eid prayer with the Messenger of Allah ﷺ. He began with the prayer before the sermon, without adhān or iqāmah. Then he stood leaning upon Bilāl, commanded the people to fear Allah, encouraged them to obey Him, admonished them, and reminded them. Then he went to the women, admonished and reminded them, and said: “Give in charity, for most of you will be fuel for Hell.” A woman from among the ordinary women, whose cheeks were darkened, stood and asked: “Why, O Messenger of Allah?” He replied: “Because you frequently complain and are ungrateful to your husbands.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (885: 4)."},{"num":16506,"demo":false,"sanad":"","matn":["عَنْ ابْنِ مَسْعُودٍ، أَنَّ رَسُولَ اللَّهِ  قَالَ: تَصَدَّقْنَ يَا مَعْشَرَ النِّسَاءِ، وَلَوْ مِنْ حليِّكُن، فَإِنَّكُنَّ أَكْثَرُ أَهْلِ النَّارِ، فَقَامَتِ امْرَأَةٌ لَيْسَتْ مِن عِلْيَةِ النِّسَاءِ، فَقَالَتْ: لِمَ يَا رَسُولَ اللَّهِ؟ قَالَ: لأنكنَّ تُكثِرْن اللَّعْنَ، وَتَكْفُرْنَ الْعَشِيرَ.","وفي رواية: وما رأيتُ ناقصات عقل ودين أغلب للب الرجال مِنكُن."],"takhrij":"حسن: رواه أحمد (3569، 4152)، وأبو يعلى (5112، 5144)، والحاكم (2/190)، كلهم من طريق منصور بن أبي الأسود، عن ذر، عن وائل بن مهانة، عن عبدالله بن مسعود، فذكر الحديث.","grade":"حسن","chapter_ar":"باب أكثر أهل النار النساء","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (4152, 3569), Abū Yaʿlā (5144, 5112), and al-Ḥākim (2/190).","chapter_en":"Most of the People of the Fire Are Women","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل النار","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of the Fire","part_no":67,"group_no":4,"chapter_no":13,"content":{"translation":{"en":["Ibn Masʿūd narrated that the Messenger of Allah ﷺ said: “O women, give in charity, even from your jewelry, for you are the majority of the people of the Fire.” A woman who was not from among the prominent women stood and asked: “Why, O Messenger of Allah?” He replied: “Because you frequently curse and are ungrateful to your husbands.” In another narration: “I have not seen anyone deficient in reason and religion more capable of overcoming the mind of a resolute man than you.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (4152، 3569)، وأبو يعلى (5144، 5112)، والحاكم (2/190)."},{"num":16507,"demo":false,"sanad":"","matn":["عن عَبْدِ الرَّحْمَنِ بن شِبْلٍ قَالَ: قَالَ: وَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّ الْفُسَّاقَ هُمْ أَهْلُ النَّارِ. قِيلَ: يَا رَسُولَ اللَّهِ، وَمَنِ الْفُسَّاقُ؟ قَالَ: النِّسَاءُ. قَالَ: رَجُلٌ: يَا رَسُولَ اللَّهِ، أَوَلَسْنَ أُمَّهَاتِنَا، وَأَخَوَاتِنَا، وَأَزْوَاجَنَا؟ قَالَ: بَلَى، وَلَكِنَّهُمْ إِذَا أُعْطِينَ لَمْ يَشْكُرْنَ، وَإِذَا ابْتُلِينَ لَمْ يَصْبِرْنَ."],"takhrij":"حسن: رواه أحمد (15531)، والحاكم (8787) كلاهما من طريق هشام الدستوائي، قال: حدثني يحيى بن أبي كثير، عن أبي راشد الحبراني، قال: قال عبدالرحمن بن شبل فذكره.","grade":"حسن","chapter_ar":"باب أكثر أهل النار النساء","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (15531) and al-Ḥākim (4/604).","chapter_en":"Most of the People of the Fire Are Women","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل النار","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of the Fire","part_no":67,"group_no":4,"chapter_no":13,"content":{"translation":{"en":["ʿAbd al-Raḥmān ibn Shibl narrated that the Messenger of Allah ﷺ said: “Indeed, the defiantly disobedient are the people of the Fire.” It was asked: “O Messenger of Allah, who are the defiantly disobedient?” He replied: “Women.” A man asked: “O Messenger of Allah, are they not our mothers, sisters, and wives?” He replied: “Yes. But when they are given something, they are not grateful, and when they are tested, they are not patient.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (15531)، والحاكم (8787)."},{"num":16508,"demo":false,"sanad":"","matn":["عَنْ أَبِي مُوسَى قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:  إِذَا كَانَ يَوْمُ الْقِيَامَةِ دَفَعَ اللهُ عَزَّ وَجَلَّ إِلَى كُلِّ مُسْلِمٍ يَهُودِيًّا أَوْ نَصْرَانِيًّا، فَيَقُولُ: هَذَا فَِكَاكُكَ مِنَ النَّارِ."],"takhrij":"صحيح: رواه مسلم في التوبة (2767) عن أبي بكر بن أبي شيبة، حدثنا أبو أسامة، عن طلحة بن يحيى، عن أبي بردة، عن أبي موسى فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في فكاك المسلم من الكفار","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2767).","chapter_en":"What Has Been Narrated Concerning the Muslim’s Ransom from among the Disbelievers","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل النار","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of the Fire","part_no":67,"group_no":4,"chapter_no":14,"content":{"translation":{"en":["Abū Mūsā al-Ashʿarī narrated that the Messenger of Allah ﷺ said: “On the Day of Resurrection, Allah, Mighty and Majestic, will assign to every Muslim a Jew or a Christian and will say: ‘This is your ransom from the Fire.’”"]},"buhuth":{"en":["Regarding the phrase “your ransom from the Fire,” the author explains:","You were exposed to the possibility of entering the Fire, but because you chose Islam, Allah placed in the Fire in your stead a Jew or a Christian—and the generality of disbelievers is included with them—so that became his ransom from the Fire."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (2767)."},{"num":16509,"demo":false,"sanad":"","matn":["عَنْ أَبِي مُوسَى الأشعري، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لَا يَمُوتُ رَجُلٌ مُسْلِمٌ إِلَّا أَدْخَلَ اللَّهُ مَكَانَهُ النَّارَ، يَهُودِيًّا أَوْ نَصْرَانِيًّا."],"takhrij":"صحيح: رواه مسلم في التوبة (2767: 50) عن أبي بكر بن أبي شيبة، حدثنا عفان بن مسلم، حدثنا همام، حدثنا قتادة، أن عونا، وسعيد بن أبي بردة، حدثاه أنهما شهدا أبا بردة يحدث عمر بن عبد العزيز، عن أبيه أبي موسى فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في فكاك المسلم من الكفار","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (50 :2767).","chapter_en":"What Has Been Narrated Concerning the Muslim’s Ransom from among the Disbelievers","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل النار","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of the Fire","part_no":67,"group_no":4,"chapter_no":14,"content":{"translation":{"en":["Abū Mūsā al-Ashʿarī narrated that the Prophet ﷺ said: “No Muslim man dies except that Allah admits into the Fire in his place a Jew or a Christian.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (2767: 50)."},{"num":16510,"demo":false,"sanad":"","matn":["عَنْ أَبِي مُوسَى، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: يَجِيءُ يَوْمَ الْقِيَامَةِ نَاسٌ مِنَ الْمُسْلِمِينَ بِذُنُوبٍ أَمْثَالِ الْجِبَالِ، فَيَغْفِرُهَا اللهُ لَهُمْ وَيَضَعُهَا عَلَى الْيَهُودِ وَالنَّصَارَى."],"takhrij":"صحيح: رواه مسلم في التوبة (2767: 51) عن محمد بن عمرو بن عباد بن جبلة بن أبي رواد، حدثنا حرمي بن عمارة، حدثنا شداد أبو طلحة الراسبي، عن غيلان بن جرير، عن أبي بردة، عن أبيه فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في فكاك المسلم من الكفار","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (51 :2767).","chapter_en":"What Has Been Narrated Concerning the Muslim’s Ransom from among the Disbelievers","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل النار","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of the Fire","part_no":67,"group_no":4,"chapter_no":14,"content":{"translation":{"en":["Abū Mūsā narrated that the Prophet ﷺ said: “On the Day of Resurrection, some Muslims will come with sins like mountains. Allah will forgive them and place them upon the Jews and Christians.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (2767: 51)."},{"num":16511,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَا مِنْكُمْ مِنْ أَحَدٍ إِلاَّ لَهُ مَنْزِلاَنِ: مَنْزِلٌ فِي الْجَنَّةِ وَمَنْزِلٌ فِي النَّارِ. فَإِذَا مَاتَ فَدَخَلَ النَّارَ وَرِثَ أَهْلُ الْجَنَّةِ مَنْزِلَهُ. فَذَلِكَ قَوْلُهُ تَعَالَى: {أُولَئِكَ هُمُ الْوَارِثُونَ }."],"takhrij":"صحيح: رواه ابن ماجه (4341)، والبيهقي في الشعب (373)، وابن أبي حاتم كما ذكر ابن كثير في تفسيره (5/464) كلهم من طريق أبي معاوية، عن الأعمش، عن أبي صالح، عن أبي هريرة فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب ما جاء في فكاك المسلم من الكفار","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by Ibn Mājah (4341), al-Bayhaqī in al-Shuʿab (373), and Ibn Abī Ḥātim, as cited by Ibn Kathīr in his Tafsīr (5/464).","chapter_en":"What Has Been Narrated Concerning the Muslim’s Ransom from among the Disbelievers","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل النار","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of the Fire","part_no":67,"group_no":4,"chapter_no":14,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “There is none among you except that he has two dwellings: a dwelling in Paradise and a dwelling in the Fire. If he dies and enters the Fire, the people of Paradise will inherit his dwelling. That is the meaning of the statement of Allah, the Exalted: ‘Those are the inheritors.’ [al-Muʾminūn 23:10]”"]}},"tuhfa":{},"full":1,"rep":[12818,13247],"tks":"صحيح: رواه ابن ماجه (4341)، والبيهقي في الشعب (373)، وابن أبي حاتم كما ذكر ابن كثير في تفسيره (5/464)."},{"num":16512,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:  لَوْ يَعْلَمُ الْمُؤْمِنُ مَا عِنْدَ اللَّهِ مِنَ الْعُقُوبَةِ، مَا طَمِعَ بِجَنَّتِهِ أَحَدٌ، وَلَوْ يَعْلَمُ الْكَافِرُ مَا عِنْدَ اللَّهِ مِنَ الرَّحْمَةِ، مَا قَنَِطَ مِنْ جَنَّتِهِ أَحَدٌ."],"takhrij":"صحيح: رواه مسلم في التوبة (2755) من طرق عن إسماعيل بن جعفر، أخبرني العلاء (هو ابن عبدالرحمن بن يعقوب) ، عن أبيه، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في شدة عقوبة الله وسعة رحمته","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2755).","chapter_en":"What Has Been Narrated Concerning the Severity of Allah’s Punishment and the Vastness of His Mercy","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة الجنة والنار معًا","group_en":"A Collection of What Has Been Narrated Concerning the Description of Paradise and the Fire Together","part_no":67,"group_no":5,"chapter_no":1,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “If the believer knew the full extent of the punishment with Allah, no one would hope for His Paradise. And if the disbeliever knew the full extent of the mercy with Allah, no one would despair of His Paradise.”"]}},"tuhfa":{},"full":1,"rep":[11403],"tks":"صحيح: رواه مسلم (2755)."},{"num":16513,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:  حُفَّتِ الْجَنَّةُ بِالْمَكَارِهِ، وَحُفَّتِ النَّارُ بِالشَّهَوَاتِ."],"takhrij":"صحيح: رواه مسلم في الجنة وصفة نعيمها (2822) عن عبد الله بن مسلمة بن قعنب، حدثنا حماد بن سلمة، عن ثابت وحميد، عن أنس بن مالك فذكره.","grade":"صحيح","chapter_ar":"باب حفت الجنة بالمكاره وحفت النار بالشهوات","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2822).","chapter_en":"Paradise Is Surrounded by Hardships and the Fire Is Surrounded by Desires","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة الجنة والنار معًا","group_en":"A Collection of What Has Been Narrated Concerning the Description of Paradise and the Fire Together","part_no":67,"group_no":5,"chapter_no":2,"content":{"translation":{"en":["Anas ibn Mālik narrated that the Messenger of Allah ﷺ said: “Paradise is surrounded by hardships, and the Fire is surrounded by desires.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (2822)."},{"num":16514,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: حُجِبَتِ النَّارُ بِالشَّهَوَاتِ، وَحُجِبَتِ الْجَنَّةُ بِالْمَكَارِهِ."],"takhrij":"متفق عليه: رواه البخاري في الرقاق (6487)، ومسلم في الجنة (2823) كلاهما من طريق أبي الزناد، عن الأعرج، عن أبي هريرة فذكره.","grade":"متفق عليه","chapter_ar":"باب حفت الجنة بالمكاره وحفت النار بالشهوات","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6487) and Muslim (2823).","chapter_en":"Paradise Is Surrounded by Hardships and the Fire Is Surrounded by Desires","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة الجنة والنار معًا","group_en":"A Collection of What Has Been Narrated Concerning the Description of Paradise and the Fire Together","part_no":67,"group_no":5,"chapter_no":2,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “The Fire has been veiled by desires, and Paradise has been veiled by hardships.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (6487)، ومسلم (2823)."},{"num":16515,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لَمَّا خَلَقَ اللَّهُ الْجَنَّةَ وَالنَّارَ أَرْسَلَ جِبْرِيلَ إِلَى الْجَنَّةِ، فَقَالَ: انْظُرْ إِلَيْهَا، وَإِلَى مَا أَعْدَدْتُ لأَهْلِهَا فِيهَا قَالَ: فَجَاءَهَا، وَنَظَرَ إِلَيْهَا وَإِلَى مَا أَعَدَّ اللَّهُ لأَهْلِهَا فِيهَا، قَالَ: فَرَجَعَ إِلَيْهِ قَالَ: فَوَعِزَّتِكَ لاَ يَسْمَعُ بِهَا أَحَدٌ إِلاَّ دَخَلَهَا. فَأَمَرَ بِهَا، فَحُفَّتْ بِالْمَكَارِهِ، فَقَالَ: ارْجِعْ إِلَيْهَا فَانْظُرْ إِلَى مَا أَعْدَدْتُ لأَهْلِهَا فِيهَا قَالَ: فَرَجَعَ إِلَيْهَا فَإِذَا هِيَ قَدْ حُفَّتْ بِالْمَكَارِهِ فَرَجَعَ إِلَيْهِ فَقَالَ: وَعِزَّتِكَ لَقَدْ خِفْتُ أَنْ لاَ يَدْخُلَهَا أَحَدٌ. قَالَ: اذْهَبْ إِلَى النَّارِ، فَانْظُرْ إِلَيْهَا وَإِلَى مَا أَعْدَدْتُ لأَهْلِهَا فِيهَا. فَإِذَا هِيَ يَرْكَبُ بَعْضُهَا بَعْضًا فَرَجَعَ إِلَيْهِ فَقَالَ: وَعِزَّتِكَ لاَ يَسْمَعُ بِهَا أَحَدٌ فَيَدْخُلُهَا. فَأَمَرَ بِهَا فَحُفَّتْ بِالشَّهَوَاتِ فَقَالَ: ارْجِعْ إِلَيْهَا. فَرَجَعَ إِلَيْهَا فَقَالَ: وَعِزَّتِكَ لَقَدْ خَشِيتُ أَنْ لاَ يَنْجُوَ مِنْهَا أَحَدٌ إِلاَّ دَخَلَهَا."],"takhrij":"حسن: رواه أبو داود (4744)، والترمذي (2560)، والنسائي (3763)، وصحّحه ابن حبان (7394) كلهم من طريق محمد بن عمرو بن علقمة الليثي، عن أبي سلمة، عن أبي هريرة فذكره.","grade":"حسن","chapter_ar":"باب حفت الجنة بالمكاره وحفت النار بالشهوات","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (4744), al-Tirmidhī (2560), al-Nasā’ī (3763), and authenticated by Ibn Ḥibbān (7394).","chapter_en":"Paradise Is Surrounded by Hardships and the Fire Is Surrounded by Desires","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة الجنة والنار معًا","group_en":"A Collection of What Has Been Narrated Concerning the Description of Paradise and the Fire Together","part_no":67,"group_no":5,"chapter_no":2,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “When Allah created Paradise and the Fire, He sent Jibrīl to Paradise and said: ‘Look at it and at what I have prepared in it for its people.’ So he went to it and looked at it and at what Allah had prepared therein for its people. Then he returned and said: ‘By Your Might, no one will hear about it except that he will enter it.’ Then Allah commanded that it be surrounded by hardships and said: ‘Return to it and look at what I have prepared therein for its people.’ He returned and found that it had been surrounded by hardships. So he returned to Allah and said: ‘By Your Might, I fear that no one will enter it.’ Then He said: ‘Go to the Fire and look at it and at what I have prepared in it for its people.’ He went and saw its parts piled one upon another. He returned and said: ‘By Your Might, no one will hear about it and then enter it.’ Then Allah commanded that it be surrounded by desires and said: ‘Return to it.’ He returned and then said: ‘By Your Might, I fear that no one will escape it without entering it.’”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[8248],"tks":"حسن: رواه أبو داود (4744)، والترمذي (2560)، والنسائي (3763)، وصححه ابن حبان (7394)."},{"num":16516,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، رَضِيَ اللَّهُ عَنْهُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:  إِذَا جَاءَ رَمَضَانُ فُتِّحَتْ أَبْوَابُ الْجَنَّةِ، وَغُلِّقَتْ أَبْوَابُ النَّارِ، وَصُفِّدَتِ الشَّيَاطِينُ."],"takhrij":"متفق عليه: رواه البخاري في الصوم (1898)، ومسلم في الصيام (1079) كلاهما عن قتيبة، حدثنا إسماعيل بن جعفر، عن أبي سهيل، عن أبيه، عن أبي هريرة فذكره. واللفظ لمسلم ، واقتصر البخاري على الجملة الأولى من الحديث.","grade":"متفق عليه","chapter_ar":"باب تفتح أبواب الجنة وتغلق أبواب النار في شهر رمضان","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (1898) and Muslim (1079).","chapter_en":"The Gates of Paradise Are Opened and the Gates of the Fire Are Closed During the Month of Ramaḍān","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة الجنة والنار معًا","group_en":"A Collection of What Has Been Narrated Concerning the Description of Paradise and the Fire Together","part_no":67,"group_no":5,"chapter_no":3,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “When Ramaḍān comes, the gates of Paradise are opened, the gates of the Fire are closed, and the devils are chained.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (1898)، ومسلم (1079)."},{"num":16517,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : إِذَا كَانَ رَمَضَانُ فُتِّحَتْ أَبْوَابُ الرَّحْمَةِ، وَغُلِّقَتْ أَبْوَابُ جَهَنَّمَ، وَسُلْسِلَتِ الشَّيَاطِينُ."],"takhrij":"متفق عليه: رواه البخاري في بدء الخلق (3277)، ومسلم في الصيام (1079: 2) كلاهما من طريق ابن شهاب قال: حدثني نافع بن أبي أنس مولى التيميين، أن أباه حدثه أنه سمع أبا هريرة فذكره.","grade":"متفق عليه","chapter_ar":"باب تفتح أبواب الجنة وتغلق أبواب النار في شهر رمضان","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (3277) and Muslim (2 :1079).","chapter_en":"The Gates of Paradise Are Opened and the Gates of the Fire Are Closed During the Month of Ramaḍān","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة الجنة والنار معًا","group_en":"A Collection of What Has Been Narrated Concerning the Description of Paradise and the Fire Together","part_no":67,"group_no":5,"chapter_no":3,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “When Ramaḍān begins, the gates of mercy are opened, the gates of Hell are closed, and the devils are chained.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (3277)، ومسلم (1079: 2)."},{"num":16518,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لاَ يَدْخُلُ أَحَدٌ الْجَنَّةَ إِلاَّ أُرِيَ مَقْعَدَهُ مِنَ النَّارِ، لَوْ أَسَاءَ، لِيَزْدَادَ شُكْرًا، وَلاَ يَدْخُلُ النَّارَ أَحَدٌ إِلاَّ أُرِيَ مَقْعَدَهُ مِنَ الْجَنَّةِ، لَوْ أَحْسَنَ، لِيَكُونَ عَلَيْهِ حَسْرَةً."],"takhrij":"صحيح: رواه البخاري في الرقاق (6569) عن أبي اليمان، أخبرنا شعيب، حدثنا أبو الزناد، عن الأعرج، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب أهل الجنة يرون مقاعدهم من النار لو أساؤوا، وأهل النار يرون مقاعدهم من الجنة لو أحسنوا","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (6569).","chapter_en":"The People of Paradise Will See Their Places in the Fire Had They Done Evil, and the People of the Fire Will See Their Places in Paradise Had They Done Good","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة الجنة والنار معًا","group_en":"A Collection of What Has Been Narrated Concerning the Description of Paradise and the Fire Together","part_no":67,"group_no":5,"chapter_no":4,"content":{"translation":{"en":["Abū Hurayrah narrated that the Prophet ﷺ said: “No one will enter Paradise except that he will be shown the place he would have occupied in the Fire had he done evil, so that he may increase in gratitude. And no one will enter the Fire except that he will be shown the place he would have occupied in Paradise had he done good, so that it may become a source of regret for him.”"]}},"tuhfa":{},"full":1,"rep":[12712],"tks":"صحيح: رواه البخاري (6569)."},{"num":16519,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّٰهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : كُلُّ أَهْلِ النَّارِ يَرَى مَنْزِلَهُ مِنَ الْجَنَّةِ، فَيَكُونُ لَهُ حَسْرَةٌ فَيَقُولُ: ﴿لَوْ أَنَّ اللَّهَ هَدَانِي لَكُنْتُ مِنَ الْمُتَّقِينَ﴾ [سورة الزمر: ٥٧]، وَكُلُّ أَهْلِ الْجَنَّةِ يَرَى مَنْزِلَهُ مِنَ النَّارِ فَيَقُولُ: ﴿وَمَا كُنَّا لِنَهْتَدِيَ لَوْلَا أَنْ هَدَانَا اللَّهُ﴾ [سورة الأعراف: ٤٣]، فَيَكُونُ لَهُ شُكْرًا. قَالَ: وَقَالَ رَسُولُ اللَّٰهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : مَا مِنْ أَحَدٍ إِلاَّ وَلَهُ مَنْزِلٌ فِي الْجَنَّةِ، وَمَنْزِلٌ فِي النَّارِ، فَالْكَافِرُ يَرِثُ الْمُؤْمِنَ مَنْزِلَهُ مِنَ النَّارِ، وَالْمُؤْمِنُ يَرِثُ الْكَافِرَ مَنْزِلَهُ مِنَ الْجَنَّةِ، وَذَلِكَ قَوْلُهُ تَعَالَى: ﴿وَتِلْكَ الْجَنَّةُ الَّتِي أُورِثْتُمُوهَا بِمَا كُنْتُمْ تَعْمَلُونَ﴾ [الزخرف: ٧٢]."],"takhrij":"حسن: رواه ابن أبي حاتم في تفسيره –كما في تفسير ابن كثير (7/240) عن الفضل بن شاذان المقري، حدثنا يوسف بن يعقوب يعني الصفار، حدثنا أبو بكر بن عياش، عن الأعمش، عن أبي صالح، عن أبي هريرة فذكره.","grade":"حسن","chapter_ar":"باب أهل الجنة يرون مقاعدهم من النار لو أساؤوا، وأهل النار يرون مقاعدهم من الجنة لو أحسنوا","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Abī Ḥātim in his Tafsīr, as cited in Ibn Kathīr’s Tafsīr (7/240).","chapter_en":"The People of Paradise Will See Their Places in the Fire Had They Done Evil, and the People of the Fire Will See Their Places in Paradise Had They Done Good","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة الجنة والنار معًا","group_en":"A Collection of What Has Been Narrated Concerning the Description of Paradise and the Fire Together","part_no":67,"group_no":5,"chapter_no":4,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “Every person from the people of the Fire will see the dwelling that would have been his in Paradise, and it will become a source of regret for him. He will say: ‘If only Allah had guided me, I would have been among the righteous.’ [al-Zumar 39:57] And every person from the people of Paradise will see the dwelling that would have been his in the Fire and will say: ‘We would never have been guided had Allah not guided us.’ [al-Aʿrāf 7:43] So this will increase him in gratitude.” He also said that the Messenger of Allah ﷺ said: “There is no one except that he has a dwelling in Paradise and a dwelling in the Fire. The disbeliever will inherit the believer’s dwelling in the Fire, and the believer will inherit the disbeliever’s dwelling in Paradise. That is the meaning of the statement of Allah, the Exalted: ‘That is the Paradise which you have been made to inherit because of what you used to do.’ [al-Zukhruf 43:72]”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن أبي حاتم في تفسيره - كما في تفسير ابن كثير - (7/240)."},{"num":16520,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:  يُؤْتَى بِأَنْعَمِ أَهْلِ الدُّنْيَا مِنْ أَهْلِ النَّارِ يَوْمَ الْقِيَامَةِ، فَيُصْبَغُ فِي النَّارِ صَبْغَةً، ثُمَّ يُقَالُ: يَا ابْنَ آدَمَ، هَلْ رَأَيْتَ خَيْرًا قَطُّ؟ هَلْ مَرَّ بِكَ نَعِيمٌ قَطُّ؟ فَيَقُولُ: لَا، وَاللهِ يَا رَبِّ. وَيُؤْتَى بِأَشَدِّ النَّاسِ بُؤْسًا فِي الدُّنْيَا مِنْ أَهْلِ الْجَنَّةِ، فَيُصْبَغُ صَبْغَةً فِي الْجَنَّةِ، فَيُقَالُ لَهُ: يَا ابْنَ آدَمَ، هَلْ رَأَيْتَ بُؤْسًا قَطُّ؟ هَلْ مَرَّ بِكَ شِدَّةٌ قَطُّ؟ فَيَقُولُ: لَا، وَاللهِ يَا رَبِّ، مَا مَرَّ بِي بُؤْسٌ قَطُّ، وَلَا رَأَيْتُ شِدَّةً قَطُّ."],"takhrij":"صحيح: رواه مسلم في صفة القيامة (2807) عن عمرو الناقد، حدثنا يزيد بن هارون، أخبرنا حماد بن سلمة، عن ثابت البناني، عن أنس بن مالك فذكره.","grade":"صحيح","chapter_ar":"باب صبغ أنعم أهل الدنيا من أهل النار في النار، وصبغ أشد الناس بؤسًا من أهل الجنة في الجنة","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2807).","chapter_en":"The Most Prosperous Person of This World among the People of the Fire Will Be Dipped into the Fire, and the Most Miserable Person of This World among the People of Paradise Will Be Dipped into Paradise","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة الجنة والنار معًا","group_en":"A Collection of What Has Been Narrated Concerning the Description of Paradise and the Fire Together","part_no":67,"group_no":5,"chapter_no":5,"content":{"translation":{"en":["Anas ibn Mālik narrated that the Messenger of Allah ﷺ said: “The person who enjoyed the greatest luxury in this world among those destined for the Fire will be brought on the Day of Resurrection and dipped once into the Fire. Then it will be said to him: ‘O son of Ādam, have you ever seen any good? Have you ever experienced any pleasure?’ He will say: ‘No, by Allah, my Lord.’ And the person who suffered the greatest misery in this world among those destined for Paradise will be brought and dipped once into Paradise. Then it will be said to him: ‘O son of Ādam, have you ever experienced any misery? Have you ever gone through any hardship?’ He will say: ‘No, by Allah, my Lord. No misery ever passed over me, and I never experienced any hardship.’”"]}},"tuhfa":{},"full":1,"rep":[12930],"tks":"صحيح: رواه مسلم (2807)."},{"num":16521,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: الْجَنَّةُ أَقْرَبُ إِلَى أَحَدِكُمْ مِنْ شِرَاكِ نَعْلِهِ، وَالنَّارُ مِثْلُ ذَلِكَ."],"takhrij":"صحيح: رواه البخاري في الرقاق (6488)، عن موسى بن مسعود، حدثنا سفيان، عن منصور، والأعمش، عن أبي وائل، عن عبد الله فذكره.","grade":"صحيح","chapter_ar":"باب قرب الجنة والنار من العبد","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (6488).","chapter_en":"The Nearness of Paradise and the Fire to the Servant","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة الجنة والنار معًا","group_en":"A Collection of What Has Been Narrated Concerning the Description of Paradise and the Fire Together","part_no":67,"group_no":5,"chapter_no":6,"content":{"translation":{"en":["ʿAbdullāh ibn Masʿūd narrated that the Prophet ﷺ said: “Paradise is closer to each one of you than the strap of his sandal, and the Fire is likewise.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (6488)."},{"num":16522,"demo":false,"sanad":"","matn":["عن أنس بْنِ مَالِكٍ، ـ رَضِيَ اللَّهُ عَنْهُ. أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَرَجَ حِينَ زَاغَتِ الشَّمْسُ، فَصَلَّى الظُّهْرَ، فَلَمَّا سَلَّمَ، قَامَ عَلَى الْمِنْبَرِ، فَذَكَرَ السَّاعَةَ، وَذَكَرَ أَنَّ بَيْنَ يَدَيْهَا أُمُورًا عِظَامًا، ثُمَّ قَالَ: مَنْ أَحَبَّ أَنْ يَسْأَلَ عَنْ شَىْءٍ فَلْيَسْأَلْ عَنْهُ، فَوَاللَّهِ لاَ تَسْأَلُونِي عَنْ شَىْءٍ إِلاَّ أَخْبَرْتُكُمْ بِهِ، مَا دُمْتُ فِي مَقَامِي هَذَا.","قَالَ أَنَسٌ: فَأَكْثَرَ النَّاسُ الْبُكَاءَ، وَأَكْثَرَ رَسُولُ اللهِ صلى الله عليه وسلم أَنْ يَقُولَ: سَلُونِي فَقَالَ أَنَسٌ: فَقَامَ إِلَيْهِ رَجُلٌ: فَقَالَ: أَيْنَ مَُدْخَلِي يَا رَسُولَ اللهِ؟ قَالَ: النَّارُ، فَقَامَ عَبْدُ اللهِ بْنُ حُذَافَةَ، فَقَالَ: مَنْ أَبِي يَا رَسُولَ اللهِ؟ قَالَ: أَبُوكَ حُذَافَةُ، قَالَ: ثُمَّ أَكْثَرَ أَنْ يَقُولَ: سَلُونِي سَلُونِي، فَبَرَكَ عُمَرُ عَلَى رُكْبَتَيْهِ، فَقَالَ: رَضِينَا بِاللهِ رَبًّا، وَبِالإِسْلَامِ دِينًا، وَبِمُحَمَّدٍ صلى الله عليه وسلم رَسُولًا، قَالَ: فَسَكَتَ رَسُولُ اللهِ صلى الله عليه وسلم حِينَ قَالَ عُمَرُ ذَلِكَ، ثُمَّ قَالَ رَسُولُ اللهِ صلى الله عليه وسلم: وَالَّذِي نَفْسِي بِيَدِهِ لَقَدْ عُرِضَتْ عَلَيَّ الْجَنَّةُ وَالنَّارُ آنِفًا فِي عُرْضِ هَذَا الْحَائِطِ وَأَنَا أُصَلِّي، فَلَمْ أَرَ كَالْيَوْمِ فِي الْخَيْرِ وَالشَّرِّ."],"takhrij":"متفق عليه: رواه البخاري في الاعتصام (7294) واللفظ له، ومسلم في الفضائل (2395: 136) كلاهما من طريق الزهري، عن أنس بن مالك، فذكره.","grade":"متفق عليه","chapter_ar":"باب عرض الجنة والنار على النبي ﷺ ورؤيته ما فيها من الخير والشر","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (7294), whose wording this is, and Muslim (136 :2395).","chapter_en":"Paradise and the Fire Were Shown to the Prophet ﷺ, and He Saw the Good and Evil Contained in Them","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة الجنة والنار معًا","group_en":"A Collection of What Has Been Narrated Concerning the Description of Paradise and the Fire Together","part_no":67,"group_no":5,"chapter_no":7,"content":{"translation":{"en":["Anas ibn Mālik narrated: The Prophet ﷺ came out after the sun had passed its zenith and prayed Ẓuhr. When he gave the salām, he stood upon the pulpit, mentioned the Hour, and mentioned that tremendous events would occur before it. Then he said: “Whoever wishes to ask about anything, let him ask. By Allah, you will not ask me about anything while I remain standing here except that I will inform you about it.” Anas said: The people began weeping intensely, while the Messenger of Allah ﷺ repeatedly said: “Ask me.”","A man stood and asked: “Where will I enter, O Messenger of Allah?” He replied: “The Fire.” Then ʿAbdullāh ibn Ḥudhāfah stood and asked: “Who is my father, O Messenger of Allah?” He replied: “Your father is Ḥudhāfah.” Then he continued saying: “Ask me, ask me.” ʿUmar fell to his knees and said: “We are pleased with Allah as our Lord, with Islam as our religion, and with Muḥammad as our Messenger.” When ʿUmar said that, the Messenger of Allah ﷺ became silent. Then the Messenger of Allah ﷺ said: “By the One in whose hand is my soul, Paradise and the Fire were just now shown to me across this wall while I was praying. I have never seen anything like what I saw today in good and evil.”"]},"buhuth":{"en":["The identity of the man who asked where he would enter and was told “the Fire” is not known.","The author states that either this man was a hypocrite, or the statement indicated that his end would be evil. Otherwise, according to the author, the Companions are all destined for Paradise, based on the statement of Allah, the Exalted:","“Why should you not spend in the cause of Allah when to Allah belongs the inheritance of the heavens and the earth? Those among you who spent and fought before the Conquest are not equal to those who did so afterward. They are greater in rank than those who spent and fought afterward, though Allah has promised the best reward to all. And Allah is fully aware of what you do.”","[al-Ḥadīd 57:10]","And He, the Exalted, says:","“Indeed, those for whom the best reward has already gone forth from Us—they will be kept far away from it.”","[al-Anbiyāʾ 21:101]"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (7294) واللفظ له، ومسلم (2395: 136)."},{"num":16523,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ قَالَ: لَا تَزَالُ جَهَنَّمُ يُلْقَى فِيهَا وَتَقُولُ: هَلْ مِنْ مَزِيدٍ؟ حَتَّى يَضَعَ رَبُّ الْعِزَّةِ فِيهَا قَدَمَهُ، فَيَنْزَوِي بَعْضُهَا إِلَى بَعْضٍ، وَتَقُولُ: قَطْ قَطْ، بِعِزَّتِكَ وَكَرَمِكَ، وَلَا يَزَالُ فِي الْجَنَّةِ فَضْلٌ حَتَّى يُنْشِئَ اللهُ لَهَا خَلْقًا، فَيُسْكِنَهُمْ فَضْلَ الْجَنَّةِ."],"takhrij":"متفق عليه: رواه مسلم في الجنة وصفة نعيمها (2848: 38) عن محمد بن عبد الله الرُزِّي، حدثنا عبد الوهاب بن عطاء، في قوله عز وجل: يَوْمَ نَقُولُ لِجَهَنَّمَ هَلِ امْتَلَأْتِ وَتَقُولُ هَلْ مِنْ مَزِيدٍ [ق: 30] فأخبرنا عن سعيد (هو ابن أبي عروبة)، عن قتادة، عن أنس فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في سعة الجنة والنار","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Agreed upon: Narrated by Muslim (38 :2848) and al-Bukhārī (7384).","chapter_en":"What Has Been Narrated Concerning the Vastness of Paradise and the Fire","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة الجنة والنار معًا","group_en":"A Collection of What Has Been Narrated Concerning the Description of Paradise and the Fire Together","part_no":67,"group_no":5,"chapter_no":8,"content":{"translation":{"en":["Anas ibn Mālik narrated that the Prophet ﷺ said: “People will continue to be cast into Hell while it says: ‘Is there any more?’ until the Lord of Might places His Foot in it. Then its parts will draw together and it will say: ‘Enough, enough, by Your Might and Your Generosity.’ And there will continue to remain extra space in Paradise until Allah creates a creation for it and settles them in the remaining space of Paradise.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مسلم (2848: 38) والبخاري (7384)."},{"num":16524,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بن عُمَرَ، أن رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِذَا صَارَ أَهْلُ الْجَنَّةِ إِلَى الْجَنَّةِ، وصار أهل النَّارِ إِلَى النَّارِ، أتي بِالْمَوْتِ حَتَّى يُجْعَلَ بَيْنَ الْجَنَّةِ وَالنَّارِ، ثُمَّ يُذْبَحُ، ثُمَّ يُنَادِي مُنَادٍ: يَا أَهْلَ الْجَنَّةِ لاَ مَوْتَ، وَيَا أَهْلَ النَّارِ لاَ مَوْتَ، فَيَزْدَادُ أَهْلُ الْجَنَّةِ فَرَحًا إِلَى فَرَحِهِمْ، وَيَزْدَادُ أَهْلُ النَّارِ حُزْنًا إِلَى حُزْنِهِمْ."],"takhrij":"متفق عليه: رواه البخاري في الرقاق (6548)، ومسلم في الجنة (2850: 43) كلاهما من طريق عبد الله بن وهب، حدثني عمر بن محمد بن زيد بن عبد الله بن عمر بن الخطاب، أن أباه حدثه عن عبد الله بن عمر فذكره.","grade":"متفق عليه","chapter_ar":"باب خلود الجنة والنار","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6548) and Muslim (43 :2850).","chapter_en":"The Eternity of Paradise and the Fire","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة الجنة والنار معًا","group_en":"A Collection of What Has Been Narrated Concerning the Description of Paradise and the Fire Together","part_no":67,"group_no":5,"chapter_no":9,"content":{"translation":{"en":["ʿAbdullāh ibn ʿUmar narrated that the Messenger of Allah ﷺ said: “When the people of Paradise have gone to Paradise and the people of the Fire have gone to the Fire, death will be brought and placed between Paradise and the Fire, then it will be slaughtered. Then a caller will proclaim: ‘O people of Paradise, there is no more death! O people of the Fire, there is no more death!’ The people of Paradise will thereby increase in joy upon their joy, and the people of the Fire will increase in sorrow upon their sorrow.”"]},"intro":{"ar":["قال اللّٰه تعالى:","﴿إِنَّ الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ كَانَتْ لَهُمْ جَنَّاتُ الْفِرْدَوْسِ نُزُلًا ۝ خَالِدِينَ فِيهَا لَا يَبْغُونَ عَنْهَا حِوَلًا﴾ [الكهف: ١٠٧-١٠٨].","وقال تعالى:","﴿إِنَّ الَّذِينَ كَفَرُوا وَمَاتُوا وَهُمْ كُفَّارٌ أُولَٰئِكَ عَلَيْهِمْ لَعْنَةُ اللَّهِ وَالْمَلَائِكَةِ وَالنَّاسِ أَجْمَعِينَ ۝ خَالِدِينَ فِيهَا لَا يُخَفَّفُ عَنْهُمُ الْعَذَابُ وَلَا هُمْ يُنْظَرُونَ﴾ [البقرة: ١٦١-١٦٢]."],"en":["Allah, the Exalted, says:","“Indeed, those who believe and perform righteous deeds will have the Gardens of al-Firdaws as their hospitality, remaining therein forever, never desiring any change from it.”","[al-Kahf 18:107-108]","And He, the Exalted, says:","“Indeed, those who disbelieve and die while they are disbelievers—upon them is the curse of Allah, the angels, and all mankind, remaining therein forever. The punishment will not be lightened for them, nor will they be given respite.”","[al-Baqarah 2:161-162]"]}},"tuhfa":{},"full":1,"rep":[12711,13253],"tks":"متفق عليه: رواه البخاري (6548)، ومسلم (2850: 43)."},{"num":16525,"demo":false,"sanad":"","matn":["عن عَبْدِ اللَّهِ بن عُمَرَ قَالَ: إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:  يُدْخِلُ اللهُ أَهْلَ الْجَنَّةِ الْجَنَّةَ، وَيُدْخِلُ أَهْلَ النَّارِ النَّارَ، ثُمَّ يَقُومُ مُؤَذِّنٌ بَيْنَهُمْ فَيَقُولُ: يَا أَهْلَ الْجَنَّةِ لَا مَوْتَ، وَيَا أَهْلَ النَّارِ لَا مَوْتَ، كُلٌّ خَالِدٌ فِيمَا هُوَ فِيهِ."],"takhrij":"متفق عليه: رواه البخاري في الرقاق (6544)، ومسلم في الجنة (2850) كلاهما من طريق يعقوب – هو ابن إبراهيم بن سعد – حدثنا أبي، عن صالح، حدثنا نافع، أن عبد الله بن عمر قال: فذكره.","grade":"متفق عليه","chapter_ar":"باب خلود الجنة والنار","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6544) and Muslim (2850).","chapter_en":"The Eternity of Paradise and the Fire","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة الجنة والنار معًا","group_en":"A Collection of What Has Been Narrated Concerning the Description of Paradise and the Fire Together","part_no":67,"group_no":5,"chapter_no":9,"content":{"translation":{"en":["ʿAbdullāh ibn ʿUmar narrated that the Messenger of Allah ﷺ said: “Allah will admit the people of Paradise into Paradise and the people of the Fire into the Fire. Then a caller will stand between them and proclaim: ‘O people of Paradise, there is no death! O people of the Fire, there is no death! Everyone will remain forever in the state in which he is.’”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (6544)، ومسلم (2850)."},{"num":16526,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: يُؤْتَى بِالْمَوْتِ كَهَيْئَةِ كَبْشٍ أَمْلَحَ، فَيُنَادِي مُنَادٍ: يَا أَهْلَ الْجَنَّةِ، فَيَشْرَئِبُّونَ وَيَنْظُرُونَ، فَيَقُولُ: هَلْ تَعْرِفُونَ هَذَا؟ فَيَقُولُونَ: نَعَمْ، هَذَا الْمَوْتُ، وَكُلُّهُمْ قَدْ رَآهُ، ثُمَّ يُنَادِي: يَا أَهْلَ النَّارِ، فَيَشْرَئِبُّونَ وَيَنْظُرُونَ، فَيَقُولُ: هَلْ تَعْرِفُونَ هَذَا؟ فَيَقُولُونَ: نَعَمْ، هَذَا الْمَوْتُ، وَكُلُّهُمْ قَدْ رَآهُ، فَيُذْبَحُ ثُمَّ يَقُولُ: يَا أَهْلَ الْجَنَّةِ، خُلُودٌ فَلاَ مَوْتَ، وَيَا أَهْلَ النَّارِ، خُلُودٌ فَلاَ مَوْتَ، ثُمَّ قَرَأَ: ﴿وَأَنْذِرْهُمْ يَوْمَ الْحَسْرَةِ إِذْ قُضِيَ الأَمْرُ وَهُمْ فِي غَفْلَةٍ﴾ [سورة مريم: 39]}، وَهَؤُلاَءِ فِي غَفْلَةٍ أَهْلُ الدُّنْيَا {وَهُمْ لاَ يُؤْمِنُونَ}."],"takhrij":"متفق عليه: رواه البخاري في التفسير (4730)، ومسلم في الجنة (2849) كلاهما من طريق الأعمش، حدثنا أبو صالح، عن أبي سعيد الخدري قال: فذكره.","grade":"متفق عليه","chapter_ar":"باب خلود الجنة والنار","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (4730) and Muslim (2849).","chapter_en":"The Eternity of Paradise and the Fire","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة الجنة والنار معًا","group_en":"A Collection of What Has Been Narrated Concerning the Description of Paradise and the Fire Together","part_no":67,"group_no":5,"chapter_no":9,"content":{"translation":{"en":["Abū Saʿīd al-Khudrī narrated that the Messenger of Allah ﷺ said: “Death will be brought in the form of a black-and-white ram. A caller will proclaim: ‘O people of Paradise!’ They will crane their necks and look. He will ask: ‘Do you recognize this?’ They will reply: ‘Yes. This is death,’ for all of them will have seen it. Then he will call: ‘O people of the Fire!’ They will crane their necks and look. He will ask: ‘Do you recognize this?’ They will reply: ‘Yes. This is death,’ for all of them will have seen it. Then it will be slaughtered, and it will be said: ‘O people of Paradise, everlasting life with no death! O people of the Fire, everlasting life with no death!’” Then he recited: “Warn them of the Day of Regret, when the matter will have been decided while they are in heedlessness.” [Maryam 19:39] These people are presently in the heedlessness of this worldly life: “And they do not believe.” [Maryam 19:39]"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (4730)، ومسلم (2849)."},{"num":16527,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ: قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: يُقَالُ لأَهْلِ الْجَنَّةِ: خُلُودٌ لاَ مَوْتَ. وَلأَهْلِ النَّارِ يَا أَهْلَ النَّارِ خُلُودٌ لاَ مَوْتَ."],"takhrij":"صحيح: رواه البخاري في الرقاق (6545) عن أبي اليمان، أخبرنا شعيب، حدثنا أبو الزناد، عن الأعرج، عن أبي هريرة قال: فذكره.","grade":"صحيح","chapter_ar":"باب خلود الجنة والنار","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (6545).","chapter_en":"The Eternity of Paradise and the Fire","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة الجنة والنار معًا","group_en":"A Collection of What Has Been Narrated Concerning the Description of Paradise and the Fire Together","part_no":67,"group_no":5,"chapter_no":9,"content":{"translation":{"en":["Abū Hurayrah narrated that the Prophet ﷺ said: “It will be said to the people of Paradise: ‘Everlasting life with no death,’ and to the people of the Fire: ‘O people of the Fire, everlasting life with no death.’”"]},"buhuth":{"en":["Imām Aḥmad (8535) also narrated it through another route as a Prophetic report with the wording:","“When the people of Paradise have entered Paradise and the people of the Fire have entered the Fire, a caller will proclaim: ‘O people of Paradise, everlasting life with no death therein! O people of the Fire, everlasting life with no death therein!’”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (6545)."},{"num":16528,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أنّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ فِي حَدِيثٌ طَوِيلٍ: فَإِذَا أَدْخَلَ اللَّهُ أَهْلَ الْجَنَّةِ الْجَنَّةَ وَأَهْلَ النَّارِ النَّارَ، قَالَ: أُتِي بِالْمَوْتِ مُلَبّباً فَيُوقَفُ عَلَى السُّورِ الَّذِي بَيْنَ أَهْلِ الْجَنَّةِ وَأَهْلِ النَّارِ، ثُمَّ يُقَالُ: يَا أَهْلَ الْجَنَّةِ فَيَطَّلِعُونَ خَائِفِينَ، ثُمَّ يُقَالُ: يَا أَهْلَ النَّارِ فَيَطَّلِعُونَ مُسْتَبْشِرِينَ يَرْجُونَ الشَّفَاعَةَ، فَيُقَالُ لأَهْلِ الْجَنَّةِ وَأَهْلِ النَّارِ: هَلْ تَعْرِفُونَ هَذَا؟ فَيَقُولُونَ هَؤُلاَءِ وَهَؤُلاَءِ: قَدْ عَرَفْنَاهُ، هُوَ الْمَوْتُ الَّذِي وُكِّل بِنَا، فَيُضْجَعُ فَيُذْبَحُ ذَبْحًا عَلَى السُّور الَّذِي بَيْنَ الْجَنَّةِ وَالنَّارِ، ثُمَّ يُقَالُ: يَا أَهْلَ الْجَنَّةِ خُلُودٌ لاَ مَوْتَ، وَيَا أَهْلَ النَّارِ خُلُودٌ لاَ مَوْتَ."],"takhrij":"حسن: رواه الترمذيّ (2557)، وابن خزيمة في التوحيد (150) كلاهما من طريق عبدالعزيز بن محمد الدّراورديّ، عن العلاء بن عبدالرحمن، عن أبيه، عن أبي هريرة، فذكره.","grade":"حسن","chapter_ar":"باب خلود الجنة والنار","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhī (2557) and Ibn Khuzaymah in al-Tawḥīd (150).","chapter_en":"The Eternity of Paradise and the Fire","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة الجنة والنار معًا","group_en":"A Collection of What Has Been Narrated Concerning the Description of Paradise and the Fire Together","part_no":67,"group_no":5,"chapter_no":9,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said in a lengthy hadith: “When Allah has admitted the people of Paradise into Paradise and the people of the Fire into the Fire, death will be brought restrained and made to stand upon the wall between the people of Paradise and the people of the Fire. Then it will be said: ‘O people of Paradise!’ and they will look out fearfully. Then it will be said: ‘O people of the Fire!’ and they will look out joyfully, hoping for intercession. Then both the people of Paradise and the people of the Fire will be asked: ‘Do you recognize this?’ Both groups will say: ‘We recognize it. It is death, which had been appointed over us.’ Then it will be laid down and slaughtered upon the wall between Paradise and the Fire. Then it will be said: ‘O people of Paradise, everlasting life with no death! O people of the Fire, everlasting life with no death!’”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الترمذي (2557)، وابن خزيمة في التوحيد (150)."},{"num":16529,"demo":false,"sanad":"","matn":["عَنْ أنَسٍ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: يُؤْتَى بِالْمَوْتِ يَوْمَ الْقِيَامَةِ، فَيُوقَفُ بَيْنَ الْجَنَّةِ وَالنَّارِ، فَيُذْبَحُ، فَيُقَالُ: يَا أَهْلَ الْجَنَّةِ خُلُودٌ لا مَوْتَ، وَيَا أَهْلَ النَّارِ خُلُودٌ لا مَوْتَ."],"takhrij":"حسن: رواه البزار (7240)، وأبو يعلى (2898)، والطبراني في الأوسط (3685)، والضياء في المختارة (2447) كلهم من طريق نافع بن خالد الطاحي، حدثنا نوح بن قيس الطاحي، عن أخيه خالد بن قيس، عن قتادة، عن أنس فذكره.","grade":"حسن","chapter_ar":"باب خلود الجنة والنار","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Hasan: Narrated by al-Bazzār (7240), Abū Yaʿlā (2898), al-Ṭabarānī in al-Muʿjam al-Awsaṭ (3672), and al-Ḍiyāʾ in al-Aḥādīth al-Mukhtārah (2447).","chapter_en":"The Eternity of Paradise and the Fire","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة الجنة والنار معًا","group_en":"A Collection of What Has Been Narrated Concerning the Description of Paradise and the Fire Together","part_no":67,"group_no":5,"chapter_no":9,"content":{"translation":{"en":["Anas narrated that the Prophet ﷺ said: “Death will be brought on the Day of Resurrection and made to stand between Paradise and the Fire, then it will be slaughtered. It will be said: ‘O people of Paradise, everlasting life with no death! O people of the Fire, everlasting life with no death!’”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه البزار (7240)، وأبو يعلى (2898)، والطبراني في الأوسط (3685)، والضياء في المختارة (2447)."},{"num":16530,"demo":false,"sanad":"","matn":["عن سعيد بْنِ وَهْبٍ الْهَمْدَانِيِّ قَالَ: قَدِمَ عَلَيْنَا مُعَاذُ بْنُ جَبَلٍ رضي الله عنه اليمن، فقال: إني رَسُولُ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  إِلَيْكُمْ: أَنْ تعبدوا الله تعالى، / وَلَا تُشْرِكُوا بِهِ شَيْئًا، وَأَنْ تُطِيعُونِي لَا آلُوكُمْ خَيْرًا، وَأَنَّ الْمَصِيرَ إلى الله، تعالى، وإلى الْجَنَّةِ وَالنَّارِ، إقامة بلا ظَعْنٌ، وَخُلُودٌ بِلَا مَوْتٍ."],"takhrij":"صحيح: رواه إسحاق بن راهويه في مسنده كما في إتحاف الخيرة المهرة (58)، والمطالب العالية (2862) عن عبيد الله بن موسى، أنبأنا إسرائيل، عن أبي إسحاق، عن سعيد بن وهب الهمداني قال: فذكره.","grade":"صحيح","chapter_ar":"باب خلود الجنة والنار","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by Isḥāq ibn Rāhawayh in his Musnad, as cited in Itḥāf al-Khiyarah al-Maharah (58) and al-Maṭālib al-ʿĀliyah (2862).","chapter_en":"The Eternity of Paradise and the Fire","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة الجنة والنار معًا","group_en":"A Collection of What Has Been Narrated Concerning the Description of Paradise and the Fire Together","part_no":67,"group_no":5,"chapter_no":9,"content":{"translation":{"en":["Saʿīd ibn Wahb al-Hamdānī narrated: Muʿādh ibn Jabal came to us and said: “I am the messenger of the Messenger of Allah ﷺ to you, conveying: ‘That you worship Allah and associate nothing with Him; that you obey me, for I will spare no effort in directing you toward good; and that the final return is to Allah, the Exalted, and to Paradise or the Fire—an abiding without departure and an eternity without death.’”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه إسحاق بن راهويه في مسنده كما في إتحاف الخيرة المهرة (58)، والمطالب العالية (2862)."},{"num":16531,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ قَالَ:  أَتَى النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَجُلٌ، فَقَالَ: يَا رَسُولَ اللَّهِ، مَا الْمُوجِبَتَانِ؟ فَقَالَ: مَنْ مَاتَ لَا يُشْرِكُ بِاللهِ شَيْئًا دَخَلَ الْجَنَّةَ، وَمَنْ مَاتَ يُشْرِكُ بِاللهِ شَيْئًا دَخَلَ النَّارَ."],"takhrij":"صحيح: رواه مسلم في الإيمان (93) من طرق عن أبي معاوية، عن الأعمش، عن أبي سفيان، عن جابر، فذكره.","grade":"صحيح","chapter_ar":"باب من مات لا يشرك بالله شيئًا دخل الجنة، ومن مات يشرك بالله شيئًا دخل النار","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (93).","chapter_en":"Whoever Dies Without Associating Anything with Allah Will Enter Paradise, and Whoever Dies Associating Anything with Allah Will Enter the Fire","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل الجنة وأهل النار معًا","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise and the People of the Fire Together","part_no":67,"group_no":6,"chapter_no":1,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh narrated: A man came to the Prophet ﷺ and asked: “O Messenger of Allah, what are the two things that make the outcome certain?” He replied: “Whoever dies without associating anything with Allah will enter Paradise, and whoever dies associating anything with Allah will enter the Fire.”"]}},"tuhfa":{},"full":1,"rep":[11939],"tks":"صحيح: رواه مسلم (93)."},{"num":16532,"demo":false,"sanad":"","matn":["عَنْ أُسَامَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: قُمْتُ عَلَى بَابِ الْجَنَّةِ، فَكَانَ عَامَّةَ مَنْ دَخَلَهَا الْمَسَاكِينُ، وَأَصْحَابُ الْجَدِّ مَحْبُوسُونَ، غَيْرَ أَنَّ أَصْحَابَ النَّارِ قَدْ أُمِرَ بِهِمْ إِلَى النَّارِ، وَقُمْتُ عَلَى بَابِ النَّارِ، فَإِذَا عَامَّةُ مَنْ دَخَلَهَا النِّسَاءُ."],"takhrij":"متفق عليه: رواه البخاري في النكاح (5196)، ومسلم في الرقاق (2736) كلاهما من طريق سليمان التيمي، عن أبي عثمان، عن أسامة بن زيد فذكره.","grade":"متفق عليه","chapter_ar":"باب أكثر أهل الجنة الفقراء، وأكثر أهل النار النساء","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5196) and Muslim (2736).","chapter_en":"Most of the People of Paradise Are the Poor, and Most of the People of the Fire Are Women","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل الجنة وأهل النار معًا","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise and the People of the Fire Together","part_no":67,"group_no":6,"chapter_no":2,"content":{"translation":{"en":["Usāmah ibn Zayd narrated that the Prophet ﷺ said: “I stood at the gate of Paradise and saw that most of those who entered it were the poor, while the people of wealth and worldly fortune were being detained, except that those destined for the Fire had already been ordered to the Fire. And I stood at the gate of the Fire and saw that most of those who entered it were women.”"]}},"tuhfa":{},"full":1,"rep":[11989],"tks":"متفق عليه: رواه البخاري (5196)، ومسلم (2736)."},{"num":16533,"demo":false,"sanad":"","matn":["عَنْ عِمْرَانَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: اطَّلَعْتُ فِي الْجَنَّةِ فَرَأَيْتُ أَكْثَرَ أَهْلِهَا الْفُقَرَاءَ، وَاطَّلَعْتُ فِي النَّارِ فَرَأَيْتُ أَكْثَرَ أَهْلِهَا النِّسَاءَ."],"takhrij":"صحيح: رواه البخاري في الرقاق (6546) عن عثمان بن الهيثم، حدثنا عوف، عن أبي رجاء، عن عمران فذكره.","grade":"صحيح","chapter_ar":"باب أكثر أهل الجنة الفقراء، وأكثر أهل النار النساء","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (6546).","chapter_en":"Most of the People of Paradise Are the Poor, and Most of the People of the Fire Are Women","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل الجنة وأهل النار معًا","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise and the People of the Fire Together","part_no":67,"group_no":6,"chapter_no":2,"content":{"translation":{"en":["ʿImrān narrated that the Prophet ﷺ said: “I looked into Paradise and saw that most of its inhabitants were the poor, and I looked into the Fire and saw that most of its inhabitants were women.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (6546)."},{"num":16534,"demo":false,"sanad":"","matn":["عن ابْنِ عَبَّاسٍ يَقُولُ: قَالَ مُحَمَّدٌ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:  اطَّلَعْتُ فِي الْجَنَّةِ فَرَأَيْتُ أَكْثَرَ أَهْلِهَا الْفُقَرَاءَ، وَاطَّلَعْتُ فِي النَّارِ فَرَأَيْتُ أَكْثَرَ أَهْلِهَا النِّسَاءَ."],"takhrij":"صحيح: رواه مسلم في الرقاق (2737) عن زهير بن حرب، حدثنا إسماعيل بن إبراهيم، عن أيوب، عن أبي رجاء العطاردي، سمعت ابن عباس، يقول: فذكره.","grade":"صحيح","chapter_ar":"باب أكثر أهل الجنة الفقراء، وأكثر أهل النار النساء","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2737).","chapter_en":"Most of the People of Paradise Are the Poor, and Most of the People of the Fire Are Women","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل الجنة وأهل النار معًا","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise and the People of the Fire Together","part_no":67,"group_no":6,"chapter_no":2,"content":{"translation":{"en":["Ibn ʿAbbās narrated that Muḥammad ﷺ said: “I looked into Paradise and saw that most of its inhabitants were the poor, and I looked into the Fire and saw that most of its inhabitants were women.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (2737)."},{"num":16535,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : تَحَاجَّتِ الْجَنَّةُ وَالنَّارُ، فَقَالَتِ النَّارُ: أُوثِرْتُ بِالْمُتَكَبِّرِينَ وَالْمُتَجَبِّرِينَ، وَقَالَتِ الْجَنَّةُ: فَمَا لِي لاَ يَدْخُلُنِي إِلاَّ ضُعَفَاءُ النَّاسِ وَسَقَطُهُمْ وغرثهم؟ قَالَ اللَّهُ لِلْجَنَّةِ: إِنَّمَا أَنْتِ رَحْمَتِي أَرْحَمُ بِكِ مَنْ أَشَاءُ مِنْ عِبَادِي، وَقَالَ لِلنَّارِ: إِنَّمَا أَنْتِ عَذَابِي أُعَذِّبُ بِكِ مَنْ أَشَاءُ مِنْ عِبَادِي، وَلِكُلِّ وَاحِدَةٍ مِنْكُمَا مِلْؤُهَا، فَأَمَّا النَّارُ فَلاَ تَمْتَلِئُ حَتَّى يَضَعَ اللَّهُ تَبَارَكَ وَتَعَالَى رِجْلَهُ، تَقُولُ: قَطٍ قَطٍ قَطٍ، فَهُنَالِكَ تَمْتَلِئُ، وَيُزْوَى بَعْضُهَا إِلَى بَعْضٍ، وَلاَ يَظْلِمُ اللَّهُ مِنْ خَلْقِهِ أَحَدًا، وَأَمَّا الْجَنَّةُ فَإِنَّ اللَّهَ يُنْشِئُ لَهَا خَلْقًا."],"takhrij":"متفق عليه: رواه البخاري في التفسير (4850)، ومسلم في كتاب الجنة (2846/36) كلاهما عن محمد بن رافع، حدثنا عبد الرزاق، أخبرنا معمر، عن همام، عن أبي هريرة فذكره.","grade":"متفق عليه","chapter_ar":"باب يدخل الضعفاء الجنة والجبارون النار","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (4850) and Muslim (36/2846).","chapter_en":"The Weak Will Enter Paradise and the Tyrannical Will Enter the Fire","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل الجنة وأهل النار معًا","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise and the People of the Fire Together","part_no":67,"group_no":6,"chapter_no":3,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “Paradise and the Fire disputed with one another. The Fire said: ‘I have been favored with the arrogant and the tyrannical.’ Paradise said: ‘Why is it that none enter me except the weak, insignificant, and simple-minded among the people?’ Allah said to Paradise: ‘You are My mercy; through you I show mercy to whomever I will among My servants.’ And He said to the Fire: ‘You are My punishment; through you I punish whomever I will among My servants. Each of you will have its fill.’ As for the Fire, it will not become full until Allah, Blessed and Exalted, places His Foot in it, and it will say: ‘Enough, enough, enough.’ Then it will become full and its parts will contract together. Allah will not wrong anyone among His creation. As for Paradise, Allah will create a creation for it.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (4850)، ومسلم (2846/36)."},{"num":16536,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، قَالَ: اخْتَصَمَتِ الْجَنَّةُ وَالنَّارُ إِلَى رَبِّهِمَا، فَقَالَتِ الْجَنَّةُ: يَا رَبِّ، مَا لَهَا لاَ يَدْخُلُهَا إِلاَّ ضُعَفَاءُ النَّاسِ وَسَقَطُهُمْ. وَقَالَتِ النَّارُ: ـ يَعْنِي ـ أُوثِرْتُ بِالْمُتَكَبِّرِينَ. فَقَالَ اللَّهُ تَعَالَى لِلْجَنَّةِ: أَنْتِ رَحْمَتِي. وَقَالَ لِلنَّارِ: أَنْتِ عَذَابِي، أُصِيبُ بِكِ مَنْ أَشَاءُ، وَلِكُلِّ وَاحِدَةٍ مِنْكُمَا مِلْؤُهَا. ـ قَالَ: ـ فَأَمَّا الْجَنَّةُ فَإِنَّ اللَّهَ لاَ يَظْلِمُ مِنْ خَلْقِهِ أَحَدًا، وَإِنَّهُ يُنْشِئُ لِلنَّارِ مَنْ يَشَاءُ، فَيُلْقَوْنَ فِيهَا، فَتَقُولُ: هَلْ مِنْ مَزِيدٍ. ثَلاَثًا، حَتَّى يَضَعَ فِيهَا قَدَمَهُ فَتَمْتَلِئُ، وَيُرَدُّ بَعْضُهَا إِلَى بَعْضٍ، وَتَقُولُ: قَطْ قَطْ قَطْ."],"takhrij":"متفق عليه: رواه البخاري في التوحيد (7449) عن عبيد الله بن سعد بن إبراهيم، حدثنا يعقوب، حدثنا أبي، عن صالح بن كيسان، عن الأعرج، عن أبي هريرة، فذكره.","grade":"متفق عليه","chapter_ar":"باب يدخل الضعفاء الجنة والجبارون النار","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (7449) and Muslim (2846).","chapter_en":"The Weak Will Enter Paradise and the Tyrannical Will Enter the Fire","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل الجنة وأهل النار معًا","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise and the People of the Fire Together","part_no":67,"group_no":6,"chapter_no":3,"content":{"translation":{"en":["Abū Hurayrah narrated that the Prophet ﷺ said: “Paradise and the Fire brought their dispute before their Lord. Paradise said: ‘My Lord, why is it that none enter me except the weak and insignificant among the people?’ The Fire said—meaning—‘I have been favored with the arrogant.’ Allah, the Exalted, said to Paradise: ‘You are My mercy.’ And He said to the Fire: ‘You are My punishment; through you I afflict whomever I will. Each of you will have its fill.’ As for Paradise, Allah does not wrong anyone among His creation. And He creates for the Fire whomever He wills, and they are cast into it. It says three times: ‘Is there any more?’ until He places His Foot in it. Then it becomes full, its parts are drawn together, and it says: ‘Enough, enough, enough.’”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[13388],"tks":"متفق عليه: رواه البخاري (7449) ومسلم (2846)."},{"num":16537,"demo":false,"sanad":"","matn":["عَنْ حَارِثَةَ بْنِ وَهْبٍ الْخُزَاعِيِّ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: أَلاَ أُخْبِرُكُمْ بِأَهْلِ الْجَنَّةِ، كُلُّ ضَعِيفٍ مُتَضَاعِفٍ، لَوْ أَقْسَمَ عَلَى اللَّهِ لأَبَرَّهُ، أَلاَ أُخْبِرُكُمْ بِأَهْلِ النَّارِ؟ كُلُّ عُتُلٍّ جَوَّاظٍ مُسْتَكْبِرٍ."],"takhrij":"متفق عليه: رواه البخاري في الأدب (6071)، ومسلم في الجنة (2853) كلاهما من طريق معبد بن خالد القيسي، عن حارثة بن وهب الخزاعي، فذكره.","grade":"متفق عليه","chapter_ar":"باب يدخل الضعفاء الجنة والجبارون النار","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6071) and Muslim (2853).","chapter_en":"The Weak Will Enter Paradise and the Tyrannical Will Enter the Fire","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل الجنة وأهل النار معًا","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise and the People of the Fire Together","part_no":67,"group_no":6,"chapter_no":3,"content":{"translation":{"en":["Ḥārithah ibn Wahb al-Khuzāʿī narrated that the Prophet ﷺ said: “Shall I tell you about the people of Paradise? Every weak person who is regarded as weak; if he were to swear an oath by Allah, Allah would fulfill it for him. And shall I tell you about the people of the Fire? Every harsh, coarse, arrogant person.”"]}},"tuhfa":{},"full":1,"rep":[14972],"tks":"متفق عليه: رواه البخاري (6071)، ومسلم (2853)."},{"num":16538,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: احْتَجَّتِ الْجَنَّةُ وَالنَّارُ، فَقَالَتِ النَّارُ: فِيَّ الْجَبَّارُونَ وَالْمُتَكَبِّرُونَ، وَقَالَتِ الْجَنَّةُ: فِيَّ ضُعَفَاءُ النَّاسِ وَمَسَاكِينُهُمْ، قَالَ: فَقَضَى بَيْنَهُمَا، إِنَّكِ الْجَنَّةُ رَحْمَتِي أَرْحَمُ بِكِ مَنْ أَشَاءُ، وَإِنَّكِ النَّارُ عَذَابِي أُعَذِّبُ بِكِ مَنْ أَشَاءُ، وَلِكِلَاكُمَا عَلَيَّ مِلْؤُهَا."],"takhrij":"صحيح: رواه مسلم في الجنة وصفة نعيمها وأهلها (2847)، والإمام أحمد (11754) كلاهما عن عثمان بن محمد، حدثنا جرير، عن الأعمش، عن أبي صالح، عن أبي سعيد الخدري قال: فذكره.","grade":"صحيح","chapter_ar":"باب يدخل الضعفاء الجنة والجبارون النار","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2847) and Imām Aḥmad (11754). The wording is Aḥmad’s; Muslim did not quote the full wording.","chapter_en":"The Weak Will Enter Paradise and the Tyrannical Will Enter the Fire","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل الجنة وأهل النار معًا","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise and the People of the Fire Together","part_no":67,"group_no":6,"chapter_no":3,"content":{"translation":{"en":["Abū Saʿīd al-Khudrī narrated that the Messenger of Allah ﷺ said: “Paradise and the Fire disputed. The Fire said: ‘Within me are the tyrants and the arrogant.’ Paradise said: ‘Within me are the weak and poor among the people.’ Allah then judged between them: ‘You, Paradise, are My mercy; through you I show mercy to whomever I will. And you, Fire, are My punishment; through you I punish whomever I will. It is upon Me to fill each of you.’”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[13390],"tks":"صحيح: رواه مسلم (2847)، والإمام أحمد (11754) واللفظ لأحمد، ومسلم لم يسق لفظه."},{"num":16539,"demo":false,"sanad":"","matn":["عَنْ عِيَاضِ بْنِ حِمَارٍ الْمُجَاشِعِيِّ:  أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ ذَاتَ يَوْمٍ فِي خُطْبَتِهِ: أَلَا إِنَّ رَبِّي أَمَرَنِي أَنْ أُعَلِّمَكُمْ مَا جَهِلْتُمْ مِمَّا عَلَّمَنِي يَوْمِي هَذَا، كُلُّ مَالٍ نَحَلْتُهُ عَبْدًا حَلَالٌ، وَإِنِّي خَلَقْتُ عِبَادِي حُنَفَاءَ كُلَّهُمْ، وَإِنَّهُمْ أَتَتْهُمُ الشَّيَاطِينُ فَاجْتَالَتْهُمْ عَنْ دِينِهِمْ، وَحَرَّمَتْ عَلَيْهِمْ مَا أَحْلَلْتُ لَهُمْ، وَأَمَرَتْهُمْ أَنْ يُشْرِكُوا بِي مَا لَمْ أُنْزِلْ بِهِ سُلْطَانًا، وَإِنَّ اللَّهَ نَظَرَ إِلَى أَهْلِ الْأَرْضِ، فَمَقَتَهُمْ عَرَبَهُمْ وَعَجَمَهُمْ إِلَّا بَقَايَا مِنْ أَهْلِ الْكِتَابِ. وَقَالَ: إِنَّمَا بَعَثْتُكَ لِأَبْتَلِيَكَ وَأَبْتَلِيَ بِكَ، وَأَنْزَلْتُ عَلَيْكَ كِتَابًا لَا يَغْسِلُهُ الْمَاءُ، تَقْرَؤُهُ نَائِمًا وَيَقْظَانَ. وَإِنَّ اللَّهَ أَمَرَنِي أَنْ أُحَرِّقَ قُرَيْشًا. فَقُلْتُ: رَبِّ إِذًا يَثْلَغُوا رَأْسِي فَيَدَعُوهُ خُبْزَةً. قَالَ: اسْتَخْرِجْهُمْ كَمَا اسْتَخْرَجُوكَ، وَاغْزُهُمْ نُغْزِكَ، وَأَنْفِقْ فَسَنُنْفِقَ عَلَيْكَ، وَابْعَثْ جَيْشًا نَبْعَثْ خَمْسَةً مِثْلَهُ، وَقَاتِلْ بِمَنْ أَطَاعَكَ مَنْ عَصَاكَ. قَالَ: وَأَهْلُ الْجَنَّةِ ثَلَاثَةٌ: ذُو سُلْطَانٍ مُقْسِطٌ مُتَصَدِّقٌ مُوَفَّقٌ، وَرَجُلٌ رَحِيمٌ رَقِيقُ الْقَلْبِ لِكُلِّ ذِي قُرْبَى وَمُسْلِمٍ، وَعَفِيفٌ مُتَعَفِّفٌ ذُو عِيَالٍ. قَالَ: وَأَهْلُ النَّارِ خَمْسَةٌ: الضَّعِيفُ الَّذِي لَا زَبْرَ لَهُ، الَّذِينَ هُمْ فِيكُمْ تَبَعًا لَا يَبْتَغُونَ أَهْلًا وَلَا مَالًا، وَالْخَائِنُ الَّذِي لَا يَخْفَى لَهُ طَمَعٌ وَإِنْ دَقَّ إِلَّا خَانَهُ، وَرَجُلٌ لَا يُصْبِحُ وَلَا يُمْسِي إِلَّا وَهُوَ يُخَادِعُكَ عَنْ أَهْلِكَ وَمَالِكَ. وَذَكَرَ الْبُخْلَ أَوِ الْكَذِبَ، وَالشِّنْظِيرُ الْفَحَّاشُ. وَلَمْ يَذْكُرْ أَبُو غَسَّانَ فِي حَدِيثِهِ: وَأَنْفِقْ فَسَنُنْفِقَ عَلَيْكَ."],"takhrij":"صحيح: رواه مسلم في الجنة وصفة نعيمها (2865) من طرق عن معاذ بن هشام، حدثني أبي، عن قتادة، عن مطرف بن عبد الله بن الشخير، عن عياض بن حمار المجاشعي، فذكره.","grade":"صحيح","chapter_ar":"باب يدخل الضعفاء الجنة والجبارون النار","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2865).","chapter_en":"The Weak Will Enter Paradise and the Tyrannical Will Enter the Fire","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل الجنة وأهل النار معًا","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise and the People of the Fire Together","part_no":67,"group_no":6,"chapter_no":3,"content":{"translation":{"en":["ʿIyāḍ ibn Ḥimār al-Mujāshiʿī narrated that the Messenger of Allah ﷺ said one day in his sermon: “Indeed, my Lord has commanded me to teach you today what you did not know from what He has taught me. Every wealth that I have granted to a servant is lawful. I created all My servants inclining naturally toward the truth, but the devils came to them and turned them away from their religion. They prohibited for them what I had made lawful and commanded them to associate with Me that for which I had sent down no authority. Allah looked upon the people of the earth and detested them, Arabs and non-Arabs alike, except for remnants among the People of the Book. And He said: ‘I have only sent you in order to test you and test others through you. I have revealed to you a Book that water cannot wash away; you recite it while asleep and awake.’ Allah commanded me to burn Quraysh. I said: ‘My Lord, then they will crush my head and leave it like a loaf of bread.’ He said: ‘Drive them out as they drove you out. Fight them and We will support you. Spend and We will spend upon you. Send an army and We will send five times its number. Fight with those who obey you against those who disobey you.’ The people of Paradise are three: a ruler who is just, charitable, and guided to success; a merciful man whose heart is tender toward every relative and Muslim; and a chaste person who restrains himself despite having dependents. And the people of the Fire are five: the weak person who has no resolve, those who merely follow among you and seek neither family nor wealth; the treacherous person whose greed, however slight, never escapes him without his betraying it; and a man who morning and evening never ceases trying to deceive you regarding your family and wealth.” He also mentioned: “Miserliness—or lying—and the foul-mouthed, obscene person.” Abū Ghassān did not mention in his narration: “Spend and We will spend upon you.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (2865)."},{"num":16540,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عَمْرِو، أن رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِنَّ أَهْلَ النَّارِ كُلُّ جَعْظَرِيٍّ جَوَّاظٍ مُسْتَكْبِرٍ جَمَّاعٍ مَنَّاعٍ، وَأَهْلُ الْجَنَّةِ الضُّعَفَاءُ الْمَغْلُوبُونَ."],"takhrij":"صحيح: رواه أحمد (7010)، والحاكم (1200) كلاهما من طريق موسى بن علي قال: سمعت أبي يحدث عن عبد الله بن عمرو بن العاص، فذكره.","grade":"صحيح","chapter_ar":"باب يدخل الضعفاء الجنة والجبارون النار","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by Aḥmad (7010) and al-Ḥākim (2/499).","chapter_en":"The Weak Will Enter Paradise and the Tyrannical Will Enter the Fire","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل الجنة وأهل النار معًا","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise and the People of the Fire Together","part_no":67,"group_no":6,"chapter_no":3,"content":{"translation":{"en":["ʿAbdullāh ibn ʿAmr narrated that the Messenger of Allah ﷺ said: “The people of the Fire are every harsh, coarse, arrogant person, one who amasses wealth and withholds it. And the people of Paradise are the weak and oppressed.”"]},"buhuth":{"en":["The author explains that “jaʿẓarī” means a harsh and coarse person.","“Jawwāẓ” means one who walks with arrogance and conceit."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (7010)، والحاكم (1200)."},{"num":16541,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ شَقِيقٍ، عَنْ رَجُلٍ مِنْ أَصْحَابِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: أَلَا أَدُلُّكُمْ عَلَى أَهْلِ الْجَنَّةِ؟، قَالُوا: بَلَى، قَالَ: الضُّعَفَاءُ الْمُتَظَلِّمُونَ، ثُمَّ قَالَ: أَلَا أَدُلُّكُمْ عَلَى أَهْلِ النَّارِ؟، قَالُوا: بَلَى، قَالَ: كُلُّ شَدِيدٍ جَعْظَرِيٍّ."],"takhrij":"صحيح: رواه أحمد (23131) عن محمد بن جعفر، حدثنا شعبة، عن أبي بشر، عن عبد الله بن شقيق، فذكره.","grade":"صحيح","chapter_ar":"باب يدخل الضعفاء الجنة والجبارون النار","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by Aḥmad (23131).","chapter_en":"The Weak Will Enter Paradise and the Tyrannical Will Enter the Fire","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل الجنة وأهل النار معًا","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise and the People of the Fire Together","part_no":67,"group_no":6,"chapter_no":3,"content":{"translation":{"en":["ʿAbdullāh ibn Shaqīq narrated from a man among the Companions of the Prophet ﷺ that the Prophet ﷺ said: “Shall I direct you to the people of Paradise?” They replied: “Yes.” He said: “The weak who are oppressed.” Then he said: “Shall I direct you to the people of the Fire?” They replied: “Yes.” He said: “Every harsh, coarse person.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (23131)."},{"num":16542,"demo":false,"sanad":"","matn":["عَنْ سُرَاقَةَ بْنِ مَالِكِ بْنِ جُعْشُمٍ رَضِيَ اللَّهُ عَنْهُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، قَالَ: لَهُ: يَا سُرَاقَةُ، أَلَا أُخْبِرُكَ بِأَهْلِ الْجَنَّةِ وَأَهْلِ النَّارِ فَقُلْتُ: بَلَى يَا رَسُولَ اللَّهِ، فَقَالَ: أَمَّا أَهْلُ النَّارِ فَكُلُّ جَعْظَرِيٍّ جَوَّاظٌ مُسْتَكْبِرٌ، وَأَمَّا أَهْلُ الْجَنَّةِ فَالضُّعَفَاءُ الْمَغْلُوبُونَ."],"takhrij":"حسن: رواه الطبراني في الكبير (6589)، والحاكم (6597) كلاهما من طريق عبد الله بن صالح-، ورواه أيضا الحاكم (6597) من طريق زيد بن الحباب-، كلاهما (عبد الله بن صالح، وزيد بن الحباب) عن موسى بن علي بن رباح اللخمي، عن أبيه، عن سراقة بن مالك بن جعشم المدلجي، فذكره.","grade":"حسن","chapter_ar":"باب يدخل الضعفاء الجنة والجبارون النار","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Hasan: Narrated by al-Ṭabarānī in al-Muʿjam al-Kabīr (7/152) and al-Ḥākim (3/619).","chapter_en":"The Weak Will Enter Paradise and the Tyrannical Will Enter the Fire","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل الجنة وأهل النار معًا","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise and the People of the Fire Together","part_no":67,"group_no":6,"chapter_no":3,"content":{"translation":{"en":["Surāqah ibn Mālik ibn Juʿshum al-Mudlijī narrated that the Messenger of Allah ﷺ said: “O Surāqah, shall I tell you about the people of Paradise and the people of the Fire?” He replied: “Yes, O Messenger of Allah.” He said: “As for the people of the Fire, they are every harsh, coarse, arrogant person. As for the people of Paradise, they are the weak and oppressed.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطبراني في الكبير (6589)، والحاكم (6597)."},{"num":16543,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَلَا أُنَبِّئُكُمْ بِأَهْلِ الْجَنَّةِ؟ هُمُ الضُّعَفَاءُ الْمَظْلُومُونَ، أَلَا أُنَبِّئُكُمْ بِأَهْلِ النَّارِ؟ كُلُّ شَدِيدٍ جَعْظَرِيٍّ."],"takhrij":"حسن: رواه أحمد (8821) عن يحيى بن إسحاق قال: أخبرنا البراء بن عبدالله، عن عبد الله بن شقيق، عن أبي هريرة، قال: فذكره.","grade":"حسن","chapter_ar":"باب يدخل الضعفاء الجنة والجبارون النار","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (8821), Abū Yaʿlā (6127), al-Ṭabarānī in al-Muʿjam al-Awsaṭ (4275), and al-Bayhaqī in Shuʿab al-Īmān (7826).","chapter_en":"The Weak Will Enter Paradise and the Tyrannical Will Enter the Fire","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل الجنة وأهل النار معًا","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise and the People of the Fire Together","part_no":67,"group_no":6,"chapter_no":3,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “Shall I inform you about the people of Paradise? They are the weak and oppressed. Shall I inform you about the people of the Fire? Every harsh, coarse person.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (8821)، وأبو يعلى (6127)، والطبراني في الأوسط (4275)، والبيهقي في شعب الإيمان (7826)."},{"num":16544,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ قَالَ: أَلَا أُخْبِرُكُمْ بِأَهْلِ النَّارِ وَأَهْلِ الْجَنَّةِ؟ أَمَّا أَهْلُ الْجَنَّةِ، فَكُلُّ ضَعِيفٍ مُتَضَعِّفٍ، أَشْعَثَ ذِي طِمْرَيْنِ، لَوْ أَقْسَمَ عَلَى اللَّهِ لَأَبَرَّهُ، وَأَمَّا أَهْلُ النَّارِ، فَكُلُّ جَعْظَرِيٍّ جَوَّاظٍ، جَمَّاعٍ مَنَّاعٍ، ذِي تَبَعٍ."],"takhrij":"حسن: رواه أحمد (12476) عن حسن –وهو ابن موسى الأشيب-، حدثنا ابن لهيعة، عن أبي النضر، عن أنس بن مالك، فذكره.","grade":"حسن","chapter_ar":"باب يدخل الضعفاء الجنة والجبارون النار","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (12476) and Abū Yaʿlā (3987).","chapter_en":"The Weak Will Enter Paradise and the Tyrannical Will Enter the Fire","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل الجنة وأهل النار معًا","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise and the People of the Fire Together","part_no":67,"group_no":6,"chapter_no":3,"content":{"translation":{"en":["Anas ibn Mālik narrated that the Prophet ﷺ said: “Shall I tell you about the people of the Fire and the people of Paradise? As for the people of Paradise, they are every weak person regarded as weak, disheveled and wearing two worn garments; if he were to swear an oath by Allah, Allah would fulfill it for him. As for the people of the Fire, they are every harsh, coarse person who amasses and withholds wealth and has followers.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (12476) وأبو يعلى (3987)."},{"num":16545,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَلاَ أُخْبِرُكُمْ بِمَنْ يَحْرُمُ عَلَى النَّارِ أَوْ بِمَنْ تَحْرُمُ عَلَيْهِ النَّارُ، عَلَى كُلِّ قَرِيبٍ هَيِّنٍ لَيِّنٍ سَهْلٍ."],"takhrij":"حسن: رواه الترمذي (2488)، وأحمد (3938)، وأبو يعلى (5053)، وابن حبان (469، 470) كلهم من طريق موسى بن عقبة، عن عبد الله بن عمرو الأودي، عن عبد الله بن مسعود قال: فذكره. قال الترمذي: \"حسن غريب\".","grade":"حسن","chapter_ar":"باب يدخل الضعفاء الجنة والجبارون النار","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhī (2488), Aḥmad (3938), Abū Yaʿlā (5053), and Ibn Ḥibbān (470, 469).","chapter_en":"The Weak Will Enter Paradise and the Tyrannical Will Enter the Fire","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل الجنة وأهل النار معًا","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise and the People of the Fire Together","part_no":67,"group_no":6,"chapter_no":3,"content":{"translation":{"en":["ʿAbdullāh ibn Masʿūd narrated that the Messenger of Allah ﷺ said: “Shall I tell you about the one who will be forbidden to the Fire—or the one upon whom the Fire will be forbidden? It is every person who is approachable, gentle, and easy-going.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الترمذي (2488)، وأحمد (3938)، وأبو يعلى (5053)، وابن حبان (470، 469)."},{"num":16546,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: كَلِمَتَانِ حَبِيبَتَانِ إِلَى الرَّحْمَنِ، خَفِيفَتَانِ عَلَى اللِّسَانِ، ثَقِيلَتَانِ فِي الْمِيزَانِ، سُبْحَانَ اللَّهِ وَبِحَمْدِهِ، سُبْحَانَ اللَّهِ الْعَظِيمِ."],"takhrij":"متفق عليه: رواه البخاري في التوحيد (7563)، ومسلم في الذكر والدعاء (2694) كلاهما من طريق محمد بن فضيل، عن عمارة بن القعقاع، عن أبي زرعة، عن أبي هريرة قال: فذكره.","grade":"متفق عليه","chapter_ar":"باب في صفة العدل لله تعالى يوم القيامة","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (7563) and Muslim (2694).","chapter_en":"Concerning the Justice of Allah, the Exalted, on the Day of Resurrection","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل الجنة وأهل النار معًا","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise and the People of the Fire Together","part_no":67,"group_no":6,"chapter_no":4,"content":{"translation":{"en":["Abū Hurayrah narrated that the Prophet ﷺ said: “Two phrases are beloved to the Most Merciful, light upon the tongue, and heavy upon the Scale: Subḥān Allāhi wa biḥamdih — Glory and praise be to Allah. Subḥān Allāhil-ʿAẓīm — Glory be to Allah, the Magnificent.”"]},"intro":{"ar":["قال تعالى:","﴿وَنَضَعُ الْمَوَازِينَ الْقِسْطَ لِيَوْمِ الْقِيَامَةِ فَلَا تُظْلَمُ نَفْسٌ شَيْئًا وَإِنْ كَانَ مِثْقَالَ حَبَّةٍ مِنْ خَرْدَلٍ أَتَيْنَا بِهَا وَكَفَىٰ بِنَا حَاسِبِينَ﴾ [الأنبياء: ٤٧].","يخبر اللّه تعالى عن عدله، وقضائه القسط بين عباده إذا جمعهم يوم القيامة."],"en":["Allah, the Exalted, says:","“We will set up the scales of justice for the Day of Resurrection, so no soul will be wronged in the least. Even if a deed is the weight of a mustard seed, We will bring it forth. And sufficient are We as Reckoners.”","[al-Anbiyāʾ 21:47]","Allah, the Exalted, informs us of His perfect justice and His judging with equity between His servants when He gathers them on the Day of Resurrection."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (7563)، ومسلم (2694)."}]);